    const retry = document.createElement("button");
    retry.type = "button";
    retry.textContent = "Retry";

    retry.addEventListener("click", async () => {
      retry.disabled = true;

      try {
        if (await onRetry()) {
          box.remove();
          activeWarning = null;
        } else {
          retry.disabled = false;
          text.textContent = "Still unable to save entries.";
        }
      } catch {
        retry.disabled = false;
        text.textContent = "Still unable to save entries.";
      }
    });

    box.append(" ", retry);
  }

  document.body.append(box);
  activeWarning = box;

  setTimeout(() => {
    if (activeWarning === box) {
      box.remove();
      activeWarning = null;
    }
  }, 5000);
}
