  const box = document.createElement("div");
  box.className = "storage-warning";
  box.setAttribute("role", "alert");

  const text = document.createElement("span");
  text.textContent = message;
  box.append(text);

  const retry = document.createElement("button");
  retry.type = "button";
  retry.textContent = "Retry";

  retry.addEventListener("click", async () => {
    if (signal?.aborted) return;

    retry.disabled = true;

    let saved = false;
    try {
      saved = await onRetry();
    } catch {
      saved = false;
    }

    // The app may have been reinitialised while saving was in progress.
    if (signal?.aborted || warningNode !== box) return;

    if (saved) {
      clearWarning();
    } else {
      text.textContent = "Still unable to save entries.";
      retry.disabled = false;
    }
  }, { signal });

  box.append(" ", retry);
  document.body.append(box);
  warningNode = box;

  const abortHandler = () => clearWarning();
  signal?.addEventListener("abort", abortHandler, { once: true });
  removeWarningAbortListener = () =>
    signal?.removeEventListener("abort", abortHandler);

  warningTimer = setTimeout(() => {
    if (warningNode === box) clearWarning();
  }, 5000);
}

function initApp() {
  appController?.abort();
  appController = new AbortController();

  const { signal } = appController;

  try {
    state.storage = globalThis.localStorage;
  } catch {
    state.storage = null;
  }

  const result = loadAndNormaliseEntries({
    storage: state.storage,
    onWarning: (message) =>
      showWarning(message, saveCurrentEntries, signal),
  });

  state.entries = result.entries;
  renderEntries(state.entries);
}
```

