Use one save manager per app run; aborting that run cancels its timer and resolves every queued caller as `false`. The failure callback receives a retry function belonging to that manager, so an aborted manager can never create a warning for a newer run.

```js
function createSaveManager({ signal, saveNow, onFailure, delay = 300 }) {
  let timer = null;
  let waiters = [];
  let closed = false;

  function attemptSave() {
    if (closed || signal.aborted) return false;

    try {
      return saveNow() === true;
    } catch {
      return false;
    }
  }

  function retry() {
    if (closed || signal.aborted) return false;

    const saved = attemptSave();

    if (!saved && !closed && !signal.aborted) {
      onFailure(retry);
    }

    return saved;
  }

  function flush() {
    timer = null;
    if (closed || signal.aborted) return;

    const saved = attemptSave();
    const currentWaiters = waiters;
    waiters = [];

    currentWaiters.forEach((resolve) => resolve(saved));

    if (!saved && !closed && !signal.aborted) {
      onFailure(retry);
    }
  }

  function request() {
    return new Promise((resolve) => {
      if (closed || signal.aborted) {
        resolve(false);
        return;
      }

      waiters.push(resolve);
      clearTimeout(timer);
      timer = setTimeout(flush, delay);
    });
  }

  function cancel() {
    if (closed) return;

    closed = true;
    clearTimeout(timer);
    timer = null;

    const currentWaiters = waiters;
    waiters = [];
    currentWaiters.forEach((resolve) => resolve(false));
  }

  signal.addEventListener("abort", cancel, { once: true });

  return { request, cancel };
}
```

