Yes—flush on `visibilitychange` as the primary opportunity, with `pagehide`/`beforeunload` as fallbacks. Make `flush()` a no-op when there is no pending debounced save, so the second lifecycle event cannot write twice:

```js
let dirty = false;

function request() {
  return new Promise(resolve => {
    if (closed || signal.aborted) return resolve(false);

    dirty = true;
    waiters.push(resolve);
    clearTimeout(timer);
    timer = setTimeout(() => flush(), delay);
  });
}

function flush(notify = true) {
  if (closed || signal.aborted || !dirty) return true;

  clearTimeout(timer);
  timer = null;
  dirty = false;

  const saved = attemptSave();
  const currentWaiters = waiters;
  waiters = [];
  currentWaiters.forEach(resolve => resolve(saved));

  if (!saved && notify && !closed && !signal.aborted) onFailure(retry);
  return saved;
}
```

Then register the lifecycle handlers once per app run:

```js
const flushQuietly = () => manager.flush(false);

document.addEventListener("visibilitychange", () => {
  if (document.visibilityState === "hidden") flushQuietly();
}, { signal });

window.addEventListener("pagehide", flushQuietly, { signal });
window.addEventListener("beforeunload", flushQuietly, { signal });
```

`visibilitychange` is generally the best signal, while the other two provide fallback coverage; `localStorage` writes are synchronous, but no unload mechanism is guaranteed in every browser.

