function getRequired(selector) {
  const element = document.querySelector(selector);

  if (!element) {
    console.error(`Required element not found: ${selector}`);
  }

  return element;
}

function initApp() {
  const app = document.querySelector("#app");
  const form = getRequired("#maintenance-form");
  const dateInput = getRequired("#date");
  const taskInput = getRequired("#task");
  const notesInput = getRequired("#notes");
  const list = getRequired("#maintenance-list");

  const requiredElements = [app, form, dateInput, taskInput, notesInput, list];

  if (requiredElements.some((element) => !element)) {
    app?.insertAdjacentHTML(
      "afterbegin",
      `<p role="alert">The maintenance form could not be loaded. Please refresh the page.</p>`
    );
    return;
  }

  const entries = [];

  function renderEntries() {
    list.innerHTML = entries.map((entry) => `
      <li>
        <strong>${entry.date} — ${entry.task}</strong>
        <p>${entry.notes}</p>
      </li>
    `).join("");
  }

  form.addEventListener("submit", (event) => {
    event.preventDefault();

    entries.push({
      date: dateInput.value,
      task: taskInput.value,
      notes: notesInput.value
    });

    renderEntries();
    form.reset();
  });
}

document.addEventListener("DOMContentLoaded", initApp);
```

If your script uses `defer`, calling `initApp()` directly is also sufficient; using `DOMContentLoaded` is harmless but not required.

```js
const selectors = {
  app: "#app",
  form: "#maintenance-form",
  dateInput: "#date",
  taskInput: "#task",
  notesInput: "#notes",
  list: "#maintenance-list"
};

function initApp() {
  const elements = Object.fromEntries(
    Object.entries(selectors).map(([name, selector]) => [
      name,
      document.querySelector(selector)
    ])
  );

  const missing = Object.entries(elements)
    .filter(([, element]) => !element)
    .map(([name]) => `${name} (${selectors[name]})`);

  if (missing.length) {
    console.error(`App initialization failed. Missing elements: ${missing.join(", ")}`);

    if (elements.app) {
      elements.app.querySelector("[data-app-error]")?.remove();

      const message = document.createElement("p");
      message.dataset.appError = "true";
      message.setAttribute("role", "alert");
      message.textContent =
        "The maintenance form could not be loaded. Please refresh the page.";
      elements.app.prepend(message);
    }

    return;
  }

  const { app, form, dateInput, taskInput, notesInput, list } = elements;
  const entries = [];

  function renderEntries() {
    list.innerHTML = entries.map((entry) => `
      <li>
        <strong>${entry.date} — ${entry.task}</strong>
        <p>${entry.notes}</p>
      </li>
    `).join("");
  }

  form.addEventListener("submit", (event) => {
    event.preventDefault();

    entries.push({
      date: dateInput.value,
      task: taskInput.value,
      notes: notesInput.value
    });

    renderEntries();
    form.reset();
  });
}

document.addEventListener("DOMContentLoaded", initApp);
```

The single `console.error` lists every missing selector, while removing the previous `[data-app-error]` prevents duplicate friendly messages if initialization is retried.

