```js
function loadAndNormaliseEntries({
  storage = null,
  onWarning = (message) => console.warn(message),
} = {}) {
  const key = "entries";
  let parsed = [];
  let changed = false;
  let canRead = true;

  if (storage === null) {
    try {
      storage = globalThis.localStorage;
    } catch {
      storage = null;
    }
  }

  if (storage) {
    try {
      const raw = storage.getItem(key);

      if (raw !== null) {
        parsed = JSON.parse(raw);
      }
    } catch {
      canRead = false;
      onWarning("Saved entries could not be read; using an empty in-memory list.");
    }
  } else {
    canRead = false;
    onWarning("Storage is unavailable; entries will remain in memory for this session.");
  }

  if (!Array.isArray(parsed)) {
    parsed = [];
    changed = true;
  }

  const usedIds = new Set();
  const entries = [];

  for (const value of parsed) {
    if (value === null || typeof value !== "object" || Array.isArray(value)) {
      changed = true;
      continue;
    }

    const entry = value;

    if (
      typeof entry.id !== "string" ||
      entry.id.length === 0 ||
      usedIds.has(entry.id)
    ) {
      entry.id = createId(usedIds);
      changed = true;
    } else {
      usedIds.add(entry.id);
    }

    entries.push(entry);
  }

  if (canRead && changed) {
    try {
      storage.setItem(key, JSON.stringify(entries));
    } catch {
      onWarning("Entries could not be saved; continuing with the in-memory list.");
    }
  }

  return { entries, usedIds };
}
```

