```python
def scan_filenames(filenames):
    """Return results in the same order as the input filenames."""
    results = []

    for original in filenames:
        try:
            file_date, client = parse_filename(os.fspath(original))
        except ValueError as exc:
            results.append({
                "status": "error",
                "path": os.fspath(original),
                "error": str(exc),
            })
        else:
            results.append({
                "status": "ok",
                "path": os.fspath(original),
                "date": file_date.isoformat(),
                "client": client,
            })

    return results


def main(argv=None):
    parser = argparse.ArgumentParser()
    output_group = parser.add_mutually_exclusive_group()
    output_group.add_argument("--json-errors", action="store_true")
    output_group.add_argument(
        "--jsonl",
        action="store_true",
        help="emit successes and errors as one ordered JSONL stream",
    )
    parser.add_argument("files", nargs="+", type=Path)

    args = parser.parse_args(
        None if argv is None else [os.fspath(item) for item in argv]
    )

    results = scan_filenames(args.files)
    rejected = [result for result in results if result["status"] == "error"]

    if args.jsonl:
        for result in results:
            print(json.dumps(
                result,
                ensure_ascii=False,
                separators=(",", ":"),
            ))
    else:
        for result in results:
            if result["status"] == "ok":
                print(json.dumps(
                    {
                        "path": result["path"],
                        "date": result["date"],
                        "client": result["client"],
                    },
                    ensure_ascii=False,
                    separators=(",", ":"),
                ))
            elif args.json_errors:
                print(json.dumps(
                    {
                        "path": result["path"],
                        "error": result["error"],
                    },
                    ensure_ascii=False,
                    separators=(",", ":"),
                ), file=sys.stderr)
            else:
                print(
                    f"ERROR: invalid filename: "
                    f"{result['path']} ({result['error']})",
                    file=sys.stderr,
                )

    return 1 if rejected else 0
```

