`Temporal.TimeZone.from` is not available in newer versions of `@js-temporal/polyfill`; don’t pin an older version. Use `Temporal.ZonedDateTime.from` with `"earlier"` and `"later"` to classify the transition:

```ts
import { Temporal } from "@js-temporal/polyfill";

export class LocalDateTimeError extends Error {
  constructor(
    message: string,
    public readonly code:
      | "INVALID_INPUT"
      | "NONEXISTENT_TIME"
      | "AMBIGUOUS_TIME",
    options?: { cause?: unknown },
  ) {
    super(message, options);
    this.name = "LocalDateTimeError";
  }
}

export function localDateTimeToUtc(
  date: string,
  time: string,
  timeZone: string,
): string {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(date) || !/^\d{2}:\d{2}$/.test(time)) {
    throw new LocalDateTimeError(
      "Date must be YYYY-MM-DD and time must be HH:mm",
      "INVALID_INPUT",
    );
  }

  let plainDateTime: Temporal.PlainDateTime;
  let earlier: Temporal.ZonedDateTime;
  let later: Temporal.ZonedDateTime;

  try {
    // Strictly rejects dates such as 2026-02-30.
    plainDateTime = Temporal.PlainDateTime.from(`${date}T${time}:00`);

    const value = `${date}T${time}:00[${timeZone}]`;
    earlier = Temporal.ZonedDateTime.from(value, {
      disambiguation: "earlier",
    });
    later = Temporal.ZonedDateTime.from(value, {
      disambiguation: "later",
    });
  } catch (cause) {
    throw new LocalDateTimeError(
      `Invalid date, time, or IANA timezone (${timeZone})`,
      "INVALID_INPUT",
      { cause },
    );
  }

  const earlierMatches = earlier
    .toPlainDateTime()
    .equals(plainDateTime);
  const laterMatches = later
    .toPlainDateTime()
    .equals(plainDateTime);

  if (!earlierMatches && !laterMatches) {
    throw new LocalDateTimeError(
      `${date} ${time} does not exist in ${timeZone} because of a DST transition`,
      "NONEXISTENT_TIME",
    );
  }

  if (
    earlierMatches &&
    laterMatches &&
    !earlier.toInstant().equals(later.toInstant())
  ) {
    throw new LocalDateTimeError(
      `${date} ${time} is ambiguous in ${timeZone}; choose the earlier or later occurrence`,
      "AMBIGUOUS_TIME",
    );
  }

  return (earlierMatches ? earlier : later).toInstant().toString();
}
```

