Yes—the comparison is based on Temporal’s possible instants, not on whether the transition is labeled “DST,” so it also handles political or historical offset changes. In current polyfill versions there is no public `TimeZone.getPossibleInstantsFor()` API; constructing with `"earlier"` and `"later"` is the compatible way to classify zero, one, or two instants:

```ts
import { Temporal } from "@js-temporal/polyfill";

export class LocalDateTimeError extends Error {
  constructor(
    message: string,
    public readonly code:
      | "INVALID_INPUT"
      | "NONEXISTENT_TIME"
      | "AMBIGUOUS_TIME",
    options?: { cause?: unknown },
  ) {
    super(message);
    this.name = "LocalDateTimeError";
    this.cause = options?.cause;
  }

  declare readonly cause?: unknown;
}

export function localDateTimeToUtc(
  date: string,
  time: string,
  timeZone: string,
): string {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(date) || !/^\d{2}:\d{2}$/.test(time)) {
    throw new LocalDateTimeError(
      "Date must be YYYY-MM-DD and time must be HH:mm",
      "INVALID_INPUT",
    );
  }

  const value = `${date}T${time}:00[${timeZone}]`;

  let plainDateTime: Temporal.PlainDateTime;
  let earlier: Temporal.ZonedDateTime;
  let later: Temporal.ZonedDateTime;

  try {
    // Rejects invalid calendar dates such as February 30.
    plainDateTime = Temporal.PlainDateTime.from(`${date}T${time}:00`);

    earlier = Temporal.ZonedDateTime.from(value, {
      disambiguation: "earlier",
    });
    later = Temporal.ZonedDateTime.from(value, {
      disambiguation: "later",
    });
  } catch (cause) {
    throw new LocalDateTimeError(
      `Invalid date, time, or IANA timezone (${timeZone})`,
      "INVALID_INPUT",
      { cause },
    );
  }

  const earlierMatches = earlier.toPlainDateTime().equals(plainDateTime);
  const laterMatches = later.toPlainDateTime().equals(plainDateTime);
  const sameInstant = earlier.toInstant().equals(later.toInstant());

  // Zero possible instants: both disambiguations normalize away from
  // the requested wall-clock time.
  if (!earlierMatches && !laterMatches) {
    throw new LocalDateTimeError(
      `${date} ${time} does not exist in ${timeZone} because of an offset transition`,
      "NONEXISTENT_TIME",
    );
  }

  // Two possible instants: both preserve the wall-clock value but differ
  // in their resulting instants.
  if (earlierMatches && laterMatches && !sameInstant) {
    throw new LocalDateTimeError(
      `${date} ${time} is ambiguous in ${timeZone}; choose the earlier or later occurrence`,
      "AMBIGUOUS_TIME",
    );
  }

  // One possible instant. In the normal case both values are identical;
  // the conditional also handles Temporal's representation safely.
  return (earlierMatches ? earlier : later).toInstant().toString();
}
```

