Save this as `Compare-Backup.ps1`, changing the three paths at the top; it creates dated manifests and a discrepancy report, then prints a clear result without modifying either source:

```powershell
$PcRoot     = "C:\Users\YourName\ReferenceFiles"
$ExternalRoot = "E:\ReferenceFiles"
$ReportRoot = "C:\BackupReports"

$date = Get-Date -Format "yyyy-MM-dd"
New-Item -ItemType Directory -Force -Path $ReportRoot | Out-Null

function Get-Manifest($Root) {
    $rootFull = (Resolve-Path $Root).Path.TrimEnd('\')
    $map = @{}
    Get-ChildItem -LiteralPath $rootFull -File -Recurse | ForEach-Object {
        $rel = $_.FullName.Substring($rootFull.Length).TrimStart('\')
        $map[$rel] = (Get-FileHash -LiteralPath $_.FullName -Algorithm SHA256).Hash
    }
    return $map
}

$pc = Get-Manifest $PcRoot
$external = Get-Manifest $ExternalRoot

$pc.GetEnumerator() | ForEach-Object {
    [PSCustomObject]@{ RelPath = $_.Key; Hash = $_.Value }
} | Export-Csv "$ReportRoot\$date`__ReferenceFiles__PC-SHA256.csv" -NoTypeInformation

$external.GetEnumerator() | ForEach-Object {
    [PSCustomObject]@{ RelPath = $_.Key; Hash = $_.Value }
} | Export-Csv "$ReportRoot\$date`__ReferenceFiles__External-SHA256.csv" -NoTypeInformation

$differences = foreach ($rel in ($pc.Keys + $external.Keys | Sort-Object -Unique)) {
    if (-not $pc.ContainsKey($rel)) {
        [PSCustomObject]@{ RelPath=$rel; Status="MissingOnPC"; PCHash=""; ExternalHash=$external[$rel] }
    } elseif (-not $external.ContainsKey($rel)) {
        [PSCustomObject]@{ RelPath=$rel; Status="MissingOnExternal"; PCHash=$pc[$rel]; ExternalHash="" }
    } elseif ($pc[$rel] -ne $external[$rel]) {
        [PSCustomObject]@{ RelPath=$rel; Status="HashMismatch"; PCHash=$pc[$rel]; ExternalHash=$external[$rel] }
    }
}

$report = "$ReportRoot\$date`__ReferenceFiles__Comparison.csv"
$differences | Export-Csv $report -NoTypeInformation

if ($differences) {
    Write-Host "FAIL: $($differences.Count) discrepancy/discrepancies found. Report: $report" -ForegroundColor Red
    exit 1
} else {
    Write-Host "PASS: paths and SHA-256 hashes match. Reports saved in $ReportRoot" -ForegroundColor Green
    exit 0
}
