                ExternalHash = ""
            }
        }
        elseif ($pc[$rel] -ne $external[$rel]) {
            [PSCustomObject]@{
                RelPath      = $rel
                Status       = "HashMismatch"
                PCHash       = $pc[$rel]
                ExternalHash = $external[$rel]
            }
        }
    }
)

$differences | Export-Csv $report -NoTypeInformation

$summaryLines = @(
    "Reference backup comparison"
    "Date: $(Get-Date -Format 'yyyy-MM-dd HH:mm:ss')"
    "Backup drive: $externalDriveName"
    ""
    "PC files: $($pc.Count)"
    "External files: $($external.Count)"
    "Discrepancies: $($differences.Count)"
    ""
)

if ($differences.Count -gt 0) {
    $summaryLines += "Result: FAIL"
    $summaryLines += ""
    $summaryLines += "First discrepancies:"

    $differences | Select-Object -First 5 | ForEach-Object {
        $summaryLines += "- $($_.Status): $($_.RelPath)"
    }

    if ($differences.Count -gt 5) {
        $summaryLines += "...and $($differences.Count - 5) more; see the CSV report."
    }
} else {
    $summaryLines += "Result: PASS — paths and SHA-256 hashes match."
}

$summaryLines | Set-Content -LiteralPath $summary -Encoding UTF8

if ($differences.Count -gt 0) {
    Write-Host "FAIL: $($differences.Count) discrepancy/discrepancies found." -ForegroundColor Red
    Write-Host "Summary: $summary"
    Write-Host "CSV report: $report"
    exit 1
}

Write-Host "PASS: paths and SHA-256 hashes match." -ForegroundColor Green
Write-Host "Backup drive: $externalDriveName"
Write-Host "Summary: $summary"
exit 0
```

The exit codes are now `0` for a clean match, `1` for hash/path discrepancies, and `2` for a missing or inaccessible location or hashing error.

Use the date-input value unchanged for errands, and keep the appointment’s wall-clock fields plus IANA timezone alongside the normalized instant (using `date-fns-tz`):

```ts
import { fromZonedTime, formatInTimeZone } from "date-fns-tz";

type Errand = {
  kind: "errand";
  id: string;
  title: string;
  date: string; // YYYY-MM-DD
};

type Appointment = {
  kind: "appointment";
  id: string;
  title: string;
  date: string;      // selected local date, YYYY-MM-DD
  time: string;      // selected local time, HH:mm
  timeZone: string;  // e.g. "America/Los_Angeles"
  startsAt: string;  // canonical UTC ISO timestamp
};

type CalendarItem = Errand | Appointment;

export function createErrand(
  id: string,
  title: string,
  date: string,
): Errand {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(date)) throw new Error("Invalid date");
  return { kind: "errand", id, title, date };
}

export function createAppointment(
  id: string,
  title: string,
  date: string,
  time: string,
  timeZone: string,
): Appointment {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(date) || !/^\d{2}:\d{2}$/.test(time)) {
    throw new Error("Invalid date or time");
  }

  const startsAt = fromZonedTime(`${date}T${time}:00`, timeZone).toISOString();
  return { kind: "appointment", id, title, date, time, timeZone, startsAt };
}

export function saveItem(item: CalendarItem): string {
  return JSON.stringify(item);
}

export function loadItem(json: string): CalendarItem {
  return JSON.parse(json) as CalendarItem;
}

export function displayAppointment(item: Appointment): string {
  return formatInTimeZone(item.startsAt, item.timeZone, "MMM d, yyyy h:mm a zzz");
}
```

Install the dependency with `npm install date-fns-tz`; also validate that the chosen timezone is an IANA identifier and decide how your UI should handle ambiguous or nonexistent times during daylight-saving transitions.

`fromZonedTime` generally normalizes nonexistent DST times rather than reliably throwing, so validate by converting the result back into the requested timezone and comparing the wall-clock value:

```ts
import { fromZonedTime, formatInTimeZone } from "date-fns-tz";

export function validateLocalDateTime(
  date: string,
  time: string,
  timeZone: string,
): void {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(date) || !/^\d{2}:\d{2}$/.test(time)) {
    throw new Error("Invalid date or time format");
  }

  try {
    new Intl.DateTimeFormat("en-US", { timeZone }).format();
  } catch {
    throw new Error(`Invalid IANA timezone: ${timeZone}`);
  }

  const requested = `${date}T${time}:00`;
  const instant = fromZonedTime(requested, timeZone);

  if (Number.isNaN(instant.getTime())) {
    throw new Error("Invalid local date/time");
  }

  const roundTripped = formatInTimeZone(
    instant,
    timeZone,
    "yyyy-MM-dd'T'HH:mm",
  );

  if (roundTripped !== `${date}T${time}`) {
    throw new Error("This local time does not exist in the selected timezone");
  }
}
```

This rejects spring-forward gaps and invalid calendar dates; fall-back times are ambiguous but usually accepted using the library’s chosen occurrence, so ask the user to select an offset if that distinction matters.

The round-trip check will usually catch `2026-02-30`, but validate the calendar date explicitly rather than relying on parser normalization. The simplest strict solution is the Temporal polyfill, whose `disambiguation: "reject"` rejects both nonexistent spring-forward times and ambiguous fall-back times:

```ts
import { Temporal } from "@js-temporal/polyfill";

export function validateLocalDateTime(
  date: string,
  time: string,
  timeZone: string,
): string {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(date) || !/^\d{2}:\d{2}$/.test(time)) {
    throw new Error("Invalid date or time format");
  }

  try {
    const zoned = Temporal.ZonedDateTime.from(
      `${date}T${time}[${timeZone}]`,
      { disambiguation: "reject" },
    );
    return zoned.toInstant().toString(); // canonical UTC ISO timestamp
  } catch {
    throw new Error(
      "Invalid timezone, impossible date/time, or ambiguous DST time",
    );
  }
}
```

Install it with `npm install @js-temporal/polyfill`; if you prefer to allow fall-back times, use `disambiguation: "earlier"` or `"later"` and store which choice was made.

```ts
import { Temporal } from "@js-temporal/polyfill";

export class LocalDateTimeError extends Error {
  constructor(
    message: string,
    public readonly code: "INVALID_INPUT" | "NONEXISTENT_TIME" | "AMBIGUOUS_TIME",
    options?: { cause?: unknown },
  ) {
    super(message);
    this.name = "LocalDateTimeError";
    this.cause = options?.cause;
  }

  declare readonly cause?: unknown;
}

export function localDateTimeToUtc(
  date: string,
  time: string,
  timeZone: string,
): string {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(date) || !/^\d{2}:\d{2}$/.test(time)) {
    throw new LocalDateTimeError(
      "Date must be YYYY-MM-DD and time must be HH:mm",
      "INVALID_INPUT",
    );
  }

  let plainDateTime: Temporal.PlainDateTime;
  let zone: Temporal.TimeZone;

  try {
    // Strictly validates calendar dates such as 2026-02-30.
    plainDateTime = Temporal.PlainDateTime.from(`${date}T${time}:00`);
    zone = Temporal.TimeZone.from(timeZone);
  } catch (cause) {
    throw new LocalDateTimeError(
      `Invalid date, time, or IANA timezone (${timeZone})`,
      "INVALID_INPUT",
      { cause },
    );
  }

  const possibleInstants = zone.getPossibleInstantsFor(plainDateTime);

  if (possibleInstants.length === 0) {
    throw new LocalDateTimeError(
      `${date} ${time} does not exist in ${timeZone} because of a DST transition`,
      "NONEXISTENT_TIME",
    );
  }

  if (possibleInstants.length > 1) {
    throw new LocalDateTimeError(
      `${date} ${time} is ambiguous in ${timeZone}; choose the earlier or later occurrence`,
      "AMBIGUOUS_TIME",
    );
  }

  return possibleInstants[0].toString(); // e.g. 2026-01-15T17:00:00Z
}
```

`getPossibleInstantsFor()` returns zero instants for a spring-forward gap, two for a fall-back ambiguity, and one for a valid local time; callers can inspect `error.code`, while any original parsing/timezone exception remains available as `error.cause`.

Using Vitest, these tests cover the DST gap, repeated fall-back time, invalid calendar date, and a valid conversion:

```ts
// localDateTimeToUtc.test.ts
import { describe, expect, it } from "vitest";
import {
  localDateTimeToUtc,
  LocalDateTimeError,
} from "./localDateTimeToUtc";

describe("localDateTimeToUtc", () => {
  const zone = "America/Los_Angeles";

  it("rejects a nonexistent spring-forward time", () => {
    expect(() =>
      localDateTimeToUtc("2026-03-08", "02:30", zone),
    ).toThrowError(LocalDateTimeError);

    try {
      localDateTimeToUtc("2026-03-08", "02:30", zone);
    } catch (error) {
      expect(error).toBeInstanceOf(LocalDateTimeError);
      expect((error as LocalDateTimeError).code).toBe("NONEXISTENT_TIME");
      expect((error as LocalDateTimeError).message).toContain(
        "does not exist",
      );
    }
  });

  it("rejects an ambiguous fall-back time", () => {
    expect(() =>
      localDateTimeToUtc("2026-11-01", "01:30", zone),
    ).toThrowError(LocalDateTimeError);

    try {
      localDateTimeToUtc("2026-11-01", "01:30", zone);
    } catch (error) {
      expect((error as LocalDateTimeError).code).toBe("AMBIGUOUS_TIME");
      expect((error as LocalDateTimeError).message).toContain("ambiguous");
    }
  });

  it("rejects an impossible calendar date and preserves the cause", () => {
