$pcManifestFile = Join-Path $ReportRoot "${date}__ReferenceFiles__PC-SHA256.csv"
$externalManifestFile = Join-Path $ReportRoot "${date}__ReferenceFiles__External-SHA256.csv"

function Get-DriveName($Path) {
    try {
        $qualifier = Split-Path -Path $Path -Qualifier
        if ($qualifier -match '^[A-Za-z]:$') {
            $volume = Get-Volume -DriveLetter $qualifier.Substring(0, 1) -ErrorAction Stop
            if ($volume.FileSystemLabel) {
                return "$($volume.FileSystemLabel) ($qualifier)"
            }
            return "Unlabelled drive ($qualifier)"
        }
    } catch {
        return "Unavailable ($Path)"
    }
    return "Not a local drive ($Path)"
}

function Get-ValidatedRoot($Path, $Label) {
    if (-not (Test-Path -LiteralPath $Path -PathType Container -ErrorAction Stop)) {
        throw "$Label folder was not found or is not a folder: $Path"
    }

    $resolved = (Resolve-Path -LiteralPath $Path -ErrorAction Stop).Path.TrimEnd('\')

    # Forces an access check while still allowing an empty folder.
    Get-ChildItem -LiteralPath $resolved -Force -ErrorAction Stop |
        Select-Object -First 1 | Out-Null

    [PSCustomObject]@{
        Path      = $resolved
        DriveName = Get-DriveName $resolved
    }
}

function Get-Manifest($Root) {
    $map = @{}

    Get-ChildItem -LiteralPath $Root -File -Recurse -Force -ErrorAction Stop |
        ForEach-Object {
            $relative = $_.FullName.Substring($Root.Length).TrimStart('\')
            $map[$relative] = (Get-FileHash -LiteralPath $_.FullName `
                -Algorithm SHA256 -ErrorAction Stop).Hash
        }

    return $map
}

$externalDriveName = Get-DriveName $ExternalRoot
$validationErrors = @()

try {
    $pcInfo = Get-ValidatedRoot $PcRoot "PC"
} catch {
    $validationErrors += $_.Exception.Message
}

try {
    $externalInfo = Get-ValidatedRoot $ExternalRoot "External drive"
    $externalDriveName = $externalInfo.DriveName
} catch {
    $validationErrors += $_.Exception.Message
}

if ($validationErrors.Count -gt 0) {
    $summaryLines = @(
        "Reference backup comparison"
        "Date: $(Get-Date -Format 'yyyy-MM-dd HH:mm:ss')"
        "Backup drive: $externalDriveName"
        ""
        "Result: FAIL — folder or drive unavailable."
        ""
        "Errors:"
    )

    $validationErrors | ForEach-Object {
        $summaryLines += "- $_"
    }

    $summaryLines | Set-Content -LiteralPath $summary -Encoding UTF8

    Write-Host "FAIL: PC or external backup location is unavailable." -ForegroundColor Red
    Write-Host "Summary: $summary"
    exit 2
}

try {
