Create a `PreFilingCheck` sheet and maintain `MAP` with every dashboard figure and its authoritative source cell; the script below flags formula errors/blanks, compares mapped values, and creates a dated backup before final edits:

```javascript
const MAP = [
  // Add every dashboard figure here:
  { dashboard: "B5", source: "'Income'!B20", label: "Total income" },
  { dashboard: "B6", source: "'Reimbursements'!B12", label: "Reimbursements" },
  { dashboard: "B7", source: "'Equipment'!B18", label: "Equipment deductions" },
  { dashboard: "B10", source: "'Carryforward'!B10", label: "Approved carryforward" }
];

function preFilingExportCheck() {
  const ss = SpreadsheetApp.getActive();
  const dash = ss.getSheetByName("Dashboard");
  const output = ss.getSheetByName("PreFilingCheck") || ss.insertSheet("PreFilingCheck");
  const results = [["Timestamp", "Type", "Item", "Dashboard value", "Source value", "Result"]];

  const used = dash.getDataRange();
  const formulas = used.getFormulas();
  const displays = used.getDisplayValues();

  formulas.forEach((row, r) => row.forEach((formula, c) => {
    if (!formula) return;
    const value = displays[r][c].trim();
    const result = /^#(REF|DIV\/0|N\/A|VALUE|NAME|NUM|NULL|ERROR)/.test(value)
      ? "ERROR"
      : value === "" ? "BLANK" : "OK";
    if (result !== "OK")
      results.push([new Date(), "Dashboard formula", dash.getRange(r + 1, c + 1).getA1Notation(), value, "", result]);
  }));

  MAP.forEach(item => {
    const d = dash.getRange(item.dashboard).getDisplayValue().trim();
    const i = item.source.lastIndexOf("!");
    const sheetName = item.source.slice(0, i).replace(/^'|'$/g, "");
    const source = ss.getSheetByName(sheetName).getRange(item.source.slice(i + 1));
    const s = source.getDisplayValue().trim();
    let result = "OK";
    if (d === "" || s === "") result = "BLANK";
    else if (/^#/.test(d) || /^#/.test(s)) result = "ERROR";
    else if (d !== s) result = "MISMATCH";
    results.push([new Date(), "Tie-out", item.label, d, s, result]);
  });

  output.clearContents();
  output.getRange(1, 1, results.length, results[0].length).setValues(results);
  output.getRange("A:A").setNumberFormat("yyyy-mm-dd hh:mm:ss");
}

function backupBeforeFinalChanges() {
  const ss = SpreadsheetApp.getActive();
  const timestamp = Utilities.formatDate(new Date(), Session.getScriptTimeZone(), "yyyyMMdd-HHmmss");
  const copy = ss.copy(`${ss.getName()} - Pre-filing backup ${timestamp}`);
  const folderId = "PASTE_BACKUP_FOLDER_ID_HERE";
  if (folderId) DriveApp.getFileById(copy.getId()).moveTo(DriveApp.getFolderById(folderId));
}
```

