Use a same-origin download service with shared SSO authentication: Streamlit stores the opaque code bound to `st.user`, while the API obtains the authenticated user from its own session and requires `payload["sub"]` to match—never trust a submitted user ID.

```python
# common.py
import redis

r = redis.Redis.from_url(
    os.environ["REDIS_URL"], decode_responses=True
)

GETDEL_LUA = """
local value = redis.call('GET', KEYS[1])
if value then redis.call('DEL', KEYS[1]) end
return value
"""

def consume_once(key: str) -> str | None:
    try:
        return r.getdel(key)                 # Redis >= 6.2
    except redis.exceptions.ResponseError as e:
        if "unknown command" not in str(e).lower():
            raise
        return r.eval(GETDEL_LUA, 1, key)    # atomic fallback
```

