from fastapi import Depends, Request
from fastapi.responses import RedirectResponse

def authenticated_user(request: Request) -> str:
    # Session is populated by your OIDC callback/middleware.
    user = request.session.get("user")
    if not user or not user.get("sub"):
        # Alternatively raise HTTPException(401) for an API-style response.
        raise HTTPException(
            status_code=303,
            headers={"Location": "/auth/login"},
        )
    return user["sub"]

@app.get("/download/form", response_class=HTMLResponse)
def download_form(
