</head>
<body>
  <h1>Download filtered rows</h1>
  <form method="post" action="/download/exchange">
    <input type="hidden" name="intent" value="{html.escape(intent, quote=True)}">
    <input type="hidden" name="csrf" value="{html.escape(csrf_token, quote=True)}">
    <button type="submit">Start download</button>
  </form>
</body>
</html>"""

    response = HTMLResponse(page, headers={
        "Cache-Control": "no-store",
