    )


GETDEL_LUA = """
local value = redis.call('GET', KEYS[1])
if value then redis.call('DEL', KEYS[1]) end
return value
"""


def consume_once(key: str) -> str | None:
    try:
        return r.getdel(key)
    except redis.exceptions.ResponseError as exc:
        if "unknown command" not in str(exc).lower():
            raise
        return r.eval(GETDEL_LUA, 1, key)


def check_csrf(form_token: str, cookie_token: str | None, origin: str | None):
    if origin != APP_ORIGIN:
        raise HTTPException(403, "Invalid request origin")
    if not cookie_token or not hmac.compare_digest(form_token, cookie_token):
        raise HTTPException(403, "CSRF validation failed")


