@app.get("/download/form", response_class=HTMLResponse)
def download_form(intent: str, user_id: str = Depends(authenticated_user)):
    if not valid_intent(intent):
        return error_page("That download link is invalid.", 400)

    csrf_token = secrets.token_urlsafe(32)
    page = f"""<!doctype html>
<html>
<head><meta name="referrer" content="no-referrer"><title>Download</title></head>
<body>
<h1>Download filtered rows</h1>
<form method="post" action="/download/exchange">
<input type="hidden" name="intent" value="{html.escape(intent, quote=True)}">
<input type="hidden" name="csrf" value="{html.escape(csrf_token, quote=True)}">
<button type="submit">Start download</button>
</form>
</body>
</html>"""

    response = HTMLResponse(
        page,
        headers={"Cache-Control": "no-store", "Referrer-Policy": "no-referrer"},
    )
    response.set_cookie(
        "download_csrf",
        csrf_token,
        max_age=300,
        secure=ENV == "production",
        httponly=False,
        samesite="strict",
        path="/download",
    )
    return response


@app.post("/download/exchange")
def exchange(
    intent: str = Form(...),
    csrf: str = Form(...),
    csrf_cookie: str | None = Cookie(None, alias="download_csrf"),
    origin: str | None = Header(None),
    user_id: str = Depends(authenticated_user),
):
    if not valid_intent(intent):
        return error_page("That download link is invalid.", 400)

    check_csrf(csrf, csrf_cookie, origin)

    try:
        raw = consume_once(f"download:intent:{intent}")
    except redis.RedisError:
        return error_page("The download service is temporarily unavailable.", 503)

    if raw is None:
        return error_page(
            "This download link has expired or has already been used.", 410
        )

    try:
        payload = json.loads(raw)
        owner = payload["sub"]
        upload_id = payload["upload_id"]
        filters = payload["filters"]
        if not all(isinstance(x, str) for x in (owner, upload_id)):
            raise ValueError
        if not isinstance(filters, dict):
            raise ValueError
    except (ValueError, TypeError, KeyError, json.JSONDecodeError):
        return error_page("That download link is invalid.", 400)

    if not hmac.compare_digest(owner, user_id):
        return error_page("This download does not belong to your account.", 403)
    if not upload_belongs_to_user(upload_id, user_id):
        return error_page("This upload is no longer available.", 403)

    return StreamingResponse(
        stream_csv(upload_id, filters),
        media_type="text/csv",
        headers={
            "Content-Disposition": 'attachment; filename="filtered.csv"',
            "Cache-Control": "no-store",
        },
    )
