function refreshIssueView() {
  const lock = LockService.getDocumentLock();
  lock.waitLock(30000);
  try {
    rebuildIssueView();
  } finally {
    lock.releaseLock();
  }
}

function rebuildIssueView() {
  const ss = SpreadsheetApp.getActive();
  const src = ss.getSheetByName(SOURCE_SHEET);
  const view = ss.getSheetByName(VIEW_SHEET) || ss.insertSheet(VIEW_SHEET);
  const roster = ss.getSheetByName(ROSTER_SHEET);

  const lastSourceRow = Math.max(src.getLastRow(), 1);
  src.getRange(1, RIDE_ID_COL).setValue('Ride ID');

  // Create permanent IDs for blank or duplicated source rows.
  const idCount = Math.max(lastSourceRow - 1, 0);
  const idValues = idCount
    ? src.getRange(2, RIDE_ID_COL, idCount, 1).getValues()
    : [];

  const usedIds = new Set();
  const finalIds = idValues.map(([id]) => {
    let value = String(id || '').trim();

    if (!value || usedIds.has(value)) {
      do {
        value = 'RIDE-' + Utilities.getUuid();
      } while (usedIds.has(value));
    }

    usedIds.add(value);
    return [value];
  });

  if (finalIds.length) {
    src.getRange(2, RIDE_ID_COL, finalIds.length, 1).setValues(finalIds);
  }

  const data = idCount
    ? src.getRange(2, 1, idCount, RIDE_ID_COL).getValues()
    : [];

  const confirmedCounts = {};
  data.forEach(row => {
    const volunteer = row[1];
    if (row[4] === 'Yes' && volunteer) {
      confirmedCounts[volunteer] = (confirmedCounts[volunteer] || 0) + 1;
    }
  });

  const issueById = new Map();

  data.forEach(row => {
    const driver = row[0];
    const volunteer = row[1];
    const pickupArea = row[3];
    const confirmed = row[4];
    const status = row[6];
    const rideId = row[9];

    const driverIssue =
      /^(DRIVER PENDING|DRIVER MARKED NO|DRIVER NOT FOUND)$/.test(status);

    const duplicateIssue =
      confirmed === 'Yes' &&
      volunteer &&
      confirmedCounts[volunteer] > 1;

    if (confirmed === 'Yes' && (driverIssue || duplicateIssue)) {
      const problems = [];
      if (driverIssue) problems.push(status);
      if (duplicateIssue) problems.push('DUPLICATE CONFIRMED RIDE');

      issueById.set(String(rideId), [
        rideId,
        volunteer,
        problems.join('; '),
        driver,
        pickupArea
      ]);
    }
  });

  // Read the existing Issue View order before changing its contents.
  const oldLastRow = Math.max(view.getLastRow() - 1, 0);
  const existingIds = oldLastRow
    ? view.getRange(2, 1, oldLastRow, 1).getValues()
        .map(row => String(row[0] || '').trim())
        .filter(Boolean)
    : [];

  // Keep existing issue IDs in their current order, then append new issues.
  const orderedRows = [];
  const retainedIds = new Set();

  existingIds.forEach(id => {
    if (issueById.has(id)) {
      orderedRows.push(issueById.get(id));
      retainedIds.add(id);
    }
  });

  issueById.forEach((row, id) => {
    if (!retainedIds.has(id)) {
      orderedRows.push(row);
    }
  });

  view.getRange(1, 1, 1, VIEW_COLS).setValues([[
    'Ride ID',
    'Volunteer',
    'Problem',
    'Driver',
    'Pickup area'
  ]]);

  // Clear contents only. Do not delete rows, filters, filter views, or sorting.
  if (oldLastRow) {
    view.getRange(2, 1, oldLastRow, VIEW_COLS).clearContent();
  }

  if (orderedRows.length) {
    view.getRange(2, 1, orderedRows.length, VIEW_COLS)
      .setValues(orderedRows);
  }

  if (roster) {
    const driverRule = SpreadsheetApp.newDataValidation()
      .requireValueInRange(roster.getRange('A2:A'), true)
      .setAllowInvalid(false)
      .build();

    const rowsForValidation = Math.max(orderedRows.length, 1);
    view.getRange(2, 4, rowsForValidation, 1)
      .setDataValidation(driverRule);
  }

  if (!view.isColumnHiddenByUser(1)) {
    view.hideColumns(1);
  }
}

function onEdit(e) {
  if (!e || !e.range) return;

  const sheet = e.range.getSheet();
  const row = e.range.getRow();
  const col = e.range.getColumn();

  if (sheet.getName() === VIEW_SHEET &&
      row > 1 &&
      (col === 4 || col === 5)) {

    const rideId = String(sheet.getRange(row, 1).getValue()).trim();
    if (!rideId) return;

    const src = SpreadsheetApp.getActive()
      .getSheetByName(SOURCE_SHEET);

    const sourceLastRow = src.getLastRow();
    if (sourceLastRow < 2) return;

    const sourceIds = src
      .getRange(2, RIDE_ID_COL, sourceLastRow - 1, 1)
      .getValues()
      .flat()
      .map(String);

    const sourceIndex = sourceIds.indexOf(rideId);
    if (sourceIndex === -1) return;

