Use this function; it exports current rows whose status is exactly `Confirmed` into a new spreadsheet with separate **Confirmed Rides** and **Confirmed Volunteers** sheets:

```javascript
function exportConfirmedLists() {
  const source = SpreadsheetApp.getActiveSpreadsheet();
  const ridesSheet = source.getSheetByName('Passenger Rides');
  const volunteersSheet = source.getSheetByName('Volunteer Tracker');

  if (!ridesSheet || !volunteersSheet) {
    throw new Error('Passenger Rides or Volunteer Tracker sheet was not found.');
  }

  const normalise = value =>
    String(value || '').trim().toLowerCase().replace(/[^a-z0-9]/g, '');

  const findColumn = (headers, names, label) => {
    const wanted = names.map(normalise);
    const index = headers.findIndex(header =>
      wanted.includes(normalise(header))
    );
    if (index === -1) {
      throw new Error(`Could not find the "${label}" column.`);
    }
    return index;
  };

  const confirmed = value => normalise(value) === 'confirmed';

  // Passenger Rides
  const rideValues = ridesSheet.getDataRange().getValues();
  const rideHeaders = rideValues[0];

  // Ride confirmed? is column E, as specified.
  const rideStatusColumn = 4;
  const rideIdColumn = findColumn(
    rideHeaders, ['Ride ID', 'RideID'], 'Ride ID'
  );
  const volunteerColumn = findColumn(
    rideHeaders, ['Volunteer', 'Volunteer Name', 'Assigned Volunteer'],
    'Volunteer'
  );
  const driverColumn = findColumn(
    rideHeaders, ['Driver', 'Driver Name'], 'Driver'
  );
  const pickupColumn = findColumn(
    rideHeaders, ['Pickup Area', 'Pickup Location', 'Pickup'],
    'Pickup Area'
  );

  const confirmedRides = [
    ['Ride ID', 'Volunteer', 'Driver', 'Pickup Area'],
    ...rideValues.slice(1)
      .filter(row => confirmed(row[rideStatusColumn]))
      .map(row => [
        row[rideIdColumn],
        row[volunteerColumn],
        row[driverColumn],
        row[pickupColumn]
      ])
  ];

  // Volunteer Tracker
  const volunteerValues = volunteersSheet.getDataRange().getValues();

  // Confirmed? is column I, as specified.
  const volunteerStatusColumn = 8;
  const confirmedVolunteers = [
    ...volunteerValues.slice(0, 1),
    ...volunteerValues.slice(1)
      .filter(row => confirmed(row[volunteerStatusColumn]))
  ];

  const exportBook = SpreadsheetApp.create(
    'Confirmed rides and volunteers - ' +
    Utilities.formatDate(
      new Date(),
      Session.getScriptTimeZone(),
      'yyyy-MM-dd HH:mm:ss'
    )
  );

  const ridesOutput = exportBook.getSheets()[0];
  ridesOutput.setName('Confirmed Rides');
  ridesOutput
    .getRange(1, 1, confirmedRides.length, confirmedRides[0].length)
    .setValues(confirmedRides);
  ridesOutput.setFrozenRows(1);
  ridesOutput.autoResizeColumns(1, confirmedRides[0].length);

  const volunteersOutput = exportBook.insertSheet('Confirmed Volunteers');
  volunteersOutput
    .getRange(1, 1, confirmedVolunteers.length, confirmedVolunteers[0].length)
    .setValues(confirmedVolunteers);
  volunteersOutput.setFrozenRows(1);
  volunteersOutput.autoResizeColumns(1, confirmedVolunteers[0].length);

  SpreadsheetApp.getUi().alert(
    'Export complete:\n' + exportBook.getUrl()
  );
}
```

