# download_api.py
import html
import json
import os
import secrets
import hmac
from fastapi import FastAPI, Cookie, Form, Header, HTTPException
from fastapi.responses import JSONResponse, HTMLResponse, StreamingResponse
from common import r, consume_once

app = FastAPI()

def current_user() -> str:
    # Replace with your SSO/OIDC middleware; never read this from POST data.
    # It must return the user authenticated to the download service.
    return get_user_from_sso_session()

def check_csrf(token: str, csrf_cookie: str | None, origin: str | None):
    if origin != os.environ["APP_ORIGIN"]:
        raise HTTPException(403, "Invalid origin")
    if not csrf_cookie or not hmac.compare_digest(token, csrf_cookie):
        raise HTTPException(403, "CSRF validation failed")

@app.get("/download/csrf")
def csrf():
    token = secrets.token_urlsafe(32)
    response = JSONResponse({"token": token})
    response.set_cookie(
        "download_csrf", token, secure=True, samesite="strict",
        httponly=False, max_age=300, path="/download",
    )
    return response

@app.post("/download/exchange")
def exchange(
    code: str = Form(...),
    csrf: str = Form(...),
    csrf_cookie: str | None = Cookie(None, alias="download_csrf"),
    origin: str | None = Header(None),
):
    check_csrf(csrf, csrf_cookie, origin)
    user_id = current_user()

    raw = consume_once(f"download:code:{code}")
    if raw is None:
        raise HTTPException(410, "Expired or already-used code")

    try:
        payload = json.loads(raw)
        if payload["sub"] != user_id:
            raise HTTPException(403, "User does not own this download")
        upload_id = payload["upload_id"]
        filters = payload["filters"]
    except (ValueError, KeyError, TypeError):
        raise HTTPException(400, "Invalid download code")

    if not upload_belongs_to_user(upload_id, user_id):
        raise HTTPException(403, "Upload is not owned by this user")

    session_id = secrets.token_urlsafe(32)
    r.set(
        f"download:session:{session_id}",
        json.dumps({"sub": user_id, "upload_id": upload_id, "filters": filters}),
        ex=60, nx=True,
    )

    # POST again so consuming the session is not a CSRF-vulnerable GET.
    form = f"""
    <form id="f" method="post" action="/download/stream">
      <input type="hidden" name="session" value="{html.escape(session_id)}">
      <input type="hidden" name="csrf" value="{html.escape(csrf)}">
    </form>
    <script>document.getElementById("f").submit()</script>
    """
    response = HTMLResponse(form)
    response.set_cookie(
        "download_session", session_id, max_age=60, secure=True,
        httponly=True, samesite="strict", path="/download",
    )
    return response

@app.post("/download/stream")
def stream(
    session: str = Form(...),
    csrf: str = Form(...),
    csrf_cookie: str | None = Cookie(None, alias="download_csrf"),
    session_cookie: str | None = Cookie(None, alias="download_session"),
    origin: str | None = Header(None),
):
    check_csrf(csrf, csrf_cookie, origin)
    if not session_cookie or not hmac.compare_digest(session, session_cookie):
        raise HTTPException(401, "Invalid download session")

    user_id = current_user()
    raw = consume_once(f"download:session:{session}")
    if raw is None:
        raise HTTPException(410, "Expired or already-used session")

    payload = json.loads(raw)
    if payload["sub"] != user_id:
        raise HTTPException(403, "Invalid download owner")

    return StreamingResponse(
        stream_csv(payload["upload_id"], payload["filters"]),
        media_type="text/csv",
        headers={
            "Content-Disposition": "attachment; filename=filtered.csv",
            "Cache-Control": "no-store",
            "Referrer-Policy": "no-referrer",
        },
    )
```

