```python
import asyncio
import logging
from concurrent.futures import ThreadPoolExecutor
from collections import Counter, defaultdict

from dash import Dash, Input, Output, dcc, html
import plotly.graph_objects as go

logging.basicConfig(level=logging.INFO)


def run_async_safely(coro_factory):
    """Run async code even if the caller already has an active event loop."""
    try:
        asyncio.get_running_loop()
    except RuntimeError:
        return asyncio.run(coro_factory())

    # asyncio.run() cannot be called inside an active loop, so use a thread.
    with ThreadPoolExecutor(max_workers=1) as executor:
        return executor.submit(
            lambda: asyncio.run(coro_factory())
        ).result()


def empty_data(message="No articles were loaded."):
    return Counter(), defaultdict(list), message


def load_initial_data():
    try:
        counts, titles = run_async_safely(
            lambda: load_article_data(URLS)
        )

        if not counts:
            return empty_data("No articles were returned by the API.")

        return counts, titles, ""

    except Exception:
        logging.exception("Initial article load failed")
        return empty_data(
            "Articles could not be loaded. Please try again later."
        )


def make_figure(category_counts):
    labels = list(category_counts)
    counts = [category_counts[label] for label in labels]

    return go.Figure(go.Bar(
        x=labels,
        y=counts,
        customdata=[[label] for label in labels],
        hovertemplate=(
            "<b>%{x}</b><br>"
            "Articles: %{y}<extra></extra>"
        ),
    ))


app = Dash(__name__)

# Safe defaults: the module can be imported without making network requests.
category_counts = Counter()
titles_by_category = defaultdict(list)
load_message = "Articles have not been loaded yet."


def make_layout():
    return html.Div([
        dcc.Graph(
            id="article-chart",
            figure=make_figure(category_counts),
        ),
        html.Div(load_message, id="load-status"),
        html.H3("Articles in selected category"),
        html.Div(
            "Click a bar to see its article titles.",
            id="article-list",
        ),
    ])


app.layout = make_layout


@app.callback(
    Output("article-list", "children"),
    Input("article-chart", "clickData"),
)
def show_titles(click_data):
    if not category_counts:
        return load_message

    if not click_data:
        return "Click a bar to see its article titles."

    category = click_data["points"][0]["customdata"][0]
    titles = titles_by_category.get(category, [])

    if not titles:
        return f"No articles found for {category}."

    return html.Div([
        html.Strong(f"{category} ({len(titles)} articles)"),
        html.Ul([html.Li(title) for title in titles]),
    ])


if __name__ == "__main__":
    category_counts, titles_by_category, load_message = load_initial_data()
    app.run(debug=True)
```

The important change is that network loading happens only inside `if __name__ == "__main__":`; failures leave Dash with an empty chart and a clear status message, while `run_async_safely()` also handles environments that already have an active event loop.

```python
import asyncio
import logging
from concurrent.futures import ThreadPoolExecutor

import plotly.graph_objects as go
from dash import Dash, Input, Output, State, dcc, html

# Reuse your existing async load_article_data(URLS) function.
URLS = [
    "https://example.com/api/articles?page=1",
    "https://example.com/api/articles?page=2",
]

logging.basicConfig(level=logging.INFO)


def run_async_safely(coro_factory):
    """Run a coroutine whether or not the current thread has an event loop."""
    try:
        asyncio.get_running_loop()
    except RuntimeError:
        return asyncio.run(coro_factory())

    with ThreadPoolExecutor(max_workers=1) as executor:
        future = executor.submit(lambda: asyncio.run(coro_factory()))
        return future.result()


def empty_payload():
    return {"counts": {}, "titles": {}}


def make_figure(payload):
    counts = payload.get("counts", {})
    labels = list(counts)

    if not labels:
        fig = go.Figure()
        fig.update_layout(
            title="No articles loaded",
            xaxis_title="Category",
            yaxis_title="Count",
        )
        return fig

    return go.Figure(
        go.Bar(
            x=labels,
            y=[counts[label] for label in labels],
            customdata=[[label] for label in labels],
            hovertemplate=(
                "<b>%{x}</b><br>"
                "Articles: %{y}<extra></extra>"
            ),
        )
    )


app = Dash(__name__)

app.layout = html.Div([
    html.Button("Refresh articles", id="refresh-button", n_clicks=0),
    html.Div(
        "Click Refresh to load articles.",
        id="load-status",
        role="status",
    ),

    # Store JSON-serializable data shared by the callbacks.
    dcc.Store(id="article-data", data=empty_payload()),

    dcc.Graph(
        id="article-chart",
        figure=make_figure(empty_payload()),
    ),

    html.H3("Articles in selected category"),
    html.Div(
        "Click a bar to see its article titles.",
        id="article-list",
    ),
])


@app.callback(
    Output("article-data", "data"),
    Output("load-status", "children"),
    Input("refresh-button", "n_clicks"),
    State("article-data", "data"),
    prevent_initial_call=True,
)
def refresh_articles(_n_clicks, previous_data):
    try:
        category_counts, titles_by_category = run_async_safely(
            lambda: load_article_data(URLS)
        )

        if not category_counts:
            return empty_payload(), "No articles were returned by the API."

        payload = {
            "counts": dict(category_counts),
            "titles": {
                category: list(titles)
                for category, titles in titles_by_category.items()
            },
        }
        return payload, f"Loaded {sum(category_counts.values())} articles."

    except Exception:
        logging.exception("Article refresh failed")

        # Preserve the last successful result instead of blanking the app.
        return (
            previous_data or empty_payload(),
            "Refresh failed; showing the last successful results.",
        )


@app.callback(
    Output("article-chart", "figure"),
    Input("article-data", "data"),
)
def update_chart(payload):
    return make_figure(payload or empty_payload())


@app.callback(
    Output("article-list", "children"),
    Input("article-chart", "clickData"),
    Input("article-data", "data"),
)
def show_titles(click_data, payload):
    payload = payload or empty_payload()
    titles_by_category = payload.get("titles", {})

    if not click_data:
        if not titles_by_category:
            return "No articles are loaded. Click Refresh to try again."
        return "Click a bar to see its article titles."

    point = click_data["points"][0]
    category = point.get("customdata", [point.get("x")])[0]
    titles = titles_by_category.get(category, [])

    if not titles:
        return f"No articles found for {category}."

    return html.Div([
        html.Strong(f"{category} ({len(titles)} articles)"),
        html.Ul([html.Li(title) for title in titles]),
    ])


if __name__ == "__main__":
    # No API call occurs here; the reloader can restart this safely.
    app.run(debug=True)
```

Because the API is contacted only inside the refresh callback, enabling Dash’s debug reloader does not perform an import-time load; the results are serialized into `dcc.Store`, so the chart and click callback use the same refreshed dataset.

Use session-scoped browser storage so each tab keeps its own refreshed dataset; the callback writes only to that user’s `dcc.Store`:

```python
dcc.Store(
    id="article-data",
    storage_type="session",  # browser sessionStorage, not shared globally
    data=empty_payload(),
)

@app.callback(
    Output("article-data", "data"),
    Output("load-status", "children"),
    Input("refresh-button", "n_clicks"),
    State("article-data", "data"),
    prevent_initial_call=True,
)
def refresh_articles(_n_clicks, previous_data):
    try:
        counts, titles = run_async_safely(lambda: load_article_data(URLS))
        if not counts:
            return empty_payload(), "No articles were returned by the API."

        return {
            "counts": dict(counts),
            "titles": {category: list(items) for category, items in titles.items()},
        }, f"Loaded {sum(counts.values())} articles."
    except Exception:
        logging.exception("Refresh failed")
        return previous_data or empty_payload(), "Refresh failed; showing previous results."
