import secrets

from dash import Dash
from flask import redirect, session
from flask_caching import Cache

app = Dash(__name__)
server = app.server

server.config.update(
    SECRET_KEY=os.environ.get("SECRET_KEY", secrets.token_urlsafe(32)),
    SESSION_COOKIE_HTTPONLY=True,
    SESSION_COOKIE_SECURE=False,  # Set True when using HTTPS in production.
    SESSION_COOKIE_SAMESITE="Lax",
)

cache = Cache(
    server,
    config={
        "CACHE_TYPE": "SimpleCache",  # Replace with RedisCache in production.
        "CACHE_DEFAULT_TIMEOUT": 600,
    },
)


@server.route("/demo-login/<user_id>/<tenant_id>")
def demo_login(user_id, tenant_id):
    """Demo only; use your real authentication system in production."""
    session.clear()
    session["user_id"] = user_id
    session["tenant_id"] = tenant_id
    session["article_cache_token"] = secrets.token_urlsafe(32)
    return redirect("/")


def current_user():
    user_id = session.get("user_id")
    tenant_id = session.get("tenant_id")

    if not user_id or not tenant_id:
        return None

    return {
        "id": user_id,
        "tenant_id": tenant_id,
    }


def session_cache_key():
    """Return a per-session cache key without putting article data in the cookie."""
    token = session.get("article_cache_token")

    if token is None:
        token = secrets.token_urlsafe(32)
        session["article_cache_token"] = token

    return f"articles:{token}"


@server.route("/demo-store")
def demo_store():
