For identical, non-sensitive API results shared across users and workers, use Redis-backed Flask-Caching:

```python
from flask_caching import Cache

cache = Cache(app.server, config={
    "CACHE_TYPE": "RedisCache",
    "CACHE_REDIS_URL": "redis://localhost:6379/0",
    "CACHE_DEFAULT_TIMEOUT": 300,
})

@cache.memoize(timeout=300)
def get_shared_articles():
    counts, titles = run_async_safely(lambda: load_article_data(URLS))
    return {
        "counts": dict(counts),
        "titles": {category: list(items) for category, items in titles.items()},
    }

@app.callback(
    Output("article-data", "data"),
    Output("load-status", "children"),
    Input("refresh-button", "n_clicks"),
    prevent_initial_call=True,
)
def refresh_from_shared_cache(_n_clicks):
    payload = get_shared_articles()
    total = sum(payload["counts"].values())
    return payload, f"Loaded {total} articles from the shared cache."
