    "CACHE_REDIS_URL": "redis://localhost:6379/0",
    "CACHE_DEFAULT_TIMEOUT": 600,
})


def session_cache_key():
    # This token identifies the cache entry but contains no article data.
    if "article_cache_token" not in session:
        session["article_cache_token"] = secrets.token_urlsafe(32)
    return f"articles:{session['article_cache_token']}"


def current_user():
    # Replace with your authentication integration.
    return {"id": session.get("user_id")}


def user_may_view(user, article):
    # Enforce ownership, tenant, role, or other authorization here.
    return article.get("tenant_id") == user.get("tenant_id")


def empty_counts():
    return {}


app.layout = html.Div([
    html.Button("Refresh articles", id="refresh-button"),
    html.Div(id="load-status"),
    dcc.Store(id="article-counts", storage_type="session", data=empty_counts()),
