        counts, titles_by_category = run_async_safely(
            lambda: load_article_data(URLS)
        )

        # Store complete articles only in Redis, never in dcc.Store.
        full_payload = {
            "articles": {
                category: list(items)
                for category, items in titles_by_category.items()
            }
        }
        cache.set(session_cache_key(), full_payload)

        counts = dict(counts)
        return counts, f"Loaded {sum(counts.values())} articles."

    except Exception:
        logging.exception("Article refresh failed")
        return empty_counts(), "Refresh failed; no new data was loaded."


@app.callback(
    Output("article-chart", "figure"),
    Input("article-counts", "data"),
)
def update_chart(counts):
    counts = counts or {}
    categories = list(counts)

    if not categories:
        return go.Figure().update_layout(title="No articles loaded")

    return go.Figure(go.Bar(
        x=categories,
        y=[counts[category] for category in categories],
        # Only the category is sent in clickData.
        customdata=[[category] for category in categories],
        hovertemplate="%{x}: %{y}<extra></extra>",
    ))


@app.callback(
    Output("article-list", "children"),
    Input("article-chart", "clickData"),
)
def show_authorized_titles(click_data):
    if not click_data:
        return "Click a category to view authorized articles."

    category = click_data["points"][0]["customdata"][0]
    payload = cache.get(session_cache_key()) or {}
    articles = payload.get("articles", {}).get(category, [])
    user = current_user()

    authorized = [
        article for article in articles
        if user_may_view(user, article)
    ]

    if not authorized:
        return "No authorized articles found."

    return html.Ul([
        html.Li([
            html.Code(str(article["id"])),
            " — ",
            article.get("title", "Untitled"),
        ])
        for article in authorized
    ])
```

The browser stores only category counts and receives titles/IDs only after the server-side authorization check; use Redis (rather than in-process caching) when Dash runs with multiple workers. If individual article selection is required, expose only opaque article IDs and re-check authorization again when serving the article detail.

