Under WSGI, an `async def` Flask route still occupies a worker while it runs, so submit the upstream fetch to a background worker (Celery/RQ in production; `ThreadPoolExecutor` for a small app) and immediately return the existing aggregate counts; run the app under ASGI only if you need true async request concurrency. Store refresh status separately, keyed by the session cache key, so failures can be reported without exposing articles:

```python
import asyncio
from concurrent.futures import ThreadPoolExecutor
from datetime import datetime, timezone

executor = ThreadPoolExecutor(max_workers=4)

def counts(payload):
    c = Counter(a.get("category", "uncategorized")
                for a in payload.get("articles", []))
    return {"categories": list(c), "counts": list(c.values())}

def refresh_in_background(key):
    try:
        articles = asyncio.run(fetch_articles_from_api())
        updated_at = datetime.now(timezone.utc).isoformat()
        cache.set(key, {"articles": articles, "updated_at": updated_at})
        cache.set(f"{key}:status", {"state": "ready", "updated_at": updated_at})
    except Exception as exc:
        cache.set(f"{key}:status", {"state": "error", "message": "Refresh failed"})

@app.post("/article-refresh")
def article_refresh():
    if current_user() is None:
        return jsonify(error="Login required"), 401
    key, cached = session_cache_key(), cache.get(session_cache_key())
    if cached is None:
        return jsonify(error="No cached articles"), 404
    cache.set(f"{key}:status", {"state": "refreshing"})
    executor.submit(refresh_in_background, key)
    result = counts(cached)
    result.update(updated_at=cached.get("updated_at"), refreshing=True)
    return jsonify(result)

@app.get("/article-refresh-status")
def article_refresh_status():
    status = cache.get(f"{session_cache_key()}:status") or {"state": "idle"}
    return jsonify(status)
```

Have the page render the `/article-refresh` response immediately (so the previous chart remains visible), poll `/article-refresh-status`, and display `"Refresh failed"` while retaining the prior chart if the status becomes `"error"`; for production, replace the executor with a durable queue because Flask’s in-process executor is lost on restart and is process-local.

Disable the button in the browser while polling, but also make the server idempotent: if the session’s status is already `"refreshing"`, return the existing job state instead of submitting another task, since client-side disabling alone is insufficient. Deduplicate before caching and counting, ideally validating that each record belongs to the current tenant:

```python
def unique_articles(articles, tenant_id):
    by_id = {}
    for article in articles:
        article_id = article.get("id")
        if article_id and article.get("tenant_id") == tenant_id:
            by_id[article_id] = article  # latest page copy wins
    return list(by_id.values())
```

In `refresh_in_background`, call `articles = unique_articles(await fetch_articles_from_api(), user_tenant_id)` and store only the resulting records; use a lock or atomic job-claim operation around the `"refreshing"` check so simultaneous requests cannot enqueue duplicate jobs.

Use Redis’s atomic `SET ... NX EX` as the job claim, and pass the tenant ID into the worker rather than reading Flask’s session there:

```python
import json
import uuid
import redis

r = redis.from_url(os.environ["REDIS_URL"], decode_responses=True)

def refresh_in_background(cache_key, tenant_id, job_id):
    status_key = f"{cache_key}:status"
    try:
        articles = unique_articles(
            asyncio.run(fetch_articles_from_api()), tenant_id
        )
        updated_at = datetime.now(timezone.utc).isoformat()
        aggregate = counts({"articles": articles})
        cache.set(cache_key, {"articles": articles, "updated_at": updated_at})
        r.set(status_key, json.dumps({
            "state": "ready", **aggregate, "updated_at": updated_at
        }), ex=600)
    except Exception:
        r.set(status_key, json.dumps({"state": "error"}), ex=600)
    finally:
        # Delete only this worker's claim.
        r.eval("""
            if redis.call('get', KEYS[1]) == ARGV[1]
            then return redis.call('del', KEYS[1])
            else return 0 end
        """, 1, f"{cache_key}:refresh-lock", job_id)

@app.post("/article-refresh")
def article_refresh():
    user = current_user()
    if user is None:
        return jsonify(error="Login required"), 401

    cache_key = session_cache_key()
    cached = cache.get(cache_key)
    if cached is None:
        return jsonify(error="No cached articles"), 404

    job_id = str(uuid.uuid4())
    lock_key = f"{cache_key}:refresh-lock"
    if not r.set(lock_key, job_id, nx=True, ex=300):
        return jsonify(state="refreshing"), 202

    r.set(f"{cache_key}:status", json.dumps({"state": "refreshing"}), ex=600)
    executor.submit(refresh_in_background, cache_key, user["tenant_id"], job_id)
    return jsonify(state="refreshing"), 202

@app.get("/article-refresh-status")
def article_refresh_status():
    value = r.get(f"{session_cache_key()}:status")
    return jsonify(json.loads(value) if value else {"state": "idle"})
```

