    // Projects without due dates go to the bottom.
    if (!a.dueDate && !b.dueDate) return 0;
    if (!a.dueDate) return 1;
    if (!b.dueDate) return -1;

    // YYYY-MM-DD dates sort correctly as strings.
    return a.dueDate.localeCompare(b.dueDate);
  });

  sortedProjects.forEach((project) => {
    const item = document.createElement('li');

    const editButton = document.createElement('button');
    editButton.type = 'button';
    editButton.textContent = project.name;
    editButton.dataset.id = project.id;

    const details = document.createElement('span');
    details.textContent =
      ` — ${project.status || 'planned'} — ${formatDueDate(project.dueDate)}`;

    const deleteButton = document.createElement('button');
    deleteButton.type = 'button';
    deleteButton.textContent = 'Delete';
    deleteButton.addEventListener('click', () => {
      projects = projects.filter(
