    const statusCol = col("Payment status"), sentCol = col("Reminder sent");
    const errors = ss.getSheetByName("Reminder errors") ||
                   ss.insertSheet("Reminder errors");
    const failed = [];
    let count = 0;

    rows.forEach((row, i) => {
      if (String(row[statusCol]).toLowerCase() !== "pending" ||
          row[sentCol] || !row[emailCol]) return;

      const currentStatus = String(
        sheet.getRange(i + 2, statusCol + 1).getValue()
      ).toLowerCase();
      if (currentStatus !== "pending") return;

      const recipient = String(row[emailCol]).trim();
      const message =
        `Hi ${row[nameCol]},\n\nOur records show that your materials contribution ` +
        `is still pending. Please send it by e-transfer to [email], or reply if ` +
        `you need another payment option.\n\nThanks!`;

      if (dryRun) {
        count++;
        return;
      }

      try {
        GmailApp.sendEmail(recipient, "Reminder: Shop Night payment", message);
        sheet.getRange(i + 2, sentCol + 1).setValue(new Date());
        count++;
      } catch (err) {
        failed.push(recipient);
        errors.appendRow([new Date(), row[nameCol], recipient, err.message]);
      }
    });

    const subject = dryRun
      ? "Shop Night reminder dry run"
      : "Shop Night reminder summary";
    const summary = dryRun
      ? `Dry run complete: ${count} reminder(s) would be sent.\n` +
        `No reminder emails were sent or marked as sent.`
      : `Reminder run complete: ${count} reminder(s) sent.\n` +
        `Failed: ${failed.length}` +
        (failed.length ? `\nFailed addresses:\n${failed.join("\n")}` : "");

    GmailApp.sendEmail(Session.getEffectiveUser().getEmail(), subject, summary);
  } finally {
    lock.releaseLock();
  }
}
```

