```javascript
function onOpen() {
  SpreadsheetApp.getUi()
    .createMenu("Waitlist")
    .addItem("Offer next spot", "offerNextWaitlistSpot")
    .addToUi();
}

function offerNextWaitlistSpot() {
  const ui = SpreadsheetApp.getUi();
  const spot = ui.prompt("Spot reference", "Enter the cancelled spot or RSVP name:", ui.ButtonSet.OK_CANCEL);
  if (spot.getSelectedButton() !== ui.Button.OK) return;

  const days = ui.prompt("Response deadline", "How many days should the offer remain open?", "3", ui.ButtonSet.OK_CANCEL);
  if (days.getSelectedButton() !== ui.Button.OK) return;

  const graceDays = Number(days.getResponseText()) || 3;
  const sheet = SpreadsheetApp.getActive().getSheetByName("Waitlist");
  const data = sheet.getDataRange().getValues();
  const headers = data.shift();
  const col = name => headers.indexOf(name);

  const required = ["Timestamp", "Name", "Email", "Offer status",
                    "Offered date", "Response deadline", "Response", "Spot reference"];
  if (required.some(h => col(h) < 0)) {
    throw new Error("Waitlist is missing one or more required columns.");
  }

  let selectedRow = -1;
  let oldest = Infinity;

  data.forEach((row, i) => {
    const status = String(row[col("Offer status")]).trim().toLowerCase();
    if ((status === "" || status === "waiting") && row[col("Email")]) {
      const timestamp = row[col("Timestamp")] instanceof Date
        ? row[col("Timestamp")].getTime()
        : Infinity;
      if (timestamp < oldest) {
        oldest = timestamp;
        selectedRow = i + 2;
      }
    }
  });

  if (selectedRow < 0) {
    ui.alert("No waiting waitlist entries were found.");
    return;
  }

  const offered = new Date();
  const deadline = new Date(offered);
  deadline.setDate(deadline.getDate() + graceDays);

  sheet.getRange(selectedRow, col("Offer status") + 1).setValue("Offered");
  sheet.getRange(selectedRow, col("Offered date") + 1).setValue(offered);
  sheet.getRange(selectedRow, col("Response deadline") + 1).setValue(deadline);
  sheet.getRange(selectedRow, col("Response") + 1).clearContent();
  sheet.getRange(selectedRow, col("Spot reference") + 1)
       .setValue(spot.getResponseText().trim());

  ui.alert("Offer recorded. Update Offer status and Response manually when they reply.");
}
