To audit acceptances and declines, add this function and create an **installable “On edit” trigger** for `recordWaitlistDecisionEdit` (this gives the audit log a more reliable editor identity):

```javascript
function recordWaitlistDecisionEdit(e) {
  if (!e || !e.range) return;

  const sheet = e.range.getSheet();
  if (sheet.getName() !== "Waitlist" || e.range.getRow() < 2) return;

  const headers = sheet
    .getRange(1, 1, 1, sheet.getLastColumn())
    .getValues()[0];

  const col = h => headers.indexOf(h);
  const statusCol = col("Offer status");
  const responseCol = col("Response");

  if (statusCol < 0 || responseCol < 0) return;

  const firstCol = e.range.getColumn() - 1;
  const lastCol = firstCol + e.range.getNumColumns() - 1;
  if (lastCol < Math.min(statusCol, responseCol) ||
      firstCol > Math.max(statusCol, responseCol)) return;

  const rows = sheet.getRange(
    e.range.getRow(), 1, e.range.getNumRows(), sheet.getLastColumn()
  ).getValues();

  rows.forEach(row => {
    const decision =
      String(row[statusCol]).trim().toLowerCase() === "accepted" ||
      String(row[responseCol]).trim().toLowerCase() === "accepted"
        ? "Accepted"
        : String(row[statusCol]).trim().toLowerCase() === "declined" ||
          String(row[responseCol]).trim().toLowerCase() === "declined"
          ? "Declined"
          : "";

    if (decision) {
      appendAudit_(
        row[col("Spot reference")],
        row[col("Name")],
        row[col("Email")],
        decision,
        row[col("Response deadline")]
      );
    }
  });
}
```

