```js
const calendarGrid = document.querySelector('#calendarGrid');
const calendarMonth = document.querySelector('#calendarMonth');
const previousMonth = document.querySelector('#previousMonth');
const nextMonth = document.querySelector('#nextMonth');

let displayedMonth = new Date(
  new Date().getFullYear(),
  new Date().getMonth(),
  1
);

function dateKey(date) {
  const year = date.getFullYear();
  const month = String(date.getMonth() + 1).padStart(2, '0');
  const day = String(date.getDate()).padStart(2, '0');
  return `${year}-${month}-${day}`;
}

function renderCalendar() {
  const year = displayedMonth.getFullYear();
  const month = displayedMonth.getMonth();

  calendarMonth.textContent = displayedMonth.toLocaleDateString(undefined, {
    month: 'long',
    year: 'numeric'
  });

  const firstDay = new Date(year, month, 1);
  const gridStart = new Date(year, month, 1 - firstDay.getDay());

  const projectsByDate = new Map();

  projects.forEach(project => {
    if (!project.dueDate) return;

    if (!projectsByDate.has(project.dueDate)) {
      projectsByDate.set(project.dueDate, []);
    }

    projectsByDate.get(project.dueDate).push(project);
  });

  calendarGrid.replaceChildren();

  for (let index = 0; index < 42; index++) {
    const day = new Date(
      gridStart.getFullYear(),
      gridStart.getMonth(),
      gridStart.getDate() + index
    );

    const key = dateKey(day);
    const cell = document.createElement('div');
    cell.className = 'calendar-cell';

    if (day.getMonth() !== month) {
      cell.classList.add('outside-month');
    }

    const dayNumber = document.createElement('div');
    dayNumber.textContent = day.getDate();
    cell.append(dayNumber);

    for (const project of projectsByDate.get(key) || []) {
      const projectButton = document.createElement('button');
      projectButton.type = 'button';
      projectButton.className = 'calendar-project';
      projectButton.dataset.projectId = project.id;
      projectButton.textContent = project.name || project.title;
      cell.append(projectButton);
    }

    calendarGrid.append(cell);
  }
}

previousMonth.addEventListener('click', () => {
  displayedMonth = new Date(
    displayedMonth.getFullYear(),
    displayedMonth.getMonth() - 1,
    1
  );
  renderCalendar();
});

nextMonth.addEventListener('click', () => {
  displayedMonth = new Date(
    displayedMonth.getFullYear(),
    displayedMonth.getMonth() + 1,
    1
  );
  renderCalendar();
});

calendarGrid.addEventListener('click', event => {
  const projectButton = event.target.closest('[data-project-id]');
  if (!projectButton) return;

  const project = projects.find(
    item => String(item.id) === projectButton.dataset.projectId
  );

  if (project) {
    openEditForm(project); // Use your existing form-loading function here.
  }
});

renderCalendar();
```

