```javascript
function sendPendingReminders() {
  runPendingReminders_(false);
}

function testPendingReminders() {
  runPendingReminders_(true); // Preview anytime; sends nothing
}

function runPendingReminders_(dryRun) {
  const lock = LockService.getScriptLock();
  if (!lock.tryLock(30000)) return;

  try {
    const ss = SpreadsheetApp.getActive();
    const tz = ss.getSpreadsheetTimeZone();
    const eventDate = ss.getSheetByName("Config").getRange("B1").getValue();
    if (!(eventDate instanceof Date)) throw new Error("Config!B1 must contain a valid event date.");

    const today = Utilities.formatDate(new Date(), tz, "yyyy-MM-dd");
    const target = new Date(eventDate);
    target.setDate(target.getDate() - 3);
    const targetDate = Utilities.formatDate(target, tz, "yyyy-MM-dd");
    const eventKey = Utilities.formatDate(eventDate, tz, "yyyy-MM-dd");

    if (!dryRun && today !== targetDate) return;

    const props = PropertiesService.getScriptProperties();
    if (!dryRun && props.getProperty("reminderRunFor") === eventKey) return;

    const sheet = ss.getSheetByName("RSVP responses");
    const values = sheet.getDataRange().getValues();
    const headers = values.shift();
    const col = name => headers.indexOf(name);
    const emailCol = col("Email"), nameCol = col("Name");
    const statusCol = col("Payment status"), sentCol = col("Reminder sent");
    const errors = ss.getSheetByName("Reminder errors") || ss.insertSheet("Reminder errors");

    let sent = 0, skippedPaid = 0;
    const failed = [];

    values.forEach((row, i) => {
      const status = String(row[statusCol]).trim().toLowerCase();

      if (status === "paid" || status === "waived") {
        skippedPaid++;
        return;
      }
      if (status !== "pending" || row[sentCol] || !row[emailCol]) return;

      const currentStatus = String(
        sheet.getRange(i + 2, statusCol + 1).getValue()
      ).trim().toLowerCase();
      if (currentStatus !== "pending") {
        if (currentStatus === "paid" || currentStatus === "waived") skippedPaid++;
        return;
      }

      const recipient = String(row[emailCol]).trim();
      const body = `Hi ${row[nameCol]},\n\nOur records show that your materials contribution is still pending. Please send it by e-transfer to [email], or reply if you need another payment option.\n\nThanks!`;

      if (dryRun) {
        sent++;
        return;
      }

      try {
        GmailApp.sendEmail(recipient, "Reminder: Shop Night payment", body);
        sheet.getRange(i + 2, sentCol + 1).setValue(new Date());
        sent++;
      } catch (err) {
        failed.push(recipient);
        errors.appendRow([new Date(), row[nameCol], recipient, err.message]);
      }
    });

    const summary =
      `${dryRun ? "Dry run" : "Reminder run"} complete.\n` +
      `Reminders ${dryRun ? "that would be sent" : "sent"}: ${sent}\n` +
      `Skipped as Paid/Waived: ${skippedPaid}\n` +
      `Failed: ${failed.length}` +
      (failed.length ? `\nFailed addresses:\n${failed.join("\n")}` : "");

    GmailApp.sendEmail(Session.getEffectiveUser().getEmail(),
      dryRun ? "Shop Night reminder dry run" : "Shop Night reminder summary",
      summary);

    if (!dryRun) props.setProperty("reminderRunFor", eventKey);
  } finally {
    lock.releaseLock();
  }
}
