Use `Config!B2` for the registration cutoff date/time and require a `Timestamp` column in `RSVP responses`; paid/waived totals will include all rows, while only eligible, unpaid registrations are considered for reminders.

```javascript
function sendPendingReminders() {
  runPendingReminders_(false);
}

function testPendingReminders() {
  runPendingReminders_(true);
}

function runPendingReminders_(dryRun) {
  const lock = LockService.getScriptLock();
  if (!lock.tryLock(30000)) return;

  try {
    const ss = SpreadsheetApp.getActive();
    const tz = ss.getSpreadsheetTimeZone();
    const config = ss.getSheetByName("Config");
    const eventDate = config.getRange("B1").getValue();
    const cutoff = config.getRange("B2").getValue();

    if (!(eventDate instanceof Date)) {
      throw new Error("Config!B1 must contain a valid event date.");
    }
    if (cutoff && !(cutoff instanceof Date)) {
      throw new Error("Config!B2 must contain a valid registration cutoff.");
    }

    const today = Utilities.formatDate(new Date(), tz, "yyyy-MM-dd");
    const target = new Date(eventDate);
    target.setDate(target.getDate() - 3);
    const targetDate = Utilities.formatDate(target, tz, "yyyy-MM-dd");
    const eventKey = Utilities.formatDate(eventDate, tz, "yyyy-MM-dd");

    if (!dryRun && today !== targetDate) return;

    const props = PropertiesService.getScriptProperties();
    if (!dryRun && props.getProperty("reminderRunFor") === eventKey) return;

    const sheet = ss.getSheetByName("RSVP responses");
    const data = sheet.getDataRange().getValues();
    const headers = data.shift();
    const col = name => headers.indexOf(name);

    const emailCol = col("Email");
    const nameCol = col("Name");
    const statusCol = col("Payment status");
    const sentCol = col("Reminder sent");
    const timestampCol = col("Timestamp");

    if ([emailCol, nameCol, statusCol, sentCol].some(i => i < 0)) {
      throw new Error("Missing one or more required RSVP columns.");
    }
    if (cutoff && timestampCol < 0) {
      throw new Error("A Timestamp column is required when Config!B2 is set.");
    }

    const errors = ss.getSheetByName("Reminder errors") ||
                   ss.insertSheet("Reminder errors");

    let totalPaid = 0;
    let totalWaived = 0;
    let pendingReminders = 0;
    let failedSends = 0;
    let skippedLate = 0;
    const failed = [];

    data.forEach((row, i) => {
      let status = String(row[statusCol]).trim().toLowerCase();

      // These totals describe the whole sheet, not just reminder candidates.
      if (status === "paid") totalPaid++;
      if (status === "waived") totalWaived++;

      // Late registrations are excluded from reminder consideration.
      if (cutoff) {
        const registered = row[timestampCol];
        if (!(registered instanceof Date) || registered > cutoff) {
          skippedLate++;
          return;
        }
      }

      if (status !== "pending" || row[sentCol] || !row[emailCol]) return;

      // Recheck immediately before sending.
      status = String(
        sheet.getRange(i + 2, statusCol + 1).getValue()
      ).trim().toLowerCase();

      if (status !== "pending") {
        if (status === "paid") totalPaid++;
        if (status === "waived") totalWaived++;
        return;
      }

      const recipient = String(row[emailCol]).trim();
      const body =
        `Hi ${row[nameCol]},\n\n` +
        `Our records show that your materials contribution is still pending. ` +
        `Please send it by e-transfer to [email], or reply if you need another payment option.\n\n` +
        `Thanks!`;

      if (dryRun) {
        pendingReminders++;
        return;
      }

      try {
        GmailApp.sendEmail(recipient, "Reminder: Shop Night payment", body);
        sheet.getRange(i + 2, sentCol + 1).setValue(new Date());
        pendingReminders++;
      } catch (err) {
        failedSends++;
        failed.push(recipient);
        errors.appendRow([
          new Date(), row[nameCol], recipient, err.message
        ]);
      }
    });

    const summary =
      `${dryRun ? "Dry run" : "Reminder run"} complete.\n` +
      `Total paid: ${totalPaid}\n` +
      `Total waived: ${totalWaived}\n` +
      `Pending reminders ${dryRun ? "that would be sent" : "sent"}: ${pendingReminders}\n` +
      `Failed sends: ${failedSends}\n` +
      `Skipped after registration cutoff: ${skippedLate}` +
      (failed.length ? `\nFailed addresses:\n${failed.join("\n")}` : "");

    GmailApp.sendEmail(
      Session.getEffectiveUser().getEmail(),
      dryRun ? "Shop Night reminder dry run" : "Shop Night reminder summary",
      summary
    );

    if (!dryRun) props.setProperty("reminderRunFor", eventKey);
  } finally {
    lock.releaseLock();
  }
}
```

Set `Config!B2` to the final eligible registration date/time, run `testPendingReminders()` first, and keep the daily trigger on `sendPendingReminders()` so the script itself enforces the three-day timing.

