  );
}

function offerNextWaitlistSpot() {
  const ui = SpreadsheetApp.getUi();
  const spotPrompt = ui.prompt(
    "Spot reference",
    "Enter the cancelled spot or RSVP name:",
    ui.ButtonSet.OK_CANCEL
  );
  if (spotPrompt.getSelectedButton() !== ui.Button.OK) return;

  const spotReference = spotPrompt.getResponseText().trim();
  if (!spotReference) {
    ui.alert("A spot reference is required.");
    return;
  }

  const daysPrompt = ui.prompt(
    "Response deadline",
    "How many days should the offer remain open?",
    "3",
    ui.ButtonSet.OK_CANCEL
  );
  if (daysPrompt.getSelectedButton() !== ui.Button.OK) return;

  const days = Math.max(1, Number(daysPrompt.getResponseText()) || 3);
  const sheet = SpreadsheetApp.getActive().getSheetByName("Waitlist");
  const values = sheet.getDataRange().getValues();
  const headers = values.shift();
  const col = name => headers.indexOf(name);

  const required = [
    "Timestamp", "Name", "Email", "Offer status",
    "Offered date", "Response deadline", "Response", "Spot reference"
  ];
  if (required.some(h => col(h) < 0)) {
    throw new Error("Waitlist is missing one or more required columns.");
  }

  const spotCol = col("Spot reference");
  const statusCol = col("Offer status");

  // Prevent duplicate active offers for the same spot.
  const alreadyOffered = values.some(row =>
    String(row[spotCol]).trim() === spotReference &&
    ["offered", "accepted"].includes(
      String(row[statusCol]).trim().toLowerCase()
    )
  );

  if (alreadyOffered) {
    ui.alert("This spot already has an active or accepted waitlist offer.");
    return;
  }

  let selectedRow = -1;
  let selected = null;
  let oldest = Infinity;

  values.forEach((row, i) => {
    const status = String(row[statusCol]).trim().toLowerCase();
    const timestamp = row[col("Timestamp")] instanceof Date
      ? row[col("Timestamp")].getTime()
      : Infinity;

    if ((status === "" || status === "waiting") &&
        row[col("Email")] &&
        timestamp < oldest) {
      oldest = timestamp;
      selectedRow = i + 2;
      selected = row;
    }
  });

  if (selectedRow < 0) {
    ui.alert("No waiting waitlist entries were found.");
    return;
  }

  const offered = new Date();
  const deadline = new Date(offered);
  deadline.setDate(deadline.getDate() + days);

  const confirm = ui.alert(
    "Confirm waitlist offer",
    `Offer spot "${spotReference}" to:\n\n` +
    `${selected[col("Name")]}\n${selected[col("Email")]}\n\n` +
    `Response deadline: ${deadline.toLocaleDateString()}`,
    ui.ButtonSet.YES_NO
  );

  if (confirm !== ui.Button.YES) return;

  sheet.getRange(selectedRow, statusCol + 1).setValue("Offered");
  sheet.getRange(selectedRow, col("Offered date") + 1).setValue(offered);
  sheet.getRange(selectedRow, col("Response deadline") + 1).setValue(deadline);
  sheet.getRange(selectedRow, col("Response") + 1).clearContent();
  sheet.getRange(selectedRow, spotCol + 1).setValue(spotReference);

  ui.alert(`Offer recorded for ${selected[col("Name")]}.`);
}
