function expireWaitlistOffers() {
  const ui = SpreadsheetApp.getUi();
  const sheet = SpreadsheetApp.getActive().getSheetByName("Waitlist");
  if (!sheet) return ui.alert("Waitlist sheet not found.");

  const values = sheet.getDataRange().getValues();
  const headers = values.shift();
  const col = h => headers.indexOf(h);

  ["Name", "Email", "Offer status", "Response deadline",
   "Spot reference"].forEach(h => {
    if (col(h) < 0) throw new Error(`Waitlist is missing "${h}".`);
  });

  const now = new Date();
  const expiring = values
    .map((row, i) => ({ row, sheetRow: i + 2 }))
    .filter(x =>
      String(x.row[col("Offer status")]).trim().toLowerCase() === "offered" &&
      x.row[col("Response deadline")] instanceof Date &&
      x.row[col("Response deadline")] < now
    );

  if (!expiring.length) {
    ui.alert("No offers are past their response deadline.");
    return;
