  const names = expiring
    .map(x => `${x.row[col("Name")]} (${x.row[col("Email")]})`)
    .join("\n");

  const answer = ui.alert(
    "Confirm expiration",
    `${expiring.length} offer(s) will be marked Expired:\n\n${names}`,
    ui.ButtonSet.YES_NO
