Require both `Offer status` and `Response` to agree before logging, then deduplicate using the spot, decision, and response deadline:

```javascript
function recordWaitlistDecisionEdit(e) {
  if (!e || !e.range) return;
  const sheet = e.range.getSheet();
  if (sheet.getName() !== "Waitlist" || e.range.getRow() < 2) return;

  const headers = sheet.getRange(1, 1, 1, sheet.getLastColumn()).getValues()[0];
  const col = h => headers.indexOf(h);
  const statusCol = col("Offer status"), responseCol = col("Response");
  if (statusCol < 0 || responseCol < 0) return;

  const first = e.range.getColumn() - 1;
  const last = first + e.range.getNumColumns() - 1;
  if (last < Math.min(statusCol, responseCol) ||
      first > Math.max(statusCol, responseCol)) return;

  const row = sheet.getRange(e.range.getRow(), 1, 1, sheet.getLastColumn()).getValues()[0];
  const status = String(row[statusCol]).trim().toLowerCase();
  const response = String(row[responseCol]).trim().toLowerCase();
  if (!["accepted", "declined"].includes(status) || status !== response) return;

  appendDecisionAudit_(row[col("Spot reference")], row[col("Name")],
    row[col("Email")], status[0].toUpperCase() + status.slice(1),
    row[col("Response deadline")]);
}

function appendDecisionAudit_(spot, name, email, event, deadline) {
  const ss = SpreadsheetApp.getActive();
  const log = ss.getSheetByName("Audit log");
  const rows = log.getDataRange().getValues();
  const headers = rows.shift(), col = h => headers.indexOf(h);
  const deadlineKey = deadline instanceof Date ? deadline.getTime() : String(deadline);

  const duplicate = rows.some(row =>
    String(row[col("Spot reference")]).trim() === String(spot).trim() &&
    String(row[col("Event")]).trim() === event &&
    (row[col("Response deadline")] instanceof Date
      ? row[col("Response deadline")].getTime()
      : String(row[col("Response deadline")])) === deadlineKey
  );
  if (!duplicate) appendAudit_(spot, name, email, event, deadline);
}
```

