Use this as a two-pass script: by default it performs only a dry run and writes a CSV; rerun the same command with `-Commit` only after reviewing that CSV.

```powershell
param(
    [Parameter(Mandatory = $true)]
    [string]$Source,

    [Parameter(Mandatory = $true)]
    [string]$Destination,

    [switch]$Commit
)

Set-StrictMode -Version Latest
$ErrorActionPreference = "Stop"

$src = (Resolve-Path -LiteralPath $Source).Path
$dst = [IO.Path]::GetFullPath((Join-Path (Get-Location) $Destination))

if ($src.TrimEnd('\') -eq $dst.TrimEnd('\')) {
    throw "Source and destination must be different folders."
}

New-Item -ItemType Directory -Path $dst -Force | Out-Null

$extensions = @(".jpg", ".jpeg", ".png", ".tif", ".tiff")
$formats = @(
    "yyyy:MM:dd HH:mm:ss",
    "yyyy-MM-dd HH:mm:ss",
    "yyyy-MM-ddTHH:mm:ss",
    "yyyy:MM:dd HH:mm:ss.fff"
)

function Get-PhotoDate {
    param(
        [Parameter(Mandatory = $true)]
        [System.IO.FileInfo]$File
    )

    # Reset all EXIF-related variables for this file.
    $p = $null
    $image = $null
    $date = $File.LastWriteTime
    $usedFallback = $true
    $exifNote = ""

    try {
        $image = [System.Drawing.Image]::FromFile($File.FullName)

        try {
            $p = $image.GetPropertyItem(36867) # DateTimeOriginal
        }
        catch {
            $p = $null
        }

        if ($null -ne $p) {
            $raw = [Text.Encoding]::ASCII.GetString($p.Value).
                Trim([char]0).
                Trim()

            $parsed = [datetime]::MinValue

            if ([datetime]::TryParseExact(
                $raw,
                $formats,
                [Globalization.CultureInfo]::InvariantCulture,
                [Globalization.DateTimeStyles]::None,
                [ref]$parsed
            )) {
                $date = $parsed
                $usedFallback = $false
            }
            else {
                $exifNote = "EXIF date could not be parsed: $raw"
            }
        }
        else {
            $exifNote = "DateTimeOriginal EXIF field not present"
        }
    }
    catch {
        $exifNote = "EXIF read failed: $($_.Exception.Message)"
    }
    finally {
        if ($null -ne $image) {
            $image.Dispose()
        }
    }

    [pscustomobject]@{
        Date         = $date
        UsedFallback = $usedFallback
        ExifNote     = $exifNote
    }
}

$dstPrefix = $dst.TrimEnd('\') + '\'

$files = @(
    Get-ChildItem -LiteralPath $src -File -Recurse |
        Where-Object {
            $extensions -contains $_.Extension.ToLowerInvariant() -and
            $_.FullName -ne $dst.TrimEnd('\') -and
            -not $_.FullName.StartsWith($dstPrefix, [StringComparison]::OrdinalIgnoreCase)
        }
)

$results = [System.Collections.Generic.List[object]]::new()
$usedOutputs = [System.Collections.Generic.HashSet[string]]::new(
    [StringComparer]::OrdinalIgnoreCase
)

foreach ($file in $files) {
    $out = ""
    $status = if ($Commit) { "Failed" } else { "DryRun" }
    $errorMessage = ""

    try {
        $photoDate = Get-PhotoDate -File $file
        $date = $photoDate.Date

        $out = Join-Path $dst (
            "{0}_{1}{2}" -f
            $date.ToString("yyyy-MM-dd_HHmmss"),
            $file.BaseName,
            $file.Extension
        )

        if (-not $usedOutputs.Add($out)) {
            throw "Duplicate output name proposed: $out"
        }

        if (Test-Path -LiteralPath $out) {
            throw "Output already exists: $out"
        }

        if ($Commit) {
            Copy-Item -LiteralPath $file.FullName `
                      -Destination $out `
                      -ErrorAction Stop
            $status = "Copied"
        }
    }
    catch {
        $status = "Failed"
        $errorMessage = $_.Exception.Message
    }

    $results.Add([pscustomobject]@{
        Source       = $file.FullName
        Output       = $out
        DateUsed     = if ($out) { $date.ToString("yyyy-MM-dd HH:mm:ss") } else { "" }
        DateSource   = if ($photoDate -and $photoDate.UsedFallback) {
                           "LastWriteTime"
                       } else {
                           "EXIF DateTimeOriginal"
                       }
        UsedFallback = if ($photoDate) { $photoDate.UsedFallback } else { $true }
        ExifNote     = if ($photoDate) { $photoDate.ExifNote } else { "" }
        Status       = $status
        Error        = $errorMessage
    })
}

$log = Join-Path $dst "rename-log.csv"
$results | Export-Csv -LiteralPath $log -NoTypeInformation -Encoding UTF8

$failed = @($results | Where-Object Status -eq "Failed")
$duplicates = @(
    $results |
        Where-Object Output |
        Group-Object Output |
        Where-Object Count -gt 1
)

Write-Host ""
Write-Host "Eligible files: $($files.Count)"
Write-Host "Logged rows:    $($results.Count)"
Write-Host "Failed:         $($failed.Count)"
Write-Host "Duplicate outputs: $($duplicates.Count)"
Write-Host "Log:            $log"

if (-not $Commit) {
    Write-Host ""
    Write-Host "DRY RUN ONLY: no photos were copied."
    Write-Host "Review the CSV, then rerun with -Commit if everything is correct."
}
else {
    $copied = @($results | Where-Object Status -eq "Copied")
    Write-Host "Copied:         $($copied.Count)"
}
```

