```python
from pathlib import Path
from PIL import Image
import imagehash

root = Path(r"C:\Photos-Organized").resolve()
quarantine = (root / "_duplicate-quarantine").resolve()
exts = {".jpg",".jpeg",".png",".heic",".tif",".tiff",".raw",".cr2",".cr3",".nef",".arw",".dng"}
threshold = 6

items = []
for p in root.rglob("*"):
    if p.is_file() and p.suffix.lower() in exts and quarantine not in p.parents:
        try:
            with Image.open(p) as im:
                items.append((p, imagehash.phash(im)))
        except Exception as e:
            print(f"Skipped unreadable/unsupported file: {p} ({e})")

parent = list(range(len(items)))
def find(x):
    while parent[x] != x:
        parent[x] = parent[parent[x]]
        x = parent[x]
    return x
def union(a, b):
    a, b = find(a), find(b)
    if a != b: parent[b] = a

for i in range(len(items)):
    for j in range(i + 1, len(items)):
        if items[i][1] - items[j][1] <= threshold:
            union(i, j)

groups = {}
for i, (path, h) in enumerate(items):
    groups.setdefault(find(i), []).append((path, h))

matches = [g for g in groups.values() if len(g) > 1]
print(f"Perceptually similar photo groups: {len(matches)}")
for n, group in enumerate(matches, 1):
    print(f"\nGroup {n}:")
    for path, h in group:
        print(f"  {h}  {path}")
```

A lower threshold is stricter; start with 6 and review results, since perceptual groups can include false positives, and most RAW formats require rendered JPEG previews rather than direct hashing.

