    a, b = find(a), find(b)
    if a != b:
        parent[b] = a

for i in range(len(items)):
    for j in range(i + 1, len(items)):
        if items[i][1] - items[j][1] <= threshold:
            union(i, j)

groups = {}
for i, (path, phash) in enumerate(items):
    groups.setdefault(find(i), []).append((path, str(phash)))

matches = sorted(
    (g for g in groups.values() if len(g) > 1),
    key=lambda g: str(min(item[0] for item in g)).lower()
)

with output.open("w", newline="", encoding="utf-8-sig") as f:
    writer = csv.writer(f)
    writer.writerow(["Group", "PHash", "Path"])
    for number, group in enumerate(matches, 1):
        for path, phash in sorted(group, key=lambda x: str(x[0]).lower()):
            writer.writerow([number, phash, str(path)])

print(f"Perceptually similar groups: {len(matches)}")
print(f"CSV written to: {output}")
```

