The safest approach is to checkpoint both the **last completed page** and the exact **byte offset** in the JSONL file. On startup, truncate the output back to that offset before requesting the next page, so a crash after writing but before checkpointing cannot create duplicates.

```python
# collect_issues.py
import argparse
import json
import os
import random
import time
from pathlib import Path

import requests


PAGE_SIZE = 100
MAX_ATTEMPTS = 8


def atomic_checkpoint(path: Path, state: dict) -> None:
    """Atomically replace the checkpoint file."""
    temp = path.with_name(path.name + ".tmp")

    with open(temp, "w", encoding="utf-8") as f:
        json.dump(state, f)
        f.flush()
        os.fsync(f.fileno())

    os.replace(temp, path)

    # Make the rename durable where supported.
    try:
        directory_fd = os.open(path.parent, os.O_RDONLY)
        try:
            os.fsync(directory_fd)
        finally:
            os.close(directory_fd)
    except OSError:
        pass


def retry_after(response, attempt: int) -> int:
    if response.status_code == 403 and response.headers.get(
        "X-RateLimit-Remaining"
    ) == "0":
        reset = int(response.headers["X-RateLimit-Reset"])
        return max(reset - int(time.time()) + 1, 1)

    value = response.headers.get("Retry-After")
    try:
        return max(int(value), 1)
    except (TypeError, ValueError):
        return min(2**attempt, 60)


def get_page(session, url: str, page: int):
    params = {
        "state": "all",
        "per_page": PAGE_SIZE,
        "page": page,
        "sort": "created",
        "direction": "asc",
    }

    for attempt in range(MAX_ATTEMPTS):
        try:
            response = session.get(url, params=params, timeout=30)

            retryable = (
                response.status_code == 429
                or 500 <= response.status_code < 600
                or (
                    response.status_code == 403
                    and response.headers.get("X-RateLimit-Remaining") == "0"
                )
            )

            if retryable:
                wait = retry_after(response, attempt)
                print(
                    f"HTTP {response.status_code}; "
                    f"retrying in {wait}s"
                )
                time.sleep(wait + random.random())
                continue

            response.raise_for_status()
            return response

        except requests.RequestException:
            if attempt == MAX_ATTEMPTS - 1:
                raise

            wait = min(2**attempt, 60)
            print(f"Request failed; retrying in {wait}s")
            time.sleep(wait + random.random())

    raise RuntimeError(f"Could not fetch page {page}")


def collect(repo: str, output_path: str, token: str, session=None) -> None:
    output = Path(output_path)
    checkpoint = Path(str(output) + ".checkpoint.json")
    output.parent.mkdir(parents=True, exist_ok=True)

    if session is None:
        session = requests.Session()

    session.headers.update({
        "Accept": "application/vnd.github+json",
        "Authorization": f"Bearer {token}",
        "X-GitHub-Api-Version": "2022-11-28",
    })

    if checkpoint.exists():
        state = json.loads(checkpoint.read_text(encoding="utf-8"))
        start_page = int(state["page"]) + 1
        offset = int(state["offset"])

        if output.exists() and output.stat().st_size < offset:
            raise RuntimeError("Output file is shorter than its checkpoint")

        # Remove a page written before the process died checkpointing it.
        with open(output, "ab") as f:
            f.truncate(offset)
    else:
        if output.exists() and output.stat().st_size:
            raise RuntimeError(
                f"{output} exists without a checkpoint; "
                "refusing to risk duplicate data"
            )

        output.touch()
        start_page = 1
        offset = 0

    url = f"https://api.github.com/repos/{repo}/issues"
    saved = 0

    with open(output, "a", encoding="utf-8") as out:
        for page in range(start_page, 1001):
            response = get_page(session, url, page)
            issues = response.json()

            if not issues:
                break

            page_saved = 0
            for issue in issues:
                # The issues endpoint also returns pull requests.
                if "pull_request" in issue:
                    continue

                out.write(json.dumps(issue, ensure_ascii=False) + "\n")
                page_saved += 1
                saved += 1

            # Ensure all page bytes reach disk before checkpointing them.
            out.flush()
            os.fsync(out.fileno())

            new_state = {
                "page": page,
                "offset": out.tell(),
            }
            atomic_checkpoint(checkpoint, new_state)

            print(
                f"completed page={page}, "
                f"saved_this_page={page_saved}, total_this_run={saved}, "
                f"remaining={response.headers.get('X-RateLimit-Remaining')}"
            )

            if len(issues) < PAGE_SIZE:
                break


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("repo", help="owner/name, such as scikit-learn/scikit-learn")
    parser.add_argument("--out", default="data/raw/issues.jsonl")
    args = parser.parse_args()

    token = os.environ.get("GITHUB_TOKEN")
    if not token:
        raise SystemExit("Set GITHUB_TOKEN before running the script")

    collect(args.repo, args.out, token)


if __name__ == "__main__":
    main()
```

