```python
# test_collect_issues.py
import json

import collect_issues


class FakeResponse:
    def __init__(self, issues):
        self._issues = issues
        self.status_code = 200
        self.headers = {"X-RateLimit-Remaining": "4999"}

    def json(self):
        return self._issues

    def raise_for_status(self):
        pass


class FakeSession:
    def get(self, url, params, timeout):
        page = params["page"]
        pages = {
            1: [{"id": 1}, {"id": 2}],
            2: [{"id": 3}],
            3: [],
        }
        return FakeResponse(pages[page])


def test_resume_does_not_duplicate_pages(tmp_path, monkeypatch):
    output = tmp_path / "issues.jsonl"
    session = FakeSession()

    original = collect_issues.atomic_checkpoint
    crashed = False

    def crash_once(path, state):
        nonlocal crashed
        if not crashed:
            crashed = True
            raise RuntimeError("simulated interruption")
        original(path, state)

    monkeypatch.setattr(collect_issues, "atomic_checkpoint", crash_once)

    try:
        collect_issues.collect("owner/repo", str(output), "token", session)
    except RuntimeError:
        pass

    monkeypatch.setattr(
        collect_issues, "atomic_checkpoint", original
    )
    collect_issues.collect("owner/repo", str(output), "token", session)

    records = [
        json.loads(line)
        for line in output.read_text(encoding="utf-8").splitlines()
    ]

    assert [record["id"] for record in records] == [1, 2, 3]
