```python
from datetime import datetime
from zoneinfo import ZoneInfo

DISPLAY_TZ = ZoneInfo("America/New_York")

def parse_dt(value):
    value = value.strip().replace("Z", "+00:00")
    dt = datetime.fromisoformat(value)
    return (dt if dt.tzinfo else dt.replace(tzinfo=DISPLAY_TZ)).astimezone(DISPLAY_TZ)

# Calendar events should retain their timezone-aware start/end values.
calendar_events = [
    {"title": "Statistics class", "start": parse_dt("2026-04-14T13:00:00Z"),
     "end": parse_dt("2026-04-14T14:30:00Z")},
]

def overlaps(start, end, event):
    return start < event["end"] and end > event["start"]

def describe_buffer(buffer):
    start = parse_dt(buffer["start"])
    end = parse_dt(buffer["end"])
    conflicts = [
        e["title"] for e in calendar_events
        if overlaps(start, end, e)
    ]
    warning = f"; WARNING overlaps: {', '.join(conflicts)}" if conflicts else ""
    return (
        f"{buffer['buffer']} "
        f"({start:%Y-%m-%d %H:%M %Z}–{end:%H:%M %Z}){warning}"
    )

# For each proposed allocation:
details = " + ".join(describe_buffer(b) for b in chosen)
emit(f"[PROPOSED] {label} gets {details}")
```

