Yes—subtract calendar-event intervals from each buffer, then consume the resulting free segments until the task’s required minutes are met; any shortfall is reported explicitly:

```python
from datetime import timedelta

def free_segments(buffer):
    start, end = parse_dt(buffer["start"]), parse_dt(buffer["end"])
    conflicts = [e for e in calendar_events if overlaps(start, end, e)]
    cursor, segments = start, []

    for event in sorted(conflicts, key=lambda e: e["start"]):
        if cursor < event["start"]:
            segments.append((cursor, min(event["start"], end)))
        cursor = max(cursor, event["end"])
        if cursor >= end:
            break
    if cursor < end:
        segments.append((cursor, end))
    return [(s, e) for s, e in segments if s < e], conflicts

def suggest_split(buffers, needed):
    proposed, remaining = [], needed
    for buffer in buffers:
        segments, conflicts = free_segments(buffer)
        for start, end in segments:
            if remaining <= 0:
                break
            finish = min(end, start + timedelta(minutes=remaining))
            proposed.append((buffer["buffer"], start, finish, conflicts))
            remaining -= int((finish - start).total_seconds() // 60)
        if remaining <= 0:
            break
    return proposed, remaining

proposed, unscheduled = suggest_split([fallback], needed)
for name, start, end, conflicts in proposed:
    blocked = ", ".join(e["title"] for e in conflicts)
    emit(f"[REPLACEMENT] {label}: {name} "
         f"({start:%Y-%m-%d %H:%M %Z}–{end:%H:%M %Z})"
         + (f"; full buffer overlaps {blocked}" if blocked else ""))

if unscheduled:
    emit(f"[UNSCHEDULED] {label}: {unscheduled} minutes remain "
         "after splitting around calendar conflicts")
```

