}

$log = Join-Path $dst "rename-log.csv"
$results | Export-Csv -LiteralPath $log -NoTypeInformation -Encoding UTF8

$failed = @($results | Where-Object Status -eq "Failed")
$duplicates = @(
    $results |
        Where-Object Output |
        Group-Object Output |
        Where-Object Count -gt 1
)

Write-Host ""
Write-Host "Eligible files: $($files.Count)"
Write-Host "Logged rows:    $($results.Count)"
Write-Host "Failed:         $($failed.Count)"
Write-Host "Duplicate outputs: $($duplicates.Count)"
Write-Host "Log:            $log"

if (-not $Commit) {
    Write-Host ""
    Write-Host "DRY RUN ONLY: no photos were copied."
    Write-Host "Review the CSV, then rerun with -Commit if everything is correct."
}
else {
    $copied = @($results | Where-Object Status -eq "Copied")
    Write-Host "Copied:         $($copied.Count)"
}
