from pathlib import Path
import csv
from PIL import Image
import imagehash

root = Path(r"C:\Photos-Organized").resolve()
quarantine = (root / "_duplicate-quarantine").resolve()
output = root / "perceptual-similarity-groups.csv"
exts = {".jpg",".jpeg",".png",".heic",".tif",".tiff",".raw",".cr2",".cr3",".nef",".arw",".dng"}
threshold = 6

items = []
for p in root.rglob("*"):
    if p.is_file() and p.suffix.lower() in exts and quarantine not in p.parents:
        try:
            with Image.open(p) as im:
                items.append((p, imagehash.phash(im)))
        except Exception as e:
            print(f"Skipped: {p} ({e})")

parent = list(range(len(items)))

def find(x):
    while parent[x] != x:
        parent[x] = parent[parent[x]]
        x = parent[x]
    return x

def union(a, b):
    a, b = find(a), find(b)
    if a != b:
        parent[b] = a

for i in range(len(items)):
    for j in range(i + 1, len(items)):
        if items[i][1] - items[j][1] <= threshold:
            union(i, j)

groups = {}
for i, (path, phash) in enumerate(items):
    groups.setdefault(find(i), []).append((path, str(phash)))

matches = sorted(
    (g for g in groups.values() if len(g) > 1),
    key=lambda g: str(min(item[0] for item in g)).lower()
)

with output.open("w", newline="", encoding="utf-8-sig") as f:
    writer = csv.writer(f)
    writer.writerow(["Group", "PHash", "Path"])
    for number, group in enumerate(matches, 1):
        for path, phash in sorted(group, key=lambda x: str(x[0]).lower()):
            writer.writerow([number, phash, str(path)])

print(f"Perceptually similar groups: {len(matches)}")
print(f"CSV written to: {output}")
