Use timezone-aware datetimes, convert UTC calendar entries into the user’s display zone, and test each proposed buffer for interval overlap:

```python
from datetime import datetime
from zoneinfo import ZoneInfo

DISPLAY_TZ = ZoneInfo("America/New_York")

def parse_dt(value):
    value = value.strip().replace("Z", "+00:00")
    dt = datetime.fromisoformat(value)
    return (dt if dt.tzinfo else dt.replace(tzinfo=DISPLAY_TZ)).astimezone(DISPLAY_TZ)

# Calendar events should retain their timezone-aware start/end values.
calendar_events = [
    {"title": "Statistics class", "start": parse_dt("2026-04-14T13:00:00Z"),
     "end": parse_dt("2026-04-14T14:30:00Z")},
]

def overlaps(start, end, event):
    return start < event["end"] and end > event["start"]

def describe_buffer(buffer):
    start = parse_dt(buffer["start"])
    end = parse_dt(buffer["end"])
    conflicts = [
        e["title"] for e in calendar_events
        if overlaps(start, end, e)
    ]
    warning = f"; WARNING overlaps: {', '.join(conflicts)}" if conflicts else ""
    return (
        f"{buffer['buffer']} "
        f"({start:%Y-%m-%d %H:%M %Z}–{end:%H:%M %Z}){warning}"
    )

# For each proposed allocation:
details = " + ".join(describe_buffer(b) for b in chosen)
emit(f"[PROPOSED] {label} gets {details}")
```

Ensure each buffer has `start` and `end` ISO timestamps (including offsets where possible); UTC values such as `...Z` are converted correctly without modifying the CSV or calendar.

Yes—subtract calendar-event intervals from each buffer, then consume the resulting free segments until the task’s required minutes are met; any shortfall is reported explicitly:

```python
from datetime import timedelta

def free_segments(buffer):
    start, end = parse_dt(buffer["start"]), parse_dt(buffer["end"])
    conflicts = [e for e in calendar_events if overlaps(start, end, e)]
    cursor, segments = start, []

    for event in sorted(conflicts, key=lambda e: e["start"]):
        if cursor < event["start"]:
            segments.append((cursor, min(event["start"], end)))
        cursor = max(cursor, event["end"])
        if cursor >= end:
            break
    if cursor < end:
        segments.append((cursor, end))
    return [(s, e) for s, e in segments if s < e], conflicts

def suggest_split(buffers, needed):
    proposed, remaining = [], needed
    for buffer in buffers:
        segments, conflicts = free_segments(buffer)
        for start, end in segments:
            if remaining <= 0:
                break
            finish = min(end, start + timedelta(minutes=remaining))
            proposed.append((buffer["buffer"], start, finish, conflicts))
            remaining -= int((finish - start).total_seconds() // 60)
        if remaining <= 0:
            break
    return proposed, remaining

proposed, unscheduled = suggest_split([fallback], needed)
for name, start, end, conflicts in proposed:
    blocked = ", ".join(e["title"] for e in conflicts)
    emit(f"[REPLACEMENT] {label}: {name} "
         f"({start:%Y-%m-%d %H:%M %Z}–{end:%H:%M %Z})"
         + (f"; full buffer overlaps {blocked}" if blocked else ""))

if unscheduled:
    emit(f"[UNSCHEDULED] {label}: {unscheduled} minutes remain "
         "after splitting around calendar conflicts")
```

Because all comparisons use timezone-aware parsed datetimes, UTC calendar entries and local buffer times are handled consistently without modifying either source.

