from math import isfinite
from flask import request, jsonify
from werkzeug.exceptions import BadRequest

@app.post("/api/issues")
def create_issue():
    if not request.is_json:
        return jsonify(error="Request body must be valid JSON"), 400

    try:
        data = request.get_json()
    except BadRequest:
        return jsonify(error="Malformed JSON request body"), 400

    if not isinstance(data, dict):
        return jsonify(error="JSON body must be an object"), 400

    missing = [field for field in ("title", "description", "lat", "lng")
               if field not in data]
    if missing:
        return jsonify(error="Missing required fields", fields=missing), 400

    title = str(data["title"]).strip()
    description = str(data["description"]).strip()

    try:
        lat = float(data["lat"])
        lng = float(data["lng"])
    except (TypeError, ValueError):
        return jsonify(error="lat and lng must be numbers"), 400

    if not title:
        return jsonify(error="title must not be empty"), 400
    if not isfinite(lat) or not -90 <= lat <= 90:
        return jsonify(error="lat must be between -90 and 90"), 400
    if not isfinite(lng) or not -180 <= lng <= 180:
        return jsonify(error="lng must be between -180 and 180"), 400

    issue = Issue(title=title, description=description, lat=lat, lng=lng)
    db.session.add(issue)
    db.session.commit()

    return jsonify(
        id=issue.id,
        title=issue.title,
        description=issue.description,
        lat=issue.lat,
        lng=issue.lng,
    ), 201
```

