    .map((email, index) => email === key ? index + 2 : -1)
    .filter(rowNumber => rowNumber !== -1);

  // Do not change anything if the key is missing or duplicated.
  if (matches.length !== 1) {
    ss.toast(
      matches.length === 0
        ? 'Key not found—no change made.'
        : 'Duplicate key—no change made.'
    );
    return;
  }

  // Only checking Done? changes the tracker.
  main.getRange(matches[0], 10).setValue('Connected');

  // Rebuild the static list so the completed reminder disappears.
  refreshReminders();
}

function onOpen() {
  SpreadsheetApp.getUi()
    .createMenu('Reminders')
    .addItem('Refresh now', 'refreshReminders')
    .addToUi();
}
```

