Add a locked mode and route every event-writing or dry-run function through one guarded calendar accessor:

```javascript
// SAFETY SETTINGS — leave unchanged while testing.
const RUN_MODE = "TEST"; // Change to "REAL" only when ready.
const TEST_CALENDAR_ID = "PASTE_TEST_CALENDAR_ID_HERE";

// REAL mode requires both settings to be changed explicitly.
const REAL_CALENDAR_ID = "";
const ALLOW_REAL_CALENDAR = false;

function getConfiguredCalendar() {
  let calendarId;

  if (RUN_MODE === "TEST") {
    calendarId = TEST_CALENDAR_ID;
    if (!calendarId || calendarId === "PASTE_TEST_CALENDAR_ID_HERE") {
      throw new Error("Configure TEST_CALENDAR_ID before running.");
    }
  } else if (RUN_MODE === "REAL") {
    if (!ALLOW_REAL_CALENDAR) {
      throw new Error(
        "Real-calendar execution is locked. Set ALLOW_REAL_CALENDAR = true explicitly."
      );
    }
    if (!REAL_CALENDAR_ID) {
      throw new Error("Configure REAL_CALENDAR_ID before using real mode.");
    }
    calendarId = REAL_CALENDAR_ID;
  } else {
    throw new Error(`Invalid RUN_MODE: ${RUN_MODE}`);
  }

  const calendar = CalendarApp.getCalendarById(calendarId);
  if (!calendar) {
    throw new Error(`Configured calendar is unavailable: ${calendarId}`);
  }

  Logger.log(`Using ${RUN_MODE} calendar: ${calendar.getName()} (${calendarId})`);
  return calendar;
}
```

Replace `CalendarApp.getCalendarById(TEST_CALENDAR_ID)` with `getConfiguredCalendar()` in `ensureThisMonth()`, `dryRunMonth()`, and any other function that accesses the target event calendar. To go live, explicitly set `RUN_MODE = "REAL"`, enter `REAL_CALENDAR_ID`, and change `ALLOW_REAL_CALENDAR` to `true`; otherwise the script throws before creating, moving, or deleting anything.

Add this read-only preflight function. It uses the same guarded calendar accessor, refuses a test run unless the calendar name contains `TEST`, and calculates the next two scheduled dates without modifying events:

```javascript
function preflight() {
  const calendar = getConfiguredCalendar();
  const calendarName = calendar.getName();
  const calendarId = calendar.getId();

  if (
    RUN_MODE === "TEST" &&
    !calendarName.toUpperCase().includes("TEST")
  ) {
    throw new Error(
      `Safety check failed: TEST mode requires a calendar name containing ` +
      `"TEST". Actual name: "${calendarName}"`
    );
  }

  const today = new Date();
  const targetMonth = new Date(
    today.getFullYear(),
    today.getMonth() + 1,
    1
  );
  const followingMonth = new Date(
    targetMonth.getFullYear(),
    targetMonth.getMonth() + 1,
    1
  );

  const holidays = loadHolidays(
    addDays(targetMonth, -14),
    addDays(followingMonth, 45)
  );

  const reviewDate = getFirstBusinessDay(
    targetMonth.getFullYear(),
    targetMonth.getMonth(),
    holidays
  );
  const finalDate = nextBusinessDay(
    addDays(reviewDate, 7),
    holidays
  );

  Logger.log(`Run mode: ${RUN_MODE}`);
  Logger.log(`Calendar name: ${calendarName}`);
  Logger.log(`Calendar ID: ${calendarId}`);
  Logger.log(`Next review date: ${dateKey(reviewDate)}`);
  Logger.log(`Next final reminder date: ${dateKey(finalDate)}`);
  Logger.log("Preflight passed. No calendar events were changed.");
}
```

Run `preflight()` manually and confirm the logged calendar ID and name before installing the trigger. Ensure `dryRunMonth()` also calls `getConfiguredCalendar()` rather than directly reading `TEST_CALENDAR_ID`, so all calendar access follows the same safety guard.

