```javascript
// Leave blank if this script is bound to the spreadsheet containing the Control tab.
const CONTROL_SPREADSHEET_ID = "";

function updateControlTab(reviewDate, finalDate, holidayCount) {
  const spreadsheet = CONTROL_SPREADSHEET_ID
    ? SpreadsheetApp.openById(CONTROL_SPREADSHEET_ID)
    : SpreadsheetApp.getActiveSpreadsheet();

  if (!spreadsheet) {
    throw new Error(
      "No spreadsheet is available. Set CONTROL_SPREADSHEET_ID."
    );
  }

  const sheet =
    spreadsheet.getSheetByName("Control") ||
    spreadsheet.insertSheet("Control");

  const now = new Date();
  const tz = Session.getScriptTimeZone();

  sheet.getRange("A1:B5").setValues([
    ["Status", "Value"],
    ["Last checked", Utilities.formatDate(now, tz, "yyyy-MM-dd HH:mm:ss z")],
    ["Planned review date", dateKey(reviewDate)],
    ["Planned final date", dateKey(finalDate)],
    ["Holiday entries loaded", String(holidayCount)]
  ]);

  sheet.getRange("A1:B1").setFontWeight("bold");
  sheet.autoResizeColumns(1, 2);
}
