function isValidExpense(expense) {
  return expense &&
    typeof expense.description === "string" &&
    expense.description.trim() !== "" &&
    typeof expense.amount === "number" &&
    Number.isFinite(expense.amount) &&
    expense.amount >= 0 &&
    typeof expense.date === "string" &&
    !Number.isNaN(Date.parse(expense.date));
}

function resetExpenses() {
  if (!confirm("Are you sure you want to delete all expenses? This cannot be undone.")) {
    return;
  }

  expenses = [];
  localStorage.removeItem("expenses");
  renderExpenses();
}

function exportExpenses() {
  const validExpenses = expenses.filter(isValidExpense);

  if (validExpenses.length === 0) {
    alert("There are no valid expenses to export.");
    return;
  }

  const json = JSON.stringify(validExpenses, null, 2);
  const blob = new Blob([json], { type: "application/json" });
  const url = URL.createObjectURL(blob);
  const link = document.createElement("a");
  const date = new Date().toISOString().slice(0, 10);

  link.href = url;
  link.download = `expenses-${date}.json`;
  link.click();

  URL.revokeObjectURL(url);
}

document.querySelector("#reset-button").addEventListener("click", resetExpenses);
document.querySelector("#export-button").addEventListener("click", exportExpenses);
