```js
function validateExpense(expense, index) {
  const errors = [];

  if (!expense || typeof expense !== "object") {
    errors.push("entry is not an object");
  } else {
    if (typeof expense.description !== "string" || !expense.description.trim()) {
      errors.push("missing description");
    }
    if (typeof expense.amount !== "number" ||
        !Number.isFinite(expense.amount) ||
        expense.amount < 0) {
      errors.push("invalid amount");
    }
    if (typeof expense.date !== "string" || Number.isNaN(Date.parse(expense.date))) {
      errors.push("invalid date");
    }
  }

  return { index, expense, errors };
}

function exportExpenses() {
  const results = expenses.map(validateExpense);
  const validExpenses = results
    .filter(result => result.errors.length === 0)
    .map(result => result.expense);
  const invalidExpenses = results.filter(result => result.errors.length > 0);

  if (invalidExpenses.length) {
    const details = invalidExpenses
      .map(({ index, errors }) => `Entry ${index + 1}: ${errors.join(", ")}`)
      .join("\n");
    alert(`${invalidExpenses.length} entr${invalidExpenses.length === 1 ? "y was" : "ies were"} skipped:\n\n${details}`);
  }

  if (!validExpenses.length) {
