Yes—injecting a `now` function keeps the test isolated and makes the dependency explicit. Use `now = () => new Date()` by default, then derive the filename from its UTC ISO date:

```js
export function exportExpenses(
  validExpenses,
  {
    status,
    now = () => new Date(),
    scheduleRevoke = (fn, delay) => setTimeout(fn, delay)
  }
) {
  if (validExpenses.length === 0) {
    status.textContent = "No valid entries were available to export.";
    return { ok: false, reason: "no-data" };
  }

  let url = null;
  let link = null;
  let result;

  try {
    const blob = new Blob([JSON.stringify(validExpenses)], {
      type: "application/json"
    });

    url = URL.createObjectURL(blob);
    link = document.createElement("a");
    link.href = url;
    link.download = `expenses-${now().toISOString().slice(0, 10)}.json`;
    document.body.append(link);
    link.click();

    status.textContent = "Export completed successfully.";
    result = { ok: true, count: validExpenses.length };
  } catch (error) {
    status.textContent = "The export failed. Please try again.";
    result = { ok: false, error };
  } finally {
    link?.remove();

    if (url) {
      const createdUrl = url;
      scheduleRevoke(() => URL.revokeObjectURL(createdUrl), 1000);
    }
  }

  return result;
}
```

