from datetime import date, datetime, timezone

def parse_memo_time(value):
    text = (value or "").strip()
    if not text:
        return None

    try:
        parsed = datetime.fromisoformat(text.replace("Z", "+00:00"))
    except ValueError:
        try:
            parsed = datetime.strptime(text, "%H:%M:%S")
        except ValueError:
            return None

    if parsed.tzinfo is not None:
        parsed = parsed.astimezone(timezone.utc).replace(tzinfo=None)
    return parsed

def sort_key(row):
    parsed = parse_memo_time(row.get("memo_time"))
    return (
        normalize_stop(row["stop"]),
        parsed is None,                    # valid values first
        parsed or datetime.max,            # chronological within each group
        row.get("original_filename", "").casefold(),
    )

rows.sort(key=sort_key)
