function importCorrectionBackup(file) {
  const reader = new FileReader();

  reader.onload = () => {
    try {
      const backup = JSON.parse(reader.result);
      if (backup?.version !== 1 || !backup.corrections ||
          typeof backup.corrections !== "object") {
        throw new Error("Unsupported backup format");
      }

      const currentPaths = new Map();
      document.querySelectorAll("figure").forEach(figure => {
        const filename = figure.dataset.filename || "";
        const raw = figure.dataset.raw || "";
        if (!currentPaths.has(filename)) currentPaths.set(filename, new Set());
        currentPaths.get(filename).add(raw);
      });

      const conflicts = [];
      const safeEntries = [];

      for (const [key, correction] of Object.entries(backup.corrections)) {
        const separator = key.indexOf("\u001f");
        const filename = separator >= 0 ? key.slice(0, separator) : key;
        const rawPath = separator >= 0 ? key.slice(separator + 1) : "";

        if (currentPaths.has(filename) &&
            !currentPaths.get(filename).has(rawPath)) {
          conflicts.push(`${filename}\n  backup RAW: ${rawPath || "(none)"}`);
        } else {
          safeEntries.push([key, correction]);
        }
      }

      if (conflicts.length) {
        const message =
          `These corrections match a filename but have a different RAW path:\n\n` +
          conflicts.join("\n\n") +
          `\n\nClick OK to import only non-conflicting corrections, or Cancel.`;

        if (!confirm(message)) return;
      }

      for (const [key, correction] of safeEntries) {
        savedCorrections[key] = correction;
      }

      localStorage.setItem(CORRECTIONS_KEY, JSON.stringify(savedCorrections));
      location.reload();
    } catch (error) {
      alert(`Could not import backup: ${error.message}`);
    }
  };

  reader.readAsText(file);
}
```

