function refreshReminders() {
  const ss = SpreadsheetApp.getActive();
  const main = ss.getSheetByName('Follow-up');
  const view = ss.getSheetByName('Reminders');
  const last = main.getLastRow();
  const today = new Date();
  today.setHours(0, 0, 0, 0);

  const output = [];
  if (last >= 2) {
    main.getRange(2, 1, last - 1, 11).getValues().forEach(r => {
      const date = r[8] instanceof Date ? new Date(r[8]) : null;
      if (!date) return;
      date.setHours(0, 0, 0, 0);

      if (r[7] === 'Yes' && date <= today &&
          r[9] !== 'Connected' && r[9] !== 'Closed') {
        output.push([r[0], r[8], r[10], false,
          String(r[1]).trim().toLowerCase()]);
      }
    });
  }

  if (view.getMaxRows() > 1)
    view.getRange(2, 1, view.getMaxRows() - 1, 5)
      .clearContent().clearDataValidations();

  view.getRange('A1:E1').setValues([['Person', 'Reminder date', 'Next step', 'Done?', 'Key']]);
  if (output.length) {
    view.getRange(2, 1, output.length, 5).setValues(output);
    const checkbox = SpreadsheetApp.newDataValidation().requireCheckbox().build();
    view.getRange(2, 4, output.length, 1).setDataValidation(checkbox);
  }
  view.getRange('B:B').setNumberFormat('m/d/yyyy');
  view.hideColumns(5);
}

function onEdit(e) {
  const range = e.range;
  const view = range.getSheet();
  if (view.getName() !== 'Reminders' || range.getColumn() !== 4 ||
      range.getRow() < 2 || range.getNumRows() !== 1 || e.value !== 'TRUE') return;

  const key = view.getRange(range.getRow(), 5).getDisplayValue().trim().toLowerCase();
  if (!key) return;

  const main = e.source.getSheetByName('Follow-up');
  const last = main.getLastRow();
  const emails = last < 2 ? [] :
    main.getRange(2, 2, last - 1, 1).getDisplayValues()
      .flat().map(x => x.trim().toLowerCase());

  const matches = emails.map((x, i) => x === key ? i + 2 : -1).filter(i => i !== -1);
  if (matches.length !== 1) {
    e.source.toast(matches.length ? 'Duplicate key—no change made.' : 'Key not found—no change made.');
    return;
  }

  main.getRange(matches[0], 10).setValue('Connected'); // column J
  refreshReminders();
}
