However, that would overwrite the current `Person` header, so the script must instead use row 2 for headers and row 3 onward for reminders.

```javascript
const MAIN_SHEET = 'Follow-up';
const REMINDERS_SHEET = 'Reminders';

function refreshReminders() {
  const ss = SpreadsheetApp.getActive();
  const main = ss.getSheetByName(MAIN_SHEET);
  const view = ss.getSheetByName(REMINDERS_SHEET);

  // Keep the workflow note in row 1.
  view.getRange('A1:E1').breakApart().merge()
    .setValue(
      'Workflow: Check Done? only after the follow-up is complete. Checking it marks the person as Connected.'
    )
    .setWrap(true);

  // Headers stay in row 2.
  view.getRange('A2:E2').setValues([[
    'Person', 'Reminder date', 'Next step', 'Done?', 'Key'
  ]]);

  // Remove the previous static reminder list, but keep the note and headers.
  const rowsToClear = view.getMaxRows() - 2;
  if (rowsToClear > 0) {
    view.getRange(3, 1, rowsToClear, 5)
      .clearContent()
      .clearDataValidations();
  }

  const output = [];
  const lastRow = main.getLastRow();
  const today = new Date();
  today.setHours(0, 0, 0, 0);

  if (lastRow >= 2) {
    main.getRange(2, 1, lastRow - 1, 11).getValues().forEach(row => {
      const reminderDate = row[8] instanceof Date
        ? new Date(row[8])
        : null;

      if (!reminderDate) return;

      reminderDate.setHours(0, 0, 0, 0);

      const isDue = row[7] === 'Yes' && reminderDate <= today;
      const status = String(row[9]).trim();

      if (isDue && status !== 'Connected' && status !== 'Closed') {
        output.push([
          row[0],                                  // Person, column A
          row[8],                                  // Reminder date, column I
          row[10],                                 // Next step, column K
          false,                                   // Done? checkbox
          String(row[1]).trim().toLowerCase()     // Hidden email key, column B
        ]);
      }
    });
  }

  if (output.length > 0) {
    view.getRange(3, 1, output.length, 5).setValues(output);

    const checkboxRule = SpreadsheetApp.newDataValidation()
      .requireCheckbox()
      .build();

    view.getRange(3, 4, output.length, 1)
      .setDataValidation(checkboxRule);
  }

  view.getRange('B:B').setNumberFormat('m/d/yyyy');
  view.setFrozenRows(2);
  view.hideColumns(5);
}

function onEdit(e) {
  if (!e || !e.range || e.value !== 'TRUE') return;

  const editedRange = e.range;
  const view = editedRange.getSheet();

  // Only respond to a single checkbox in Reminders column D, row 3 or later.
  if (
    view.getName() !== REMINDERS_SHEET ||
    editedRange.getColumn() !== 4 ||
    editedRange.getRow() < 3 ||
    editedRange.getNumRows() !== 1 ||
    editedRange.getNumColumns() !== 1
  ) {
    return;
  }

  const row = editedRange.getRow();
  const key = view.getRange(row, 5)
    .getDisplayValue()
    .trim()
    .toLowerCase();

  if (!key) return;

  const ss = e.source;
  const main = ss.getSheetByName(MAIN_SHEET);
  const lastRow = main.getLastRow();

  if (lastRow < 2) return;

  const emails = main
    .getRange(2, 2, lastRow - 1, 1)
    .getDisplayValues()
    .flat()
    .map(email => email.trim().toLowerCase());

  const matches = emails
    .map((email, index) => email === key ? index + 2 : -1)
    .filter(rowNumber => rowNumber !== -1);

  // Do not change anything if the key is missing or duplicated.
  if (matches.length !== 1) {
    ss.toast(
      matches.length === 0
        ? 'Key not found—no change made.'
        : 'Duplicate key—no change made.'
    );
    return;
  }

  // Only checking Done? changes the tracker.
  main.getRange(matches[0], 10).setValue('Connected');

  // Rebuild the static list so the completed reminder disappears.
  refreshReminders();
}

function onOpen() {
  SpreadsheetApp.getUi()
    .createMenu('Reminders')
    .addItem('Refresh now', 'refreshReminders')
    .addToUi();
}
```

