Below is a small Apps Script that treats “business day” as Monday–Friday, creates the current month’s two all-day events, and updates them by a unique month marker instead of creating duplicates. In **script.google.com**, create a project, paste this code, set the project time zone to match your Calendar, run `installDailyTrigger()` once, and authorize it.

```javascript
const CALENDAR_ID = ""; // Leave blank for your default calendar.

function ensureThisMonth() {
  const calendar = CALENDAR_ID
    ? CalendarApp.getCalendarById(CALENDAR_ID)
    : CalendarApp.getDefaultCalendar();

  const today = new Date();
  const year = today.getFullYear();
  const month = today.getMonth();
  const firstBusinessDay = getFirstBusinessDay(year, month);
  const finalReminder = new Date(firstBusinessDay);
  finalReminder.setDate(finalReminder.getDate() + 7);

  const monthKey = Utilities.formatDate(
    firstBusinessDay,
    Session.getScriptTimeZone(),
    "yyyy-MM"
  );

  const reviewDescription =
    `Checklist:\n` +
    `☐ Review open introductions\n` +
    `☐ Send respectful, relevant follow-ups\n` +
    `☐ Update each tracker line\n` +
    `☐ Set the final reminder for one week later\n\n` +
    `<!-- introduction-follow-up:${monthKey}:review -->`;

  const finalDescription =
    `Checklist:\n` +
    `☐ Send one low-pressure final reminder for still-open items\n` +
    `☐ Mark unanswered items closed\n` +
    `☐ Set next reminder to —\n\n` +
    `<!-- introduction-follow-up:${monthKey}:final -->`;

  upsertEvent(
    calendar,
    "Review Open Introductions",
    firstBusinessDay,
    reviewDescription,
    monthKey,
    "review"
  );

  upsertEvent(
    calendar,
    "Final Follow-Up",
    finalReminder,
    finalDescription,
    monthKey,
    "final"
  );
}

function getFirstBusinessDay(year, month) {
  const date = new Date(year, month, 1);
  while (date.getDay() === 0 || date.getDay() === 6) {
    date.setDate(date.getDate() + 1);
  }
  return date;
}

function upsertEvent(calendar, title, date, description, monthKey, kind) {
  const marker = `<!-- introduction-follow-up:${monthKey}:${kind} -->`;
  const searchStart = new Date(date);
  searchStart.setDate(searchStart.getDate() - 2);
  const searchEnd = new Date(date);
  searchEnd.setDate(searchEnd.getDate() + 3);

  const matches = calendar.getEvents(searchStart, searchEnd)
    .filter(event => (event.getDescription() || "").includes(marker));

  let event = matches.shift();

  if (!event) {
    event = calendar.createAllDayEvent(title, date, { description });
  } else {
    event.setTitle(title);
    event.setAllDayDate(date);
    event.setDescription(description);
  }

  // Clean up accidental duplicates created with the same marker.
  matches.forEach(duplicate => duplicate.deleteEvent());
}

function installDailyTrigger() {
  ScriptApp.getProjectTriggers()
    .filter(trigger => trigger.getHandlerFunction() === "ensureThisMonth")
    .forEach(trigger => ScriptApp.deleteTrigger(trigger));

  ScriptApp.newTrigger("ensureThisMonth")
    .timeBased()
    .everyDays(1)
    .atHour(6)
    .create();

  ensureThisMonth();
}
```

The daily trigger is intentional: it ensures the events exist even if the script is first installed mid-month, while the marker prevents duplicate events. This version excludes weekends but not public holidays; a holiday list can be added if you need that definition of “business day.”

Use a small year-specific `Set` of holiday dates and make the date finder skip both weekends and listed holidays. Replace `getFirstBusinessDay()` and the final-reminder calculation with:

```javascript
// Update this once a year; use the script's time zone.
const HOLIDAYS = new Set([
  "2026-01-01",
  "2026-05-25",
  "2026-07-03", // observed holiday, if applicable
  "2026-09-07",
  "2026-11-26",
  "2026-12-25"
]);

function dateKey(date) {
  return Utilities.formatDate(
    date, Session.getScriptTimeZone(), "yyyy-MM-dd"
  );
}

function isBusinessDay(date) {
  return date.getDay() !== 0 &&
         date.getDay() !== 6 &&
         !HOLIDAYS.has(dateKey(date));
}

function nextBusinessDay(date) {
  const result = new Date(date);
  while (!isBusinessDay(result)) result.setDate(result.getDate() + 1);
  return result;
}

function getFirstBusinessDay(year, month) {
  return nextBusinessDay(new Date(year, month, 1));
}
