```javascript
const CALENDAR_ID = ""; // Blank = your default calendar.
const HOLIDAY_SHEET_ID = "PASTE_SHEET_ID_HERE";
const HOLIDAY_TAB = "Holidays";

const REVIEW_TITLE = "Review Open Introductions";
const FINAL_TITLE = "Final Follow-Up";

/**
 * Creates or updates this month's two events.
 * Run this manually once to test, then install the daily trigger.
 */
function ensureThisMonth() {
  const calendar = CALENDAR_ID
    ? CalendarApp.getCalendarById(CALENDAR_ID)
    : CalendarApp.getDefaultCalendar();

  if (!calendar) {
    throw new Error("Calendar not found. Check CALENDAR_ID.");
  }

  const holidays = loadHolidays();
  const today = new Date();
  const year = today.getFullYear();
  const month = today.getMonth();

  const firstBusinessDay = getFirstBusinessDay(year, month, holidays);

  // One week after the review, moved forward if it lands on a
  // weekend or holiday.
  const finalReminder = nextBusinessDay(
    addDays(firstBusinessDay, 7),
    holidays
  );

  const monthKey = Utilities.formatDate(
    firstBusinessDay,
    Session.getScriptTimeZone(),
    "yyyy-MM"
  );

  const reviewMarker =
    `<!-- introduction-follow-up:${monthKey}:review -->`;

  const finalMarker =
    `<!-- introduction-follow-up:${monthKey}:final -->`;

  const reviewDescription =
    `Checklist:\n` +
    `☐ Review open introductions\n` +
    `☐ Send respectful, relevant follow-ups\n` +
    `☐ Update each tracker line\n` +
    `☐ Set the final reminder for one week later\n\n` +
    reviewMarker;

  const finalDescription =
    `Checklist:\n` +
    `☐ Send one low-pressure final reminder for still-open items\n` +
    `☐ Mark unanswered items closed\n` +
    `☐ Set next reminder to —\n\n` +
    finalMarker;

  upsertEvent(
    calendar,
    REVIEW_TITLE,
    firstBusinessDay,
    reviewDescription,
    monthKey,
    "review",
    reviewMarker
  );

  upsertEvent(
    calendar,
    FINAL_TITLE,
    finalReminder,
    finalDescription,
    monthKey,
    "final",
    finalMarker
  );
}

/**
 * Reads holiday dates from column A, starting at A2.
 * Use actual Google Sheets date values, not formatted text where possible.
 */
function loadHolidays() {
  const spreadsheet = SpreadsheetApp.openById(HOLIDAY_SHEET_ID);
  const sheet = spreadsheet.getSheetByName(HOLIDAY_TAB);

  if (!sheet) {
    throw new Error(`Sheet tab "${HOLIDAY_TAB}" was not found.`);
  }

  const lastRow = sheet.getLastRow();
  if (lastRow < 2) return new Set();

  return new Set(
    sheet
      .getRange(2, 1, lastRow - 1, 1)
      .getValues()
      .flat()
      .map(value => holidayValueToKey(value))
      .filter(Boolean)
  );
}

/**
 * Converts a Sheet date or YYYY-MM-DD text into a comparable date key.
 */
function holidayValueToKey(value) {
  if (value instanceof Date && !isNaN(value.getTime())) {
    return dateKey(value);
  }

  if (typeof value === "string") {
    const match = value.trim().match(/^(\d{4})-(\d{2})-(\d{2})$/);
    if (match) return value.trim();
  }

  return null;
}

function dateKey(date) {
  return Utilities.formatDate(
    date,
    Session.getScriptTimeZone(),
    "yyyy-MM-dd"
  );
}

function isBusinessDay(date, holidays) {
  const day = date.getDay();
  return day !== 0 &&
    day !== 6 &&
    !holidays.has(dateKey(date));
}

function nextBusinessDay(date, holidays) {
  const result = new Date(date);

  while (!isBusinessDay(result, holidays)) {
    result.setDate(result.getDate() + 1);
  }

  return result;
}

function getFirstBusinessDay(year, month, holidays) {
  return nextBusinessDay(new Date(year, month, 1), holidays);
}

function addDays(date, days) {
  const result = new Date(date);
  result.setDate(result.getDate() + days);
  return result;
}

/**
 * Finds an existing event by stored Calendar ID first, then by marker.
 * This allows an event to be moved safely when a holiday is added later.
 */
function upsertEvent(
  calendar,
  title,
  targetDate,
  description,
  monthKey,
  kind,
  marker
) {
  const properties = PropertiesService.getScriptProperties();
  const propertyKey = `intro_event_${monthKey}_${kind}`;

  let event = null;
  const storedEventId = properties.getProperty(propertyKey);

  // First choice: retrieve the exact event previously created.
  if (storedEventId) {
    try {
      const storedEvent = calendar.getEventById(storedEventId);

      if (
        storedEvent &&
        (storedEvent.getDescription() || "").includes(marker)
      ) {
        event = storedEvent;
      }
    } catch (error) {
      // Fall through to marker-based search.
    }
  }

  /*
   * Fallback search covers the whole surrounding period rather than
   * only the new target date. This finds an event at its old date after
   * a holiday causes the target date to change.
   */
  const searchStart = addDays(targetDate, -45);
  const searchEnd = addDays(targetDate, 45);

  const markerMatches = calendar
    .getEvents(searchStart, searchEnd)
    .filter(existing =>
      (existing.getDescription() || "").includes(marker)
    );

  if (!event && markerMatches.length > 0) {
    event = markerMatches.shift();
  }

  if (!event) {
    event = calendar.createAllDayEvent(title, targetDate, {
      description: description
    });
  } else {
    event.setTitle(title);
    event.setAllDayDate(targetDate);
    event.setDescription(description);
  }

  // Store the ID so future date changes can update this exact event.
  properties.setProperty(propertyKey, event.getId());

  // Remove any accidental duplicates carrying the same marker.
  markerMatches.forEach(duplicate => {
    if (duplicate.getId() !== event.getId()) {
      duplicate.deleteEvent();
    }
  });
}

/**
 * Installs one daily trigger and runs the setup immediately.
 */
function installDailyTrigger() {
  ScriptApp.getProjectTriggers()
    .filter(trigger =>
      trigger.getHandlerFunction() === "ensureThisMonth"
    )
    .forEach(trigger => ScriptApp.deleteTrigger(trigger));

  ScriptApp.newTrigger("ensureThisMonth")
    .timeBased()
    .everyDays(1)
    .atHour(6)
    .create();

  ensureThisMonth();
}
```

