}

function dryRunMonth(monthOffset) {
  const calendar = CalendarApp.getCalendarById(TEST_CALENDAR_ID);
  if (!calendar) {
    throw new Error("Test calendar was not found or is not accessible.");
  }

  const today = new Date();
  const targetMonth = new Date(
    today.getFullYear(),
    today.getMonth() + monthOffset,
    1
  );
  const followingMonth = new Date(
    targetMonth.getFullYear(),
    targetMonth.getMonth() + 1,
    1
  );

  const holidays = loadHolidays(
    addDays(targetMonth, -14),
    addDays(followingMonth, 45)
  );

  const firstBusinessDay = getFirstBusinessDay(
    targetMonth.getFullYear(),
    targetMonth.getMonth(),
    holidays
  );

  const finalReminder = nextBusinessDay(
    addDays(firstBusinessDay, 7),
    holidays
  );

  const monthKey = Utilities.formatDate(
    firstBusinessDay,
    Session.getScriptTimeZone(),
    "yyyy-MM"
  );

  Logger.log(`DRY RUN for ${monthKey}`);
  Logger.log(`Planned review date: ${dateKey(firstBusinessDay)}`);
  Logger.log(`Planned final date: ${dateKey(finalReminder)}`);

  inspectPlannedEvent(
    calendar,
    firstBusinessDay,
    monthKey,
    "review",
    `<!-- test-introduction-follow-up:${monthKey}:review -->`
  );

  inspectPlannedEvent(
    calendar,
    finalReminder,
    monthKey,
    "final",
    `<!-- test-introduction-follow-up:${monthKey}:final -->`
  );
}

function inspectPlannedEvent(calendar, targetDate, monthKey, kind, marker) {
  const properties = PropertiesService.getScriptProperties();
  const propertyKey = `test_intro_event_${monthKey}_${kind}`;
  const storedId = properties.getProperty(propertyKey);

  let storedEvent = null;

  if (storedId) {
    try {
      const candidate = calendar.getEventById(storedId);
      if (
        candidate &&
        (candidate.getDescription() || "").includes(marker)
      ) {
        storedEvent = candidate;
      }
    } catch (error) {
      Logger.log(`${kind}: stored ID could not be read: ${storedId}`);
    }
  }

  const markerMatches = calendar
    .getEvents(addDays(targetDate, -370), addDays(targetDate, 370))
    .filter(event =>
      (event.getDescription() || "").includes(marker)
    );

  const allMatches = [];
  if (storedEvent) allMatches.push(storedEvent);
  markerMatches.forEach(event => {
    if (!allMatches.some(existing => existing.getId() === event.getId())) {
      allMatches.push(event);
    }
  });

  Logger.log(`${kind}: stored ID = ${storedId || "(none)"}`);
  Logger.log(
    `${kind}: matching event IDs = ${
      allMatches.length
        ? allMatches.map(event => event.getId()).join(", ")
        : "(none)"
    }`
  );

  if (!allMatches.length) {
    Logger.log(
      `${kind}: WOULD CREATE an event on ${dateKey(targetDate)}`
    );
    return;
  }

  allMatches.forEach(event => {
    const currentDate = event.isAllDayEvent()
      ? event.getAllDayStartDate()
      : event.getStartTime();

    Logger.log(
      `${kind}: ${event.getId()} is on ${dateKey(currentDate)}`
    );
  });

  if (storedEvent) {
    const currentDate = storedEvent.isAllDayEvent()
      ? storedEvent.getAllDayStartDate()
      : storedEvent.getStartTime();

    if (dateKey(currentDate) === dateKey(targetDate)) {
      Logger.log(`${kind}: no move needed`);
    } else {
      Logger.log(
        `${kind}: WOULD MOVE ${storedEvent.getId()} to ` +
        `${dateKey(targetDate)}`
      );
    }
  } else {
    Logger.log(
      `${kind}: WOULD USE the first marker match and move it to ` +
      `${dateKey(targetDate)}`
    );
  }

  if (allMatches.length > 1) {
    Logger.log(
      `${kind}: WOULD REMOVE ${
        allMatches.length - 1
      } duplicate marker match(es)`
    );
  }
}
```

