```javascript
// SAFETY SETTINGS — leave unchanged while testing.
const RUN_MODE = "TEST"; // Change to "REAL" only when ready.
const TEST_CALENDAR_ID = "PASTE_TEST_CALENDAR_ID_HERE";

// REAL mode requires both settings to be changed explicitly.
const REAL_CALENDAR_ID = "";
const ALLOW_REAL_CALENDAR = false;

function getConfiguredCalendar() {
  let calendarId;

  if (RUN_MODE === "TEST") {
    calendarId = TEST_CALENDAR_ID;
    if (!calendarId || calendarId === "PASTE_TEST_CALENDAR_ID_HERE") {
      throw new Error("Configure TEST_CALENDAR_ID before running.");
    }
  } else if (RUN_MODE === "REAL") {
    if (!ALLOW_REAL_CALENDAR) {
      throw new Error(
        "Real-calendar execution is locked. Set ALLOW_REAL_CALENDAR = true explicitly."
      );
    }
    if (!REAL_CALENDAR_ID) {
      throw new Error("Configure REAL_CALENDAR_ID before using real mode.");
    }
    calendarId = REAL_CALENDAR_ID;
  } else {
    throw new Error(`Invalid RUN_MODE: ${RUN_MODE}`);
  }

  const calendar = CalendarApp.getCalendarById(calendarId);
  if (!calendar) {
    throw new Error(`Configured calendar is unavailable: ${calendarId}`);
  }

  Logger.log(`Using ${RUN_MODE} calendar: ${calendar.getName()} (${calendarId})`);
  return calendar;
}
```

