```javascript
function preflight() {
  const calendar = getConfiguredCalendar();
  const calendarName = calendar.getName();
  const calendarId = calendar.getId();

  if (
    RUN_MODE === "TEST" &&
    !calendarName.toUpperCase().includes("TEST")
  ) {
    throw new Error(
      `Safety check failed: TEST mode requires a calendar name containing ` +
      `"TEST". Actual name: "${calendarName}"`
    );
  }

  const today = new Date();
  const targetMonth = new Date(
    today.getFullYear(),
    today.getMonth() + 1,
    1
  );
  const followingMonth = new Date(
    targetMonth.getFullYear(),
    targetMonth.getMonth() + 1,
    1
  );

  const holidays = loadHolidays(
    addDays(targetMonth, -14),
    addDays(followingMonth, 45)
  );

  const reviewDate = getFirstBusinessDay(
    targetMonth.getFullYear(),
    targetMonth.getMonth(),
    holidays
  );
  const finalDate = nextBusinessDay(
    addDays(reviewDate, 7),
    holidays
  );

  Logger.log(`Run mode: ${RUN_MODE}`);
  Logger.log(`Calendar name: ${calendarName}`);
  Logger.log(`Calendar ID: ${calendarId}`);
  Logger.log(`Next review date: ${dateKey(reviewDate)}`);
  Logger.log(`Next final reminder date: ${dateKey(finalDate)}`);
  Logger.log("Preflight passed. No calendar events were changed.");
}
