```js
export class InvalidDateError extends RangeError {
  constructor(message = "Unable to determine export date", options) {
    super(message, options);
    this.name = "InvalidDateError";
  }
}

export function getFilename(now) {
  let date;

  try {
    date = now();
  } catch (error) {
    throw new InvalidDateError("The clock failed", { cause: error });
  }

  if (!(date instanceof Date) || Number.isNaN(date.getTime())) {
    throw new InvalidDateError();
  }

  return `expenses-${date.toISOString().slice(0, 10)}.json`;
}
