```js
export function handleExport(rawEntries, { status, ...exportOptions }) {
  const validEntries = [];
  const skipped = [];

  rawEntries.forEach((entry, index) => {
    const result = validateExpense(entry);

    if (result.ok) {
      validEntries.push(result.value);
    } else {
      skipped.push({
        index,
        entry,
        reason: result.reason
      });
    }
  });

  const validation = {
    acceptedCount: validEntries.length,
    skippedCount: skipped.length,
    skipped
  };

  const exportResult = exportExpenses(validEntries, {
    status,
    ...exportOptions
  });

  return { validation, export: exportResult };
}
```

