export function describeValidation({ acceptedCount, skippedCount, skipped }) {
  const lines = [`Accepted ${acceptedCount}; skipped ${skippedCount}.`];

  for (const item of skipped) {
    lines.push(`Entry ${item.index + 1}: ${item.reason}`);
  }

  return lines.join("\n");
}

export function describeExport(result) {
  if (result.ok) return "Export completed successfully.";
  return result.reason === "invalid-date"
    ? "The export failed because the date was invalid."
    : "The export failed. Please try again.";
}

export function renderExportResult(status, { validation, export: exportResult }) {
  status.textContent =
    `${describeValidation(validation)}\n${describeExport(exportResult)}`;
}
