```js
export function renderExportResult({ status, report, exportButton }, result) {
  const hasSkipped = result.validation.skipped.length > 0;
  const hasExportError = !result.export.ok;
  const needsAttention = hasSkipped || hasExportError;

  status.setAttribute("aria-live", "polite");
  report.setAttribute("aria-live", "off");
  status.textContent = describeExport(result.export);

  report.replaceChildren();
  report.hidden = !needsAttention;

  const heading = document.createElement("h2");
  heading.tabIndex = -1;
  heading.textContent = hasExportError
    ? "Export needs attention"
    : "Validation report";
  report.append(heading);

  const summary = document.createElement("p");
  summary.textContent =
    `Accepted ${result.validation.acceptedCount}; ` +
    `skipped ${result.validation.skippedCount}.`;
  report.append(summary);

  if (hasSkipped) {
    const list = document.createElement("ul");
    for (const item of result.validation.skipped) {
      const li = document.createElement("li");
      li.textContent =
        `Entry ${item.index + 1}: ${item.entry.description} (${item.reason})`;
      list.append(li);
    }
    report.append(list);
  }

  const dismiss = document.createElement("button");
  dismiss.type = "button";
  dismiss.textContent = "Dismiss";
  dismiss.addEventListener("click", () => {
    report.hidden = true;
    exportButton.focus();
  });
  report.append(dismiss);

  if (needsAttention) heading.focus();
  else exportButton.focus();
}
```

