function normalizeSearch(value) {
  return [...value.normalize("NFKD")]
    .map(ch => {
      const code = ch.codePointAt(0);
      // Convert hiragana to katakana.
      return code >= 0x3041 && code <= 0x3096
        ? String.fromCodePoint(code + 0x60)
        : ch;
