```js
function parseMemoTime(value) {
  const text = (value || "").trim();
  if (!text) return null;

  // Simple memo times use a fixed day, so they remain comparable.
  if (/^\d{2}:\d{2}:\d{2}$/.test(text)) {
    const [h, m, s] = text.split(":").map(Number);
    if (h > 23 || m > 59 || s > 59) return null;
    return Date.UTC(1970, 0, 1, h, m, s);
  }

  // Supports ISO date-times such as 2024-03-01T09:00:00Z.
  const timestamp = Date.parse(text.replace(" ", "T"));
  return Number.isNaN(timestamp) ? null : timestamp;
}

function memoTimestamp(figure) {
  return parseMemoTime(figure.dataset.memoTime);
}

// Preserve the generated order for equal times and as a final tie-breaker.
const originalGroupOrder = new Map(groups.map((group, i) => [group, i]));

for (const group of groups) {
  const sheet = group.querySelector(".sheet");
  const groupFigures = [...sheet.querySelectorAll("figure")];

  groupFigures.sort((a, b) => {
    const at = memoTimestamp(a);
    const bt = memoTimestamp(b);
    return (at ?? Infinity) - (bt ?? Infinity);
  });

  groupFigures.forEach(figure => sheet.appendChild(figure));
}

groups.sort((a, b) => {
  const aTimes = [...a.querySelectorAll("figure")]
    .map(memoTimestamp)
    .filter(time => time !== null);
  const bTimes = [...b.querySelectorAll("figure")]
    .map(memoTimestamp)
    .filter(time => time !== null);

  const aEarliest = aTimes.length ? Math.min(...aTimes) : Infinity;
  const bEarliest = bTimes.length ? Math.min(...bTimes) : Infinity;

  return (
    aEarliest - bEarliest ||
    originalGroupOrder.get(a) - originalGroupOrder.get(b)
  );
});

const contactSheet = document.querySelector("#contact-sheet"); // parent of .stop-group
groups.forEach(group => contactSheet.appendChild(group));
```

