function removeEdit(edits, id, token) {
  const edit = edits[id];
  if (!edit || edit.token !== token) return edits;

  const nextEdits = { ...edits };
  delete nextEdits[id];
  return nextEdits;
}

case "commit": {
  const edit = state.edits[action.id];

  // An old blur cannot commit or clear a newer session.
  if (!edit || edit.token !== action.token) return state;

  const ingredient = state.ingredients.find(i => i.id === action.id);

  const stale =
    !ingredient ||
    edit.revision !== state.revision ||
    ingredient.baseQuantity !== edit.baseQuantity ||
    ingredient.baseServings !== edit.baseServings;

  const draft = edit.draft.trim();
  const value = Number(draft);

  const invalid =
    draft === "" ||
    !Number.isFinite(value) ||
    value < 0 ||
    edit.locked <= 0 ||
    ingredient?.baseServings <= 0;

  if (stale || invalid) {
    return {
      ...state,
      edits: removeEdit(state.edits, action.id, action.token)
    };
  }

  const ingredients = state.ingredients.map(current =>
    current.id === action.id
      ? {
          ...current,
          // Both base values were verified above.
          baseQuantity: value * current.baseServings / edit.locked
        }
      : current
  );

  return {
    ...state,
    ingredients,
    edits: removeEdit(state.edits, action.id, action.token)
  };
}
```

