```ts
type UnitPrefs = { displayUnit: Record<string, string> };
const defaultPrefs: UnitPrefs = { displayUnit: {} };

function createUnitPrefsStore(initial: UnitPrefs) {
  let state = initial;
  const listeners = new Set<() => void>();

  if (typeof window !== "undefined") {
    const saved = localStorage.getItem("unit-prefs");
    if (saved) state = { ...initial, ...JSON.parse(saved) };
  }

  return {
    getSnapshot: () => state,
    subscribe: (fn: () => void) => {
      listeners.add(fn);
      return () => listeners.delete(fn);
    },
    set(next: UnitPrefs) {
      state = next;
      localStorage.setItem("unit-prefs", JSON.stringify(next));
      listeners.forEach(fn => fn());
    },
  };
}

const prefsStore = createUnitPrefsStore(
  typeof window !== "undefined"
    ? (window as any).__INITIAL_UNIT_PREFS__ ?? defaultPrefs
    : defaultPrefs
);

export function useDisplayUnit(canonicalUnit: string) {
  return useSyncExternalStoreWithSelector(
    prefsStore.subscribe,
    prefsStore.getSnapshot,
    prefsStore.getSnapshot, // server snapshot must match the bootstrapped value
    prefs => prefs.displayUnit[canonicalUnit] ?? canonicalUnit,
    Object.is
  );
}
```

