  const props = PropertiesService.getScriptProperties();
  const previousMode = props.getProperty(TEST_MODE_KEY);
  props.setProperty(TEST_MODE_KEY, 'false'); // real write for this disposable probe
  const results = [];

  try {
    results.push(probeOne_('On edit', view, log, () =>
      updateViewTimestamp({
        source: ss,
        range: entry.getRange('A2'),
        testMode: false
      })
    ));

    results.push(probeOne_('On change', view, log, () =>
      updateTimestampWhenRowDeleted({
        source: ss,
        changeType: 'REMOVE_ROW',
        testMode: false
      })
    ));
  } finally {
    if (previousMode === null) props.deleteProperty(TEST_MODE_KEY);
    else props.setProperty(TEST_MODE_KEY, previousMode);
  }

  SpreadsheetApp.getUi().alert(
    'Permission check results',
    results.join('\n') +
      '\n\nThe original B1 value and test-mode setting were restored.',
    SpreadsheetApp.getUi().ButtonSet.OK
  );
}

function probeOne_(name, view, log, action) {
  const cell = view.getRange('B1');
  const original = cell.getValue();
  const rowsBefore = log.getLastRow();
  let callError = '';

  try {
    action();
  } catch (err) {
    callError = err.message || String(err);
  }

  const changed = String(cell.getValue()) !== String(original);
  const appended = log.getLastRow() > rowsBefore;

  try {
    if (original === '') cell.clearContent();
    else cell.setValue(original);
  } catch (err) {
    callError += `; restore failed: ${err.message || err}`;
  }

  return `${name}: ${appended && changed && !callError ? 'PASS' : 'FAIL'} ` +
    `(log appended: ${appended ? 'yes' : 'no'}, B1 changed: ${changed ? 'yes' : 'no'}` +
    `${callError ? `, error: ${callError}` : ''})`;
}
```

