```javascript
function runPermissionChecks() {
  const ss = SpreadsheetApp.getActive();
  const view = ss.getSheetByName('View');
  const log = ss.getSheetByName('Timestamp Errors');
  const entry = ss.getSheetByName('Entry');

  if (!view || !log || !entry) {
    throw new Error('View, Entry, or Timestamp Errors sheet is missing.');
  }

  const props = PropertiesService.getScriptProperties();
  const results = [];

  // This probe intentionally performs real writes in the disposable copy.
  props.setProperty(TEST_MODE_KEY, 'false');

  try {
    results.push(probeOne_('On edit', view, log, () =>
      updateViewTimestamp({
        source: ss,
        range: entry.getRange('A2'),
        testMode: false
      })
    ));

    results.push(probeOne_('On change', view, log, () =>
      updateTimestampWhenRowDeleted({
        source: ss,
        changeType: 'REMOVE_ROW',
        testMode: false
      })
    ));
  } finally {
    // Always finish in the safe state, even if a probe fails.
    props.setProperty(TEST_MODE_KEY, 'true');
  }

  SpreadsheetApp.getUi().alert(
    'Permission check results',
    results.join('\n\n') +
      '\n\nThe original View!B1 value was restored. Test mode is now enabled.',
    SpreadsheetApp.getUi().ButtonSet.OK
  );
}

function probeOne_(name, view, log, action) {
  const cell = view.getRange('B1');
  const originalValue = cell.getValue();
  const originalFormula = cell.getFormula();
  const beforeText = formatProbeTime_(originalValue);
  const beforeMs = timestampMillis_(originalValue);
  const rowsBefore = log.getLastRow();
  let callError = '';

  try {
    action();
    SpreadsheetApp.flush();
  } catch (err) {
    callError = err.message || String(err);
  }

  const afterValue = cell.getValue();
  const afterText = formatProbeTime_(afterValue);
  const afterMs = timestampMillis_(afterValue);
  const appended = log.getLastRow() > rowsBefore;
  const changedToNewer =
    beforeMs !== null &&
    afterMs !== null &&
    afterMs > beforeMs;

  // Restore the original formula or value.
  try {
    if (originalFormula) cell.setFormula(originalFormula);
    else if (originalValue === '') cell.clearContent();
    else cell.setValue(originalValue);
  } catch (err) {
    callError += `${callError ? '; ' : ''}restore failed: ${err.message || err}`;
  }

  const passed = appended && changedToNewer && !callError;

  return `${name}: ${passed ? 'PASS' : 'FAIL'}` +
    `\n  Log appended: ${appended ? 'yes' : 'no'}` +
    `\n  Before: ${beforeText}` +
    `\n  After:  ${afterText}` +
    `\n  Newer timestamp: ${changedToNewer ? 'yes' : 'no'}` +
    (callError ? `\n  Error: ${callError}` : '');
}

function timestampMillis_(value) {
  if (value instanceof Date && !isNaN(value.getTime())) {
    return value.getTime();
  }

  const parsed = new Date(value);
  return value !== '' && !isNaN(parsed.getTime()) ? parsed.getTime() : null;
}

function formatProbeTime_(value) {
  if (value === '' || value === null) return '(blank)';

  const date = value instanceof Date ? value : new Date(value);
  if (!isNaN(date.getTime())) {
    return Utilities.formatDate(
      date,
      Session.getScriptTimeZone(),
      'yyyy-MM-dd HH:mm:ss.SSS z'
    );
  }

  return String(value);
}
```

