A copied spreadsheet is **not a guaranteed full restore**: `copyTo()` does not preserve file-level sharing, and inherited/domain access cannot reliably be reproduced or removed by Apps Script. Before testing, create the backup in the owner’s private **My Drive**, do not move it into a shared folder, and save a manifest of every sheet’s visibility plus each protection’s editors and domain-edit setting:

```javascript
function writeBackupManifest_(source, backup) {
  const manifest = {
    sourceId: source.getId(),
    locale: source.getSpreadsheetLocale(),
    timeZone: source.getSpreadsheetTimeZone(),
    sheets: source.getSheets().map(sheet => ({
      name: sheet.getName(),
      hidden: sheet.isSheetHidden(),
      protections: [
        ...sheet.getProtections(SpreadsheetApp.ProtectionType.SHEET),
        ...sheet.getProtections(SpreadsheetApp.ProtectionType.RANGE)
      ].map(p => ({
        type: p.getProtectionType().toString(),
        range: p.getProtectionType() === SpreadsheetApp.ProtectionType.RANGE
          ? p.getRange().getA1Notation() : null,
        description: p.getDescription(),
        warningOnly: p.isWarningOnly(),
        domainEdit: p.isDomainEditAllowed(),
        editors: p.isWarningOnly()
          ? [] : p.getEditors().map(user => user.getEmail()),
        unprotectedRanges: p.getProtectionType() === SpreadsheetApp.ProtectionType.SHEET
          ? p.getUnprotectedRanges().map(r => r.getA1Notation()) : []
      }))
    })
  };

  const file = DriveApp.getFileById(backup.getId());
  file.setDescription(JSON.stringify(manifest, null, 2));
  return manifest;
}
```

Call `writeBackupManifest_(source, backup)` after copying the sheets; for sensitive visa data, also inspect the backup file’s **Share** dialog and Drive permissions before proceeding, because a backup placed in a shared folder, shared drive, or domain-managed location may inherit access that the script cannot remove. The manifest records exact user-editor email addresses, but groups, inherited permissions, and organization policies still require manual verification rather than assuming the backup is private.

Enable the **Advanced Drive service** (Drive API v3), then run this check immediately after creating the backup; it reports explicit and inherited permissions and warns about shared drives or broadly shared parent folders:

```javascript
function checkBackupSharing_(backupId) {
  const fields =
    'id,name,driveId,parents,permissions(' +
    'id,type,role,emailAddress,domain,allowFileDiscovery,' +
    'permissionDetails(inherited,inheritedFrom,permissionType))';

  const file = Drive.Files.get(backupId, {
    fields,
    supportsAllDrives: true
  });
  const warnings = [];

  if (file.driveId) warnings.push('Backup is in a shared drive.');

  (file.permissions || []).forEach(p => {
    const inherited = (p.permissionDetails || []).some(d => d.inherited);
    if (inherited) warnings.push(`Inherited permission: ${permissionSummary_(p)}`);
    if (p.type === 'anyone') warnings.push('Anyone with the link can access the backup.');
    if (p.type === 'domain') warnings.push(`Domain-wide access: ${p.domain || '(domain)'}`);
  });

  (file.parents || []).forEach(parentId => {
    const parent = Drive.Files.get(parentId, {
      fields: 'id,name,driveId,permissions(type,role,emailAddress,domain,allowFileDiscovery)',
      supportsAllDrives: true
    });
    if (parent.driveId) warnings.push(`Parent folder "${parent.name}" is in a shared drive.`);
    (parent.permissions || []).forEach(p => {
      if (p.type === 'anyone' || p.type === 'domain') {
        warnings.push(`Parent folder "${parent.name}" grants ${permissionSummary_(p)}.`);
      }
    });
  });

  return {
    warnings,
    permissions: file.permissions || [],
    report: warnings.length
      ? 'WARNING:\n' + warnings.join('\n')
      : 'No broad or inherited sharing detected; verify the Drive Share dialog manually.'
  };
}

function permissionSummary_(p) {
  return `${p.type} ${p.role} ${p.emailAddress || p.domain || ''}`.trim();
}
```

