```javascript
const STATUS_RANGES = [
  // 'Entry!B1',
  // 'View!B1',
];

function compareWithPermissionBackup() {
  const source = SpreadsheetApp.getActive();
  const backupId = PropertiesService.getScriptProperties()
    .getProperty(PERMISSION_BACKUP_KEY);

  if (!backupId) {
    throw new Error('No permission-test backup ID was found.');
  }

  const backup = SpreadsheetApp.openById(backupId);
  const lines = [
    `Source: ${source.getName()} (${source.getId()})`,
    `Backup: ${backup.getName()} (${backup.getId()})`,
    `Spreadsheet names: ${source.getName() === backup.getName() ? 'MATCH' : 'DIFFER'}`,
    ''
  ];

  ['Entry', 'View'].forEach(name => {
    lines.push(...compareSheetReadOnly_(source, backup, name));
    lines.push('');
  });

  lines.push(...compareStatusRanges_(source, backup));
  lines.push('');
  lines.push('This report did not modify either spreadsheet.');

  const report = lines.join('\n');
  Logger.log(report);

  SpreadsheetApp.getUi().alert(
    'Read-only backup comparison',
    report.length > 9000 ? report.slice(0, 8900) + '\n\n[Report truncated; see Apps Script execution log.]' : report,
    SpreadsheetApp.getUi().ButtonSet.OK
  );

  return report;
}

function compareSheetReadOnly_(source, backup, sheetName) {
  const a = source.getSheetByName(sheetName);
  const b = backup.getSheetByName(sheetName);
  const out = [`[${sheetName}]`];

  if (!a || !b) {
    out.push(`Sheet presence: ${a ? 'source only' : ''}${a && b ? 'both' : ''}${b ? 'backup only' : ''}`);
    return out;
  }

  out.push(`Sheet presence: MATCH`);
  out.push(`Hidden: ${a.isSheetHidden() === b.isSheetHidden() ? 'MATCH' : 'DIFFER'} ` +
    `(source=${a.isSheetHidden()}, backup=${b.isSheetHidden()})`);
  out.push(`Gridlines: ${a.hasHiddenGridlines() === b.hasHiddenGridlines() ? 'MATCH' : 'DIFFER'}`);

  const aRange = a.getDataRange();
  const bRange = b.getDataRange();
  const aFormulas = aRange.getFormulas();
  const bFormulas = bRange.getFormulas();
  const aValues = aRange.getDisplayValues();
  const bValues = bRange.getDisplayValues();

  const formulaDiffs = compareMatrices_(aFormulas, bFormulas, aRange, bRange);
  const valueDiffs = compareMatrices_(aValues, bValues, aRange, bRange);

  out.push(`Formula differences: ${formulaDiffs.length}`);
  formulaDiffs.slice(0, 20).forEach(d => out.push(`  ${d}`));
  if (formulaDiffs.length > 20) out.push('  ...additional formula differences omitted');

  out.push(`Displayed-value differences: ${valueDiffs.length}`);
  valueDiffs.slice(0, 20).forEach(d => out.push(`  ${d}`));
  if (valueDiffs.length > 20) out.push('  ...additional value differences omitted');

  const protectionResult = compareProtectionsReadOnly_(a, b);
  out.push(`Protections: ${protectionResult.same ? 'MATCH' : 'DIFFER'}`);
  protectionResult.differences.slice(0, 20)
    .forEach(d => out.push(`  ${d}`));

  return out;
}

function compareMatrices_(left, right, leftRange, rightRange) {
  const differences = [];
  const rows = Math.max(left.length, right.length);
  const cols = Math.max(
    left.length ? left[0].length : 0,
    right.length ? right[0].length : 0
  );

  for (let r = 0; r < rows; r++) {
    for (let c = 0; c < cols; c++) {
      const x = left[r]?.[c] ?? '';
      const y = right[r]?.[c] ?? '';

      if (x !== y) {
        const row = Math.max(leftRange.getRow(), rightRange.getRow()) + r;
        const col = Math.max(leftRange.getColumn(), rightRange.getColumn()) + c;
        const a1 = columnToLetter_(col) + row;
        differences.push(`${a1}: source=${JSON.stringify(x)}, backup=${JSON.stringify(y)}`);
      }
    }
  }

  return differences;
}

function compareProtectionsReadOnly_(sourceSheet, backupSheet) {
  const left = protectionManifestReadOnly_(sourceSheet);
  const right = protectionManifestReadOnly_(backupSheet);
  const differences = [];

  if (JSON.stringify(left) !== JSON.stringify(right)) {
    differences.push(`source=${JSON.stringify(left)}`);
    differences.push(`backup=${JSON.stringify(right)}`);
  }

  return { same: differences.length === 0, differences };
}

function protectionManifestReadOnly_(sheet) {
  const protections = [
    ...sheet.getProtections(SpreadsheetApp.ProtectionType.SHEET),
    ...sheet.getProtections(SpreadsheetApp.ProtectionType.RANGE)
  ];

  return protections.map(p => ({
    type: String(p.getProtectionType()),
    range: p.getProtectionType() === SpreadsheetApp.ProtectionType.RANGE
      ? p.getRange().getA1Notation()
      : null,
    description: p.getDescription() || '',
    warningOnly: p.isWarningOnly(),
    domainEdit: p.isWarningOnly() ? false : p.isDomainEditAllowed(),
    editors: p.isWarningOnly()
      ? []
      : p.getEditors().map(u => u.getEmail()).sort(),
    unprotectedRanges: p.getProtectionType() === SpreadsheetApp.ProtectionType.SHEET
      ? p.getUnprotectedRanges().map(r => r.getA1Notation()).sort()
      : []
  })).sort((x, y) => JSON.stringify(x).localeCompare(JSON.stringify(y)));
}

function compareStatusRanges_(source, backup) {
  if (!STATUS_RANGES.length) {
    return ['[Statuses]', 'No STATUS_RANGES configured; sheet presence and hidden state were compared.'];
  }

  const out = ['[Statuses]'];

  STATUS_RANGES.forEach(spec => {
    const [sheetName, a1] = spec.split('!');
    const a = source.getSheetByName(sheetName);
    const b = backup.getSheetByName(sheetName);

    if (!a || !b) {
      out.push(`${spec}: sheet missing in ${!a ? 'source' : 'backup'}`);
      return;
    }

    const sourceValue = a.getRange(a1).getDisplayValue();
    const backupValue = b.getRange(a1).getDisplayValue();
    out.push(`${spec}: ${sourceValue === backupValue ? 'MATCH' : 'DIFFER'} ` +
      `(source=${JSON.stringify(sourceValue)}, backup=${JSON.stringify(backupValue)})`);
  });

  return out;
}

function columnToLetter_(column) {
  let result = '';
  while (column > 0) {
    const remainder = (column - 1) % 26;
    result = String.fromCharCode(65 + remainder) + result;
    column = Math.floor((column - 1) / 26);
  }
  return result;
}
```

