    const sourceNames = a.getRange(1, 1, rows, 1).getDisplayValues();
    const backupNames = b.getRange(1, 1, rows, 1).getDisplayValues();
    const sourceStatuses = a.getRange(1, 6, rows, 1).getDisplayValues();
    const backupStatuses = b.getRange(1, 6, rows, 1).getDisplayValues();

    let nameDifferences = 0;
    let statusDifferences = 0;
    const details = [];

    for (let i = 0; i < rows; i++) {
      const row = i + 1;
      const nameDiff = sourceNames[i][0] !== backupNames[i][0];
      const statusDiff = sourceStatuses[i][0] !== backupStatuses[i][0];

      if (nameDiff) {
        nameDifferences++;
        if (details.length < 20) details.push(`  Row ${row}: document name differs`);
      }
      if (statusDiff) {
        statusDifferences++;
        if (details.length < 20) details.push(`  Row ${row}: status differs`);
      }
    }

    out.push(`${sheetName}: document-name differences=${nameDifferences}, ` +
      `status differences=${statusDifferences}, ` +
      `overall=${nameDifferences + statusDifferences === 0 ? 'MATCH' : 'DIFFER'}`);
    out.push(...details);
    if (nameDifferences + statusDifferences > details.length) {
      out.push('  ...additional differences omitted');
    }
  });

  return out;
}
