```javascript
function compareAndSaveBackupReport() {
  const source = SpreadsheetApp.getActive();
  const backupId = PropertiesService.getScriptProperties()
    .getProperty(PERMISSION_BACKUP_KEY);

  if (!backupId) throw new Error('No permission-test backup ID was found.');

  const backup = SpreadsheetApp.openById(backupId);
  const lines = [
    `Source: ${source.getName()} (${source.getId()})`,
    `Backup: ${backup.getName()} (${backup.getId()})`,
    `Spreadsheet names: ${source.getName() === backup.getName() ? 'MATCH' : 'DIFFER'}`,
    ''
  ];

  ['Entry', 'View'].forEach(name => {
    lines.push(...compareSheetReadOnly_(source, backup, name), '');
  });

  lines.push(...compareNamesAndStatusesReadOnly_(source, backup, ['Entry', 'View']), '');

  let sharingCheck;
  lines.push('[Backup sharing warnings]');
  try {
    sharingCheck = checkBackupSharing_(backup.getId());
    lines.push(sharingCheck.report);
  } catch (err) {
    sharingCheck = { warnings: [`Unable to inspect Drive sharing: ${err.message}`] };
    lines.push(`FAIL: ${sharingCheck.warnings[0]}`);
  }

  const summary = getOverallBackupResult_(source, backup, sharingCheck);
  lines.unshift(`[OVERALL RESULT: ${summary.pass ? 'PASS' : 'FAIL'}]`);
  lines.splice(1, 0,
    `Name differences: ${summary.nameDifferences}`,
    `Status differences: ${summary.statusDifferences}`,
    `Formula differences: ${summary.formulaDifferences}`,
    `Protection mismatches: ${summary.protectionMismatches}`,
    `Hidden-sheet mismatches: ${summary.hiddenSheetMismatches}`,
    `Sharing warnings: ${summary.sharingWarnings}`,
    ''
  );

  lines.push('', 'This report did not modify Entry or View.');

  const report = lines.join('\n');
  const reportSheet = source.insertSheet(
    `Backup report ${Utilities.formatDate(
      new Date(), source.getSpreadsheetTimeZone(), 'yyyy-MM-dd HH-mm-ss'
    )}`
  );

  reportSheet.getRange(1, 1, lines.length, 1)
    .setValues(lines.map(line => [line]))
    .setWrap(true);
  reportSheet.setColumnWidth(1, 900);

  SpreadsheetApp.getUi().alert(
    `Backup comparison: ${summary.pass ? 'PASS' : 'FAIL'}`,
    `Saved as "${reportSheet.getName()}". ` +
      (summary.pass
        ? 'No requested differences or sharing warnings were found.'
        : 'Review the FAIL results before restoring the visa checklist.'),
    SpreadsheetApp.getUi().ButtonSet.OK
  );

  return report;
}

function getOverallBackupResult_(source, backup, sharingCheck) {
  let nameDifferences = 0;
  let statusDifferences = 0;
  let formulaDifferences = 0;
  let protectionMismatches = 0;
  let hiddenSheetMismatches = 0;

  ['Entry', 'View'].forEach(sheetName => {
    const a = source.getSheetByName(sheetName);
    const b = backup.getSheetByName(sheetName);

    if (!a || !b) {
      nameDifferences++;
      statusDifferences++;
      formulaDifferences++;
      protectionMismatches++;
      return;
    }

    nameDifferences += columnDifferenceCount_(a, b, 1);
    statusDifferences += columnDifferenceCount_(a, b, 6);

    formulaDifferences += rangeMatrixDifferenceCount_(
      a.getDataRange().getFormulas(),
      b.getDataRange().getFormulas()
    );

    if (JSON.stringify(protectionManifestReadOnly_(a)) !==
        JSON.stringify(protectionManifestReadOnly_(b))) {
      protectionMismatches++;
    }
  });

  const sourceSheets = new Map(
    source.getSheets().map(s => [s.getName(), s.isSheetHidden()])
  );
  const backupSheets = new Map(
    backup.getSheets().map(s => [s.getName(), s.isSheetHidden()])
  );

  const allNames = new Set([...sourceSheets.keys(), ...backupSheets.keys()]);
  allNames.forEach(name => {
    if (sourceSheets.get(name) !== backupSheets.get(name)) {
      hiddenSheetMismatches++;
    }
  });

  const sharingWarnings = (sharingCheck && sharingCheck.warnings)
    ? sharingCheck.warnings.length
    : 1;

  return {
    nameDifferences,
    statusDifferences,
    formulaDifferences,
    protectionMismatches,
    hiddenSheetMismatches,
    sharingWarnings,
    pass: nameDifferences === 0 &&
      statusDifferences === 0 &&
      formulaDifferences === 0 &&
      protectionMismatches === 0 &&
      hiddenSheetMismatches === 0 &&
      sharingWarnings === 0
  };
}

function columnDifferenceCount_(sourceSheet, backupSheet, column) {
  const rows = Math.max(
    sourceSheet.getLastRow(),
    backupSheet.getLastRow(),
    1
  );

  const left = sourceSheet.getRange(1, column, rows, 1).getDisplayValues();
  const right = backupSheet.getRange(1, column, rows, 1).getDisplayValues();

  let count = 0;
  for (let i = 0; i < rows; i++) {
    if (left[i][0] !== right[i][0]) count++;
  }
  return count;
}

function rangeMatrixDifferenceCount_(left, right) {
  const rows = Math.max(left.length, right.length);
  const cols = Math.max(
    left.length ? left[0].length : 0,
    right.length ? right[0].length : 0
  );

  let count = 0;
  for (let r = 0; r < rows; r++) {
    for (let c = 0; c < cols; c++) {
      if ((left[r]?.[c] || '') !== (right[r]?.[c] || '')) count++;
    }
  }
  return count;
}
```

