Use ExifTool to create a CSV from the untouched card copy, then run this read-only script; it groups shots within each folder when successive capture times are no more than two seconds apart:

```bash
exiftool -r -csv -Directory -FileName -DateTimeOriginal \
  -ext CR3 -ext NEF -ext ARW /path/to/card-copy > ingest.csv
```

```python
#!/usr/bin/env python3
import csv
import sys
from collections import defaultdict
from datetime import datetime

GAP_SECONDS = 2.0
INPUT = sys.argv[1] if len(sys.argv) > 1 else "ingest.csv"

def capture_time(row):
    value = row.get("DateTimeOriginal", "").strip()
    for fmt in ("%Y:%m:%d %H:%M:%S", "%Y-%m-%d %H:%M:%S"):
        try:
            return datetime.strptime(value, fmt)
        except ValueError:
            pass
    return None

by_folder = defaultdict(list)

with open(INPUT, newline="", encoding="utf-8-sig") as f:
    for row in csv.DictReader(f):
        t = capture_time(row)
        if t and row.get("FileName"):
            by_folder[row.get("Directory", "")].append((t, row["FileName"]))

for folder, shots in sorted(by_folder.items()):
    shots.sort()
    groups = []
    current = []

    for shot in shots:
        if current and (shot[0] - current[-1][0]).total_seconds() > GAP_SECONDS:
            groups.append(current)
            current = []
        current.append(shot)
    if current:
        groups.append(current)

    for number, group in enumerate(groups, 1):
        if len(group) not in (3, 5):
            print(f"\nFLAG  folder={folder}  group={number}  count={len(group)}")
            for t, name in group:
                print(f"  {t:%Y-%m-%d %H:%M:%S}  {folder}/{name}")
```

