Use `ExposureTime` or `ShutterSpeed` as the primary signature—`ExposureCompensation` is often the same for every frame even when auto-bracketing changes the exposure. This version also starts a new group when a complete 3/5-frame exposure pattern repeats immediately:

```bash
exiftool -r -csv -Directory -FileName -DateTimeOriginal \
  -ExposureTime -ShutterSpeed -ExposureCompensation \
  -ext CR3 -ext NEF -ext ARW /path/to/card-copy > ingest.csv
```

```python
#!/usr/bin/env python3
import csv, sys
from collections import defaultdict
from datetime import datetime

GAP_SECONDS = 2.0
INPUT = sys.argv[1] if len(sys.argv) > 1 else "ingest.csv"

def get_time(row):
    for fmt in ("%Y:%m:%d %H:%M:%S", "%Y-%m-%d %H:%M:%S"):
        try:
            return datetime.strptime(row["DateTimeOriginal"].strip(), fmt)
        except (KeyError, ValueError):
            pass
    return None

def exposure_signature(row):
    # ExposureTime is generally the most useful field for aperture-priority
    # bracketing; fall back when the camera does not write it.
    for field in ("ExposureTime", "ShutterSpeed", "ExposureCompensation"):
        value = row.get(field, "").strip()
        if value:
            return field, value
    return "missing", ""

folders = defaultdict(list)

with open(INPUT, newline="", encoding="utf-8-sig") as f:
    for row in csv.DictReader(f):
        t = get_time(row)
        if t and row.get("FileName"):
            folders[row.get("Directory", "")].append(
                (t, row["FileName"], exposure_signature(row))
            )

for folder, shots in sorted(folders.items()):
    shots.sort()
    bursts, current = [], []

    for shot in shots:
        starts_new = False

        if current:
            gap = (shot[0] - current[-1][0]).total_seconds()
            starts_new = gap > GAP_SECONDS

            # If a complete bracket's first exposure repeats, treat it as
            # the beginning of a second bracket fired very quickly.
            sigs = [x[2] for x in current]
            complete = len(current) in (3, 5)
            distinct = len(set(sigs)) == len(sigs)
            repeats_first = shot[2] == current[0][2]
            starts_new |= complete and distinct and repeats_first

        if starts_new:
            bursts.append(current)
            current = []

        current.append(shot)

    if current:
        bursts.append(current)

    for n, group in enumerate(bursts, 1):
        signatures = [x[2] for x in group]
        problems = []

        if len(group) not in (3, 5):
            problems.append(f"count={len(group)}")
        if ("missing", "") in signatures:
            problems.append("missing exposure metadata")
        elif len(set(signatures)) != len(signatures):
            problems.append("repeated exposure setting")

        if problems:
            print(f"\nFLAG folder={folder} group={n} ({', '.join(problems)})")
            for t, name, sig in group:
                print(f"  {t:%Y-%m-%d %H:%M:%S}  {folder}/{name}  {sig[0]}={sig[1]}")
```

Run it with `python check_brackets.py ingest.csv`; treat the exposure-pattern check as a strong heuristic rather than proof, since some cameras omit bracket-specific metadata or write identical exposure times when bracketing aperture or ISO.

Use total exposure EV rather than shutter speed alone: `EV100 = log2(aperture² / shutter_seconds) − log2(ISO / 100)`, so an ISO or aperture change is reflected even when shutter speed repeats. Export `FNumber` and `ISO`, then use this read-only checker:

```bash
exiftool -r -csv -Directory -FileName -DateTimeOriginal \
  -ExposureTime -FNumber -ISO -ShutterSpeed \
  -ext CR3 -ext NEF -ext ARW /path/to/card-copy > ingest.csv
```

```python
#!/usr/bin/env python3
import csv, math, re, sys
from collections import defaultdict
from datetime import datetime

GAP_SECONDS = 2.0
EV_TOLERANCE = 0.30       # metadata rounding tolerance, in EV
INPUT = sys.argv[1] if len(sys.argv) > 1 else "ingest.csv"

def number(value):
    """Parse values such as 0.25, 1/4, '1/4 s', or '2.8'."""
    if not value:
        return None
    value = value.strip().replace(" s", "")
    match = re.search(r"(-?\d+(?:\.\d+)?)\s*/\s*(\d+(?:\.\d+)?)", value)
    if match:
        denominator = float(match.group(2))
        return float(match.group(1)) / denominator if denominator else None
    match = re.search(r"-?\d+(?:\.\d+)?", value)
    return float(match.group()) if match else None

def capture_time(row):
    value = row.get("DateTimeOriginal", "").strip()
    for fmt in ("%Y:%m:%d %H:%M:%S.%f",
                "%Y:%m:%d %H:%M:%S",
                "%Y-%m-%d %H:%M:%S.%f",
                "%Y-%m-%d %H:%M:%S"):
        try:
            return datetime.strptime(value, fmt)
        except ValueError:
            pass
    return None

def exposure_ev(row):
    seconds = number(row.get("ExposureTime", ""))
    aperture = number(row.get("FNumber", ""))
    iso = number(row.get("ISO", "")) or 100.0

    # If ExposureTime is absent, ShutterSpeed is usually exported as 1/4,
    # 0.25, etc.; this fallback is less reliable on some cameras.
    if seconds is None:
        seconds = number(row.get("ShutterSpeed", ""))

    if not seconds or not aperture or not iso or seconds <= 0:
        return None
    return math.log2((aperture * aperture) / seconds) - math.log2(iso / 100.0)

def close(a, b):
    return a is not None and b is not None and abs(a - b) <= EV_TOLERANCE

def distinct_evs(group):
    values = [x[2] for x in group if x[2] is not None]
    return len(values) == len(group) and all(
        abs(a - b) > EV_TOLERANCE
        for i, a in enumerate(values)
        for b in values[i + 1:]
    )

def plausible_boundary(group, next_ev):
    # A repeated first EV after two or more distinct exposures is a useful
    # boundary marker, even when the preceding bracket is incomplete.
    return (
        len(group) >= 2 and next_ev is not None and
        distinct_evs(group) and close(next_ev, group[0][2])
    )

def split_bursts(shots):
    bursts, current = [], []
    for shot in shots:
        if current:
            gap = (shot[0] - current[-1][0]).total_seconds()
            if gap > GAP_SECONDS or plausible_boundary(current, shot[2]):
                bursts.append(current)
                current = []
        current.append(shot)
    if current:
        bursts.append(current)
    return bursts

folders = defaultdict(list)

with open(INPUT, newline="", encoding="utf-8-sig") as f:
    for row in csv.DictReader(f):
        t = capture_time(row)
        if t and row.get("FileName"):
            folders[row.get("Directory", "")].append(
                (t, row["FileName"], exposure_ev(row))
            )

for folder, shots in sorted(folders.items()):
    shots.sort(key=lambda x: x[0])

    for group_number, group in enumerate(split_bursts(shots), 1):
        evs = [x[2] for x in group]
        problems = []

        if len(group) not in (3, 5):
            problems.append(f"count={len(group)}")
        if any(ev is None for ev in evs):
            problems.append("missing exposure metadata")
        elif len(evs) != len(set(round(ev / EV_TOLERANCE) for ev in evs)):
            problems.append("repeated effective exposure")

        steps = [
            evs[i + 1] - evs[i]
            for i in range(len(evs) - 1)
            if evs[i] is not None and evs[i + 1] is not None
        ]

        if problems:
            print(
                f"\nFLAG folder={folder} group={group_number} "
                f"({', '.join(problems)})"
            )
            for i, (t, name, ev) in enumerate(group):
                label = ""
                if ev is not None and len(evs) in (3, 5):
                    rank = sorted(evs).index(ev)
                    label = f"  level={rank + 1}/{len(evs)}"
                print(
                    f"  {t:%Y-%m-%d %H:%M:%S.%f}  "
                    f"{folder}/{name}  EV100={ev if ev is not None else 'NA'}{label}"
                )
            if steps:
                print("  EV steps:", ", ".join(f"{step:+.2f}" for step in steps))
```

Here a higher EV100 means a darker exposure setting, while a lower value means a brighter one; a three-frame dark/base/bright sequence will therefore show three distinct EVs even if two files share the same shutter speed. The EV calculation describes camera settings, not scene brightness, so treat missing `FNumber` or `ISO` metadata as a review flag rather than silently trusting shutter speed alone.

Export the alternate ISO tags as well:

```bash
exiftool -r -csv -Directory -FileName -DateTimeOriginal \
  -ExposureTime -ShutterSpeed -FNumber -ISO \
  -ISOSpeedRatings -RecommendedExposureIndex \
  -ext CR3 -ext NEF -ext ARW /path/to/card-copy > ingest.csv
```

```python
#!/usr/bin/env python3
import csv, math, re, sys
from collections import defaultdict
from datetime import datetime

GAP_SECONDS = 2.0
EV_TOLERANCE = 0.5
INPUT = sys.argv[1] if len(sys.argv) > 1 else "ingest.csv"

def number(value):
    """Parse 0.25, 1/4, '1/4 s', or '2.8'; return None for Auto/blank."""
    if not value:
        return None
    value = value.strip().replace(" s", "")
    m = re.search(r"(-?\d+(?:\.\d+)?)\s*/\s*(\d+(?:\.\d+)?)", value)
    if m:
        denominator = float(m.group(2))
        return float(m.group(1)) / denominator if denominator else None
    m = re.search(r"-?\d+(?:\.\d+)?", value)
    return float(m.group()) if m else None

def capture_time(row):
    value = row.get("DateTimeOriginal", "").strip()
    for fmt in ("%Y:%m:%d %H:%M:%S.%f", "%Y:%m:%d %H:%M:%S",
                "%Y-%m-%d %H:%M:%S.%f", "%Y-%m-%d %H:%M:%S"):
        try:
            return datetime.strptime(value, fmt)
        except ValueError:
            pass
    return None

def iso_value(row):
    # A numeric ISO field wins; Auto/blank falls through to the alternatives.
    for field in ("ISO", "ISOSpeedRatings", "RecommendedExposureIndex"):
        value = number(row.get(field, ""))
        if value is not None and value > 0:
            return value, field
    return None, None

def exposure_ev(row):
    seconds = number(row.get("ExposureTime", "")) or \
              number(row.get("ShutterSpeed", ""))
    aperture = number(row.get("FNumber", ""))
    iso, iso_source = iso_value(row)

    if not seconds or not aperture or not iso:
        return None, iso_source

    ev100 = math.log2((aperture * aperture) / seconds) \
            - math.log2(iso / 100.0)
    return ev100, iso_source

def distinct(evs):
    return all(abs(a - b) > EV_TOLERANCE
               for i, a in enumerate(evs) for b in evs[i + 1:])

def starts_new_burst(current, shot):
    if not current:
        return False

    gap = (shot[0] - current[-1][0]).total_seconds()
    if gap > GAP_SECONDS:
        return True

    # A repeated first EV after at least two distinct exposures suggests
    # another bracket began before the time gap became large enough.
    current_evs = [item[2] for item in current]
    return (
        len(current) >= 2
        and all(ev is not None for ev in current_evs)
        and distinct(current_evs)
        and shot[2] is not None
        and abs(shot[2] - current_evs[0]) <= EV_TOLERANCE
    )

def split_bursts(shots):
    bursts, current = [], []
    for shot in shots:
        if starts_new_burst(current, shot):
            bursts.append(current)
            current = []
        current.append(shot)
    if current:
        bursts.append(current)
    return bursts

def labels_for(group):
    """Return labels in capture order, or None if EVs cannot be ranked."""
    evs = [item[2] for item in group]
    if len(evs) not in (3, 5) or any(ev is None for ev in evs):
        return None
    if not distinct(evs):
        return None

    if len(evs) == 3:
        names = ["dark", "base", "bright"]
    else:
        names = ["dark", "dark-mid", "base", "bright-mid", "bright"]

    # Higher EV100 represents the darker exposure setting.
    order = sorted(range(len(evs)), key=lambda i: evs[i], reverse=True)
    result = [None] * len(evs)
    for rank, index in enumerate(order):
        result[index] = names[rank]
    return result

folders = defaultdict(list)

with open(INPUT, newline="", encoding="utf-8-sig") as f:
    for row in csv.DictReader(f):
        timestamp = capture_time(row)
        if timestamp and row.get("FileName"):
            ev, iso_source = exposure_ev(row)
            folders[row.get("Directory", "")].append(
                (timestamp, row["FileName"], ev, iso_source)
            )

for folder, shots in sorted(folders.items()):
    shots.sort(key=lambda item: (item[0], item[1]))

    for group_number, group in enumerate(split_bursts(shots), 1):
        evs = [item[2] for item in group]
        problems = []

        if len(group) not in (3, 5):
            problems.append(f"count={len(group)}")
        if any(ev is None for ev in evs):
            problems.append("unknown EV/ISO")
        elif not distinct(evs):
            problems.append("repeated effective exposure")

        labels = labels_for(group)
        if labels is not None:
            expected = (
                ["dark", "base", "bright"] if len(group) == 3 else
                ["dark", "dark-mid", "base", "bright-mid", "bright"]
            )
            if labels != expected:
                problems.append("wrong time order: " + " -> ".join(labels))

        if problems:
            print(f"\nFLAG folder={folder} group={group_number} "
                  f"({', '.join(problems)})")

            for position, (timestamp, filename, ev, iso_source) in enumerate(group, 1):
                label = labels[position - 1] if labels else "unknown"
                ev_text = f"{ev:.2f}" if ev is not None else "unknown"
                iso_text = iso_source or "none"
                print(
                    f"  {position}: {timestamp:%Y-%m-%d %H:%M:%S.%f}  "
                    f"{folder}/{filename}  EV100={ev_text}  "
                    f"ISO={iso_text}  expected={label}"
                )
```

For a valid three-frame bracket, the expected capture order is `dark -> base -> bright`; the script flags reversed or otherwise misordered sequences while retaining the folder and original filename for review.

