  const valid = new Set(ingredients.map(i => i.id));

  setEdits(prev => {
    const next = { ...prev };

    for (const [id, edit] of Object.entries(prev)) {
      const wasAlreadyKnown = knownSessions.current.get(id) === edit.token;
      if (!valid.has(id) && wasAlreadyKnown) delete next[id];
