    if (prev[id]?.token !== token) return prev; // cannot delete a newer session
    const next = { ...prev };
    delete next[id];
    return next;
  });
}

function cancelEdit(id, token) {
  setEdits(prev => {
    if (prev[id]?.token !== token) return prev;
    const next = { ...prev };
    delete next[id];
    return next;
  });
}

useEffect(() => {
  const validIds = new Set(list.ingredients.map(i => i.id));

  setEdits(prev => Object.fromEntries(
    Object.entries(prev).filter(([id, edit]) =>
      validIds.has(id) || edit.revision >= list.revision
    )
