Use a single `useReducer` state so refreshes, edits, and commits are serialized through the same current snapshot; functional setters alone cannot make separate `list` and `edits` updates atomic:

```js
function reducer(state, action) {
  switch (action.type) {
    case "replace": {
      const revision = state.revision + 1;
      const valid = new Set(action.ingredients.map(i => i.id));

      return {
        revision,
        ingredients: action.ingredients,
        edits: Object.fromEntries(
          Object.entries(state.edits).filter(([id, e]) =>
            valid.has(id) || e.revision >= revision
          )
        )
      };
    }

    case "begin":
      return {
        ...state,
        edits: {
          ...state.edits,
          [action.id]: {
            token: action.token,
            draft: String(action.displayedValue),
            locked: action.locked,
            revision: state.revision
          }
        }
      };

    case "commit": {
      const edit = state.edits[action.id];
      if (!edit || edit.token !== action.token) return state; // stale blur

      const value = Number(edit.draft);
      const valid = edit.draft.trim() &&
        Number.isFinite(value) && value >= 0 && edit.locked > 0;

      const ingredients =
        valid && edit.revision === state.revision
          ? state.ingredients.map(i =>
              i.id === action.id
                ? { ...i, baseQuantity: value * i.baseServings / edit.locked }
                : i
            )
          : state.ingredients;

      const edits = { ...state.edits };
      delete edits[action.id];

      return { ...state, ingredients, edits };
    }
  }
}
```

