Use a ref owned by each input instance; generate the token inside `onFocus`, store it synchronously, and read that same ref in `onBlur` rather than capturing `list`, `edits`, or a token from render state:

```jsx
function QuantityInput({ id, displayedValue, servings }) {
  const [state, dispatch] = useReducer(reducer, initialState);
  const sessionRef = useRef(null);

  const begin = () => {
    const token = Symbol(id);
    sessionRef.current = token;
    dispatch({
      type: "begin",
      id,
      token,
      displayedValue,
      locked: servings
    });
  };

  const commit = () => {
    const token = sessionRef.current;
    if (token) dispatch({ type: "commit", id, token });
    sessionRef.current = null;
  };

  return (
    <input
      value={state.edits[id]?.draft ?? String(displayedValue)}
      onFocus={begin}
      onChange={e =>
        dispatch({ type: "change", id, draft: e.target.value })
      }
      onBlur={commit}
    />
  );
}
```

The action creators can simply return plain actions—`beginEdit(id, displayedValue, locked)` creates the token and returns both the action and token, while `commitQuantity(id, token)` returns `{ type: "commit", id, token }`; the reducer remains the only place that validates the token and revision against its current state.

