function reducer(state, action) {
  switch (action.type) {
    case "replace": {
      const revision = state.revision + 1;
      const validIds = new Set(action.ingredients.map(i => i.id));

      return {
        revision,
        ingredients: action.ingredients,
        edits: Object.fromEntries(
          Object.entries(state.edits).filter(([id, edit]) =>
            validIds.has(id) || edit.revision >= revision
          )
        )
      };
    }

    case "begin":
      return {
        ...state,
        edits: {
          ...state.edits,
          [action.id]: {
            token: action.token,
            draft: String(action.displayedValue),
            locked: action.locked,
            revision: state.revision
          }
        }
      };

    case "change": {
      const edit = state.edits[action.id];

      // Ignore changes from an input session that has been superseded.
      if (!edit || edit.token !== action.token) return state;

      return {
        ...state,
        edits: {
          ...state.edits,
          [action.id]: { ...edit, draft: action.draft }
        }
      };
    }

    // Keep the existing "commit" case here.
    default:
      return state;
  }
}

function IngredientEditor({ initialIngredients, servings }) {
  const [state, dispatch] = useReducer(reducer, {
    revision: 0,
    ingredients: initialIngredients,
    edits: {}
  });

  async function refreshIngredients() {
    const nextIngredients = await fetchIngredients();
    // The reducer increments the revision and replaces the list atomically.
    dispatch({ type: "replace", ingredients: nextIngredients });
