    <>
      <button onClick={refreshIngredients}>Refresh</button>

      {state.ingredients.map(ingredient => (
        <QuantityInput
          key={ingredient.id}
          id={ingredient.id}
          displayedValue={ingredient.baseQuantity}
          servings={servings}
          edit={state.edits[ingredient.id]}
          dispatch={dispatch}
        />
      ))}
    </>
  );
}

