function protectTimestampLog_() {
  const ss = SpreadsheetApp.getActive();
  const log = ss.getSheetByName('Timestamp Errors');
  if (!log) throw new Error('Timestamp Errors sheet does not exist.');

  const ownerEmail = Session.getEffectiveUser().getEmail();
  if (!ownerEmail) throw new Error('Could not determine the script owner.');

  const description = 'Timestamp error log — script owner only';
  const protections = log.getProtections(SpreadsheetApp.ProtectionType.SHEET);
