  protection.setWarningOnly(false);
  protection.setUnprotectedRanges([]);
  protection.setEditors([ownerEmail]);

  ss.toast(`Timestamp log protected; only ${ownerEmail} can edit it.`, 'Protection enabled', 6);
}
