function copySheetSettings_(source, target) {
  target.setHiddenGridlines(source.hasHiddenGridlines());
  if (source.isSheetHidden() && target.getParent().getSheets().length > 1) {
    target.hideSheet();
  }

  source.getProtections(SpreadsheetApp.ProtectionType.SHEET).forEach(src => {
    const dst = target.protect()
      .setDescription(src.getDescription() || '')
      .setWarningOnly(src.isWarningOnly());

    if (!src.isWarningOnly()) {
      dst.setUnprotectedRanges(
        src.getUnprotectedRanges().map(r =>
          target.getRange(r.getA1Notation())
        )
      );
    }
  });

  source.getProtections(SpreadsheetApp.ProtectionType.RANGE).forEach(src => {
    const dst = target.getRange(src.getRange().getA1Notation()).protect()
      .setDescription(src.getDescription() || '')
      .setWarningOnly(src.isWarningOnly());

    if (!src.isWarningOnly()) {
      dst.setEditors([Session.getEffectiveUser().getEmail()]);
