Use an **Input** sheet for document/deadline fields and protect the formula columns (**W, X, Z**, etc.) for all rows; keep a blank, preformatted template row at the bottom and add new records by copying only the input columns, not the whole row. For a quick audit trail, create an **Audit log** sheet and install this Apps Script as an **installable “On edit” trigger**:

```javascript
function auditDeadlineEdit(e) {
  const sheet = e.range.getSheet();
  const watched = {17:"Filing deadline", 21:"Interview deadline",
                  22:"Visa-issuance deadline", 25:"Applicability confirmed"};
  const col = e.range.getColumn();

  if (sheet.getName() !== "Applications" || e.range.getRow() < 2 ||
      e.range.getNumRows() !== 1 || e.range.getNumColumns() !== 1 ||
      !watched[col]) return;

  const log = e.source.getSheetByName("Audit log") ||
              e.source.insertSheet("Audit log");
  if (log.getLastRow() === 0)
    log.appendRow(["Timestamp","User","Sheet","Cell","Field","Old value","New value"]);

  const user = e.user ? e.user.getEmail() : Session.getActiveUser().getEmail();
  log.appendRow([new Date(), user, sheet.getName(), e.range.getA1Notation(),
                 watched[col], e.oldValue || "", e.value || ""]);
}
```

