function auditDeadlineEdit(e) {
  const s = e.range.getSheet();
  const watched = {17:"Filing deadline",21:"Interview deadline",
                   22:"Visa-issuance deadline",25:"Applicability confirmed"};
  if (s.getName() !== "Applications" || e.range.getRow() < 2) return;

  const log = e.source.getSheetByName("Audit log") || e.source.insertSheet("Audit log");
  if (log.getLastRow() === 0)
    log.appendRow(["Timestamp","User","Sheet","Cell","Field","Old value","New value"]);

  const values = e.range.getValues();
  const user = e.user ? e.user.getEmail() : Session.getActiveUser().getEmail();
  const rows = [];

  for (let r = 0; r < values.length; r++)
    for (let c = 0; c < values[r].length; c++) {
      const field = watched[e.range.getColumn() + c];
      if (field)
        rows.push([new Date(), user, s.getName(),
          s.getRange(e.range.getRow() + r, e.range.getColumn() + c).getA1Notation(),
          field, e.range.getNumRows() === 1 && e.range.getNumColumns() === 1
            ? (e.oldValue || "") : "[bulk paste—old value unavailable]",
          values[r][c]]);
    }
  if (rows.length) log.getRange(log.getLastRow() + 1, 1, rows.length, 7).setValues(rows);
}
