Set up **Staging** with the same headers as `Applications` for columns **A:V**; paste complete input rows there, using the unique application ID in column **A** to update an existing row or append a new one. Protect **W:X** and **Z** on `Applications`, leave **Staging** editable, and add this script; it uses one batch ID and records the staging paste range with exact old/new values for the watched fields:

```javascript
function onOpen() {
  SpreadsheetApp.getUi()
    .createMenu("Application tools")
    .addItem("Apply staged rows", "applyStagedRows")
    .addToUi();
}

function applyStagedRows() {
  const ss = SpreadsheetApp.getActive();
  const app = ss.getSheetByName("Applications");
  const stage = ss.getSheetByName("Staging");
  const log = ss.getSheetByName("Audit log") || ss.insertSheet("Audit log");

  if (!app || !stage) throw new Error("Applications or Staging sheet is missing.");

  const lastStageRow = stage.getLastRow();
  if (lastStageRow < 2) throw new Error("There are no staged rows to apply.");

  if (log.getLastRow() === 0) {
    log.appendRow([
      "Batch ID", "Timestamp", "User", "Source range",
      "Destination", "Cell", "Field", "Old value", "New value"
    ]);
  }

  const sourceRange = `Staging!A2:V${lastStageRow}`;
  const staged = stage.getRange(2, 1, lastStageRow - 1, 22).getValues();
  const batchId = Utilities.getUuid();
  const timestamp = new Date();
  const user = Session.getActiveUser().getEmail() || "Unknown user";

  const appLastRow = Math.max(app.getLastRow(), 2);
  const ids = app.getRange(2, 1, appLastRow - 1, 1).getDisplayValues();
  const idToRow = new Map();
  let lastIdRow = 1;

  ids.forEach((row, i) => {
    const id = String(row[0]).trim();
    if (id) {
      idToRow.set(id, i + 2);
      lastIdRow = i + 2;
    }
  });

  const watched = {
    17: "Filing deadline",       // Q
    21: "Interview deadline",    // U
    22: "Visa-issuance deadline",// V
    25: "Applicability confirmed"// Y, handled separately below
  };

  const auditRows = [];

  staged.forEach(inputRow => {
    if (inputRow.every(value => value === "")) return;

    const id = String(inputRow[0]).trim();
    if (!id) throw new Error("Every staged row must contain an application ID in column A.");

    let targetRow = idToRow.get(id);
    if (!targetRow) {
      targetRow = ++lastIdRow;
      idToRow.set(id, targetRow);
    }

    // Snapshot the old input values before overwriting them.
    const oldInput = app.getRange(targetRow, 1, 1, 22).getDisplayValues()[0];
    app.getRange(targetRow, 1, 1, 22).setValues([inputRow]);

    // Copy formulas into newly appended rows without copying protected values.
    if (targetRow > 2 && !oldInput[0]) {
      app.getRange(targetRow - 1, 23, 1, 2)
        .copyTo(app.getRange(targetRow, 23, 1, 2),
                SpreadsheetApp.CopyPasteType.PASTE_FORMULA, false);
      app.getRange(targetRow - 1, 26)
        .copyTo(app.getRange(targetRow, 26),
                SpreadsheetApp.CopyPasteType.PASTE_FORMULA, false);
    }

    const newInput = app.getRange(targetRow, 1, 1, 22).getDisplayValues()[0];
    const watchedInputColumns = [17, 21, 22]; // Q, U, V

    watchedInputColumns.forEach(column => {
      const index = column - 1;
      if (oldInput[index] !== newInput[index]) {
        auditRows.push([
          batchId, timestamp, user, sourceRange,
          app.getName(), app.getRange(targetRow, column).getA1Notation(),
          watched[column], oldInput[index], newInput[index]
        ]);
      }
    });

    // Confirmation is column Y, which is outside the A:V staging input range.
    // If you want to stage it too, add it as a separate staging column and copy it here.
  });

  if (auditRows.length) {
    log.getRange(log.getLastRow() + 1, 1, auditRows.length, 9)
      .setValues(auditRows);
  }

  stage.getRange(2, 1, lastStageRow - 1, 22).clearContent();
  SpreadsheetApp.getUi().alert(`Applied batch ${batchId} and logged ${auditRows.length} field change(s).`);
}
```

