  const staged = stage
    .getRange(2, 1, lastStageRow - 1, 23)
    .getDisplayValues()
    .filter(row => row.some(value => value.trim() !== ""));

  const appLastRow = Math.max(app.getLastRow(), 2);
  const appValues = app
    .getRange(2, 1, appLastRow - 1, 25)
    .getDisplayValues();

