    }

    if (stagedIds.has(id)) duplicateStaged.add(id);
    stagedIds.add(id);
  });

  duplicateExisting.forEach(id => {
    historyRows.push([
      batchId, timestamp, "Duplicate existing ID", id, "", "", "",
      "The ID appears more than once in Applications."
    ]);
  });

  duplicateStaged.forEach(id => {
    historyRows.push([
      batchId, timestamp, "Duplicate staged ID", id, "", "", "",
      "The ID appears more than once in this staging batch."
    ]);
  });

  missingIdRows.forEach(rowNumber => {
    historyRows.push([
      batchId, timestamp, "Validation error", "", "", "", "",
      `Staging row ${rowNumber} has no application ID in column A.`
