  if (!hasValidationErrors && newRowCount === 0 && changeCount === 0) {
    historyRows.push([
      batchId, timestamp, "Summary", "", "", "", "",
      "No watched fields would change and no new rows would be appended."
    ]);
  } else {
    historyRows.push([
      batchId, timestamp, "Summary", "", "", "", "",
      `Rows reviewed: ${staged.length}; New rows: ${newRowCount}; ` +
      `Changed watched fields: ${changeCount}; ` +
      `Validation errors: ${hasValidationErrors ? "Yes" : "No"}; ` +
      `User: ${user}; Source: ${sourceRange}`
    ]);
