Yes—store a SHA-256 fingerprint of `Staging!A:W` in each preview summary, then compare it immediately before applying. Add this helper:

```javascript
function getStagingSnapshot_(stage) {
  const lastRow = stage.getLastRow();
  const values = lastRow >= 2
    ? stage.getRange(2, 1, lastRow - 1, 23).getDisplayValues()
    : [];

  const payload = JSON.stringify({ lastRow, values });
  const digest = Utilities.computeDigest(
    Utilities.DigestAlgorithm.SHA_256,
    payload,
    Utilities.Charset.UTF_8
  );

  const hash = digest
    .map(byte => (byte < 0 ? byte + 256 : byte).toString(16).padStart(2, "0"))
    .join("");

  return { lastRow, values, hash };
}
