  try {
    const ss = SpreadsheetApp.getActive();
    const ui = SpreadsheetApp.getUi();
    getAuthorizedUser_();

    const idResponse = ui.prompt(
      "Apply approved preview",
      "Enter the exact approved Preview history batch ID:",
      ui.ButtonSet.OK_CANCEL
    );
    if (idResponse.getSelectedButton() !== ui.Button.OK) return;

    const batchId = idResponse.getResponseText().trim();
    const props = PropertiesService.getDocumentProperties();
    const statusKey = APPLY_STATUS_PREFIX + batchId;
    const status = props.getProperty(statusKey);

    if (status) {
      throw new Error(`This batch is already marked ${status}; it cannot be reused.`);
    }

    const preview = getPreviewSummary_(ss, batchId);
    if (!preview) throw new Error("Preview batch was not found.");
    if (preview.hasValidationErrors) {
      throw new Error("A preview with validation errors cannot be applied.");
    }

    assertPreviewIntact_(ss, batchId);
    const approval = getAndVerifyApproval_(ss, batchId);

    const stage = ss.getSheetByName("Staging");
    let snapshot = getStagingSnapshot_(stage);
    if (snapshot.hash !== preview.hash ||
        snapshot.hash !== approval.stagingHash) {
      throw new Error("Staging no longer matches the approved preview.");
    }

    ui.alert(
      `Batch ${batchId} is approved by ${approval.approvedBy}.\n\n` +
      "Application will now write the reviewed changes."
    );

    // Final tamper and staging checks immediately before the first write.
    assertPreviewIntact_(ss, batchId);
    snapshot = getStagingSnapshot_(stage);
    if (snapshot.hash !== preview.hash) {
      throw new Error("Staging changed immediately before apply.");
    }

    // Mark APPLYING first: a crash cannot silently permit a second attempt.
    props.setProperty(statusKey, "APPLYING");

    try {
      writeApplicationRows_(ss, batchId); // Your existing destination-write logic.
      SpreadsheetApp.flush();
      props.setProperty(statusKey, "APPLIED");
    } catch (err) {
      // APPLYING deliberately remains set, preventing an unsafe retry.
      throw new Error(`Application failed and was locked: ${err.message}`);
    }

    ui.alert(`Batch ${batchId} was applied successfully.`);
  } catch (err) {
    SpreadsheetApp.getUi().alert(`Apply stopped: ${err.message}`);
  } finally {
    lock.releaseLock();
  }
}

function assertPreviewIntact_(ss, batchId) {
  const props = PropertiesService.getDocumentProperties();
  const expected = props.getProperty(PREVIEW_DIGEST_PREFIX + batchId);
  if (!expected) throw new Error("No trusted digest exists for this preview batch.");

  const history = ss.getSheetByName("Preview history");
  if (!history) throw new Error("Preview history is missing.");

  const rows = history.getDataRange().getDisplayValues()
    .filter(row => row[0].trim() === batchId && row[2] !== "Approval");

  const actual = sha256Hex_(JSON.stringify(rows));
  if (actual !== expected) {
    throw new Error(
      "Preview history was altered, deleted, or reordered since preview creation."
    );
  }
}

function getAndVerifyApproval_(ss, batchId) {
  const raw = PropertiesService.getDocumentProperties()
    .getProperty(APPROVAL_PREFIX + batchId);
  if (!raw) throw new Error("No approval exists for this preview batch.");

  const approval = JSON.parse(raw);
  const history = ss.getSheetByName("Preview history");
  const matches = history.getDataRange().getDisplayValues()
    .filter(row =>
      row[0].trim() === batchId &&
      row[2] === "Approval" &&
      row[7].includes(`Approval token: ${approval.token}`)
    );

  if (matches.length !== 1 ||
      sha256Hex_(JSON.stringify(matches[0])) !== approval.digest) {
    throw new Error("The approval record is missing or has been altered.");
  }

  return approval;
}

function sha256Hex_(text) {
  return Utilities.computeDigest(
    Utilities.DigestAlgorithm.SHA_256,
    text,
    Utilities.Charset.UTF_8
  ).map(b => (b < 0 ? b + 256 : b).toString(16).padStart(2, "0"))
   .join("");
}
```

When creating each preview, store its digest with `PREVIEW_DIGEST_PREFIX + batchId`, using the ordered batch rows while excluding `"Approval"` rows; `writeApplicationRows_()` should use the already-verified batch rather than reselecting the latest preview. This prevents reuse after staging changes, preview-row edits, approval edits, or a completed/partially attempted apply.

Store an immutable copy of the rows selected by each preview, and have apply use that payload—not a fresh read or “latest” lookup from `Staging`. The example below assumes the preview payload contains `applicationRows`, each of which is the exact array to append to `Applications`, plus the staging hash captured during preview creation.

```javascript
const PREVIEW_PAYLOAD_PREFIX = "previewPayload:";
const PREVIEW_PAYLOAD_DIGEST_PREFIX = "previewPayloadDigest:";

/**
 * Call this when creating the preview, after snapshot and validation.
 *
 * payload.applicationRows must contain the exact values that Apply will write.
 */
function storePreviewPayload_(batchId, payload) {
  const json = JSON.stringify(payload);
  const props = PropertiesService.getDocumentProperties();

  props.setProperty(PREVIEW_PAYLOAD_PREFIX + batchId, json);
  props.setProperty(
    PREVIEW_PAYLOAD_DIGEST_PREFIX + batchId,
    sha256Hex_(json)
  );
}

function getVerifiedPreviewPayload_(batchId) {
  const props = PropertiesService.getDocumentProperties();
  const raw = props.getProperty(PREVIEW_PAYLOAD_PREFIX + batchId);
  const expectedDigest = props.getProperty(
    PREVIEW_PAYLOAD_DIGEST_PREFIX + batchId
  );

  if (!raw || !expectedDigest) {
    throw new Error("The immutable staged-row payload is missing.");
  }

  if (sha256Hex_(raw) !== expectedDigest) {
    throw new Error("The approved staged-row payload was altered.");
  }

  const payload = JSON.parse(raw);

  if (!payload.stagingHash || !Array.isArray(payload.applicationRows)) {
    throw new Error("The preview payload is incomplete.");
  }

  return payload;
}

/**
 * Writes only the rows captured by the approved preview.
 *
 * This function does not select rows from the current Staging contents.
 * It verifies the current staging hash before writing, logs the write, and
 * clears Staging only after the destination write and audit log succeed.
 */
function writeApplicationRows_(ss, batchId) {
  const payload = getVerifiedPreviewPayload_(batchId);
  const stage = ss.getSheetByName("Staging");
  const applications = ss.getSheetByName("Applications");
  const audit = ss.getSheetByName("Application audit");

  if (!stage || !applications || !audit) {
    throw new Error(
      "Staging, Applications, or Application audit sheet is missing."
    );
  }

  // Final guard against applying an approved payload to changed staging data.
  const currentSnapshot = getStagingSnapshot_(stage);
  if (currentSnapshot.hash !== payload.stagingHash) {
    throw new Error(
      "Staging changed after approval; no application rows were written."
    );
  }

  const rows = payload.applicationRows;
  const writtenAt = new Date();
  const firstDestinationRow = applications.getLastRow() + 1;

  // Nothing is cleared unless the normal successful path reaches the end.
  if (rows.length > 0) {
    const width = rows[0].length;

    if (rows.some(row => !Array.isArray(row) || row.length !== width)) {
      throw new Error("The approved application rows have inconsistent widths.");
    }

    applications
      .getRange(firstDestinationRow, 1, rows.length, width)
      .setValues(rows);
  }

  SpreadsheetApp.flush();

  // Record what was actually written, including the exact approved payload.
  const auditRows = rows.map((row, index) => [
    writtenAt,
    batchId,
    "APPLY",
    firstDestinationRow + index,
    payload.stagingHash,
    JSON.stringify(row)
  ]);

  if (auditRows.length > 0) {
    audit
      .getRange(audit.getLastRow() + 1, 1, auditRows.length, auditRows[0].length)
      .setValues(auditRows);
  } else {
    audit.appendRow([
      writtenAt,
      batchId,
      "APPLY",
      "",
      payload.stagingHash,
      "No application rows"
    ]);
  }

  SpreadsheetApp.flush();

  // Clear only after destination writing and audit logging succeeded.
  clearStagingAfterSuccessfulApply_(stage);
  SpreadsheetApp.flush();
}

function clearStagingAfterSuccessfulApply_(stage) {
  const firstDataRow = 2;
  const lastRow = stage.getLastRow();
  const lastColumn = stage.getLastColumn();

  if (lastRow >= firstDataRow && lastColumn > 0) {
    stage
      .getRange(
        firstDataRow,
        1,
        lastRow - firstDataRow + 1,
        lastColumn
      )
      .clearContent();
  }
}
```

When creating the preview, save `applicationRows` from the validated preview result and include its digest in the approval record; `applyApprovedBatch()` should compare that digest and `payload.stagingHash` before calling this function. Since Apps Script has no transaction rollback, leave the batch in `APPLYING` if any write, audit, or clear operation throws, so it cannot be silently retried.

Use an immutable operation list: updates carry the exact target row, application ID, expected old value, and replacement value for each writable column; inserts carry only writable-column values. Keep formula columns out of the payload and reject any operation that targets them.

```javascript
const APPLICATION_ID_COL = 1;                 // 1-based sheet column
const FORMULA_COLUMNS = new Set([5, 6, 9]);   // 1-based protected columns
const WRITABLE_COLUMNS = [1, 2, 3, 4, 7, 8]; // adjust to your sheet

/*
Preview payload example:
{
  stagingHash: "...",
  operations: [
    {
      type: "UPDATE",
      applicationId: "A-102",
      targetRow: 17,
      changes: [
        { col: 2, oldValue: "Pending", newValue: "Approved" },
        { col: 4, oldValue: "12", newValue: "15" }
      ]
    },
    {
      type: "INSERT",
      values: { "1": "A-103", "2": "Pending", "3": "New", "4": 8 }
    }
  ]
}
*/

function writeApplicationRows_(ss, batchId) {
  const payload = getVerifiedPreviewPayload_(batchId);
  const stage = ss.getSheetByName("Staging");
  const applications = ss.getSheetByName("Applications");
  const audit = ss.getSheetByName("Application audit");

  if (!stage || !applications || !audit) {
    throw new Error("Required sheet is missing.");
  }

  if (getStagingSnapshot_(stage).hash !== payload.stagingHash) {
    throw new Error("Staging changed after approval.");
  }

  if (!Array.isArray(payload.operations)) {
    throw new Error("Approved payload has no operation list.");
  }

  const auditRows = [];
  const timestamp = new Date();

  payload.operations.forEach(op => {
    if (op.type === "UPDATE") {
      applyExactUpdate_(applications, op);
      auditRows.push([
        timestamp, batchId, "UPDATE", op.targetRow,
        op.applicationId, JSON.stringify(op.changes)
      ]);
    } else if (op.type === "INSERT") {
      const row = appendWritableInsert_(applications, op);
      auditRows.push([
        timestamp, batchId, "INSERT", row,
        String(op.values[APPLICATION_ID_COL] || ""),
        JSON.stringify(op.values)
      ]);
    } else {
      throw new Error(`Unsupported operation type: ${op.type}`);
    }
  });

  SpreadsheetApp.flush();

  if (auditRows.length) {
    audit.getRange(
      audit.getLastRow() + 1, 1, auditRows.length, auditRows[0].length
    ).setValues(auditRows);
  }

  SpreadsheetApp.flush();

  // This is reached only after every destination and audit write succeeds.
  clearStagingAfterSuccessfulApply_(stage);
}

function applyExactUpdate_(sheet, op) {
  if (!Number.isInteger(op.targetRow) || op.targetRow < 2) {
    throw new Error("Invalid target row in approved update.");
  }

  const id = String(sheet.getRange(op.targetRow, APPLICATION_ID_COL)
    .getDisplayValue()).trim();

  if (id !== String(op.applicationId).trim()) {
    throw new Error(
      `Application ID mismatch at row ${op.targetRow}; update stopped.`
    );
  }

  if (!Array.isArray(op.changes) || !op.changes.length) {
    throw new Error(`Update for ${op.applicationId} has no changed fields.`);
  }

  op.changes.forEach(change => {
    const col = Number(change.col);

    if (!WRITABLE_COLUMNS.includes(col) || FORMULA_COLUMNS.has(col)) {
      throw new Error(`Column ${col} is protected or not writable.`);
    }

    const cell = sheet.getRange(op.targetRow, col);
    const actual = cell.getDisplayValue();

    if (String(actual) !== String(change.oldValue)) {
      throw new Error(
        `Row ${op.targetRow}, column ${col} changed since preview.`
      );
    }
  });

  // All preconditions are checked before any field in this row is changed.
  op.changes.forEach(change => {
    sheet.getRange(op.targetRow, Number(change.col))
      .setValue(change.newValue);
  });
}

function appendWritableInsert_(sheet, op) {
  const values = op.values || {};
  const applicationId = String(values[APPLICATION_ID_COL] || "").trim();

  if (!applicationId) {
    throw new Error("Inserted application is missing its ID.");
  }

  if (FORMULA_COLUMNS.has(APPLICATION_ID_COL) ||
      !WRITABLE_COLUMNS.includes(APPLICATION_ID_COL)) {
    throw new Error("The application ID column is not writable.");
  }

  const existingIds = sheet
    .getRange(2, APPLICATION_ID_COL,
      Math.max(sheet.getLastRow() - 1, 1), 1)
    .getDisplayValues()
    .flat()
    .map(v => String(v).trim());

  if (existingIds.includes(applicationId)) {
    throw new Error(`Application ID already exists: ${applicationId}`);
  }

  const targetRow = Math.max(sheet.getLastRow() + 1, 2);

  Object.keys(values).forEach(key => {
    const col = Number(key);

    if (!WRITABLE_COLUMNS.includes(col) || FORMULA_COLUMNS.has(col)) {
      throw new Error(`Insert attempts to write protected column ${col}.`);
    }

    sheet.getRange(targetRow, col).setValue(values[key]);
  });

  return targetRow;
}
```

At preview creation, build each `UPDATE` operation from the validated row’s stable ID and current target row, recording `oldValue` before storing the payload; if any destination write or audit write fails, leave the batch marked `APPLYING` so it cannot be retried blindly.

Use a read-only preflight for the entire payload, then checkpoint after each successfully applied operation; any exception marks the batch `FAILED`, leaves `Staging` untouched, and prevents it from being reported as applied. Apps Script has no transaction rollback, so a runtime failure can still leave earlier destination changes in place—the checkpoint makes that explicit for reconciliation rather than silently retrying.

```javascript
const APPLY_CHECKPOINT_PREFIX = "applyCheckpoint:";
const APPLY_STATUS_PREFIX = "previewApplyStatus:";

function writeApplicationRows_(ss, batchId) {
  const props = PropertiesService.getDocumentProperties();
  const payload = getVerifiedPreviewPayload_(batchId);
  const stage = ss.getSheetByName("Staging");
  const applications = ss.getSheetByName("Applications");
  const audit = ss.getSheetByName("Application audit");

  if (!stage || !applications || !audit) {
    throw new Error("Required sheet is missing.");
  }

  if (getStagingSnapshot_(stage).hash !== payload.stagingHash) {
    throw new Error("Staging changed after approval.");
  }

  const operations = payload.operations;
  if (!Array.isArray(operations)) {
    throw new Error("Approved payload has no operations.");
  }

  // No writes occur during this phase.
  preflightOperations_(applications, operations);

  const statusKey = APPLY_STATUS_PREFIX + batchId;
  const checkpointKey = APPLY_CHECKPOINT_PREFIX + batchId;
  const startedAt = new Date().toISOString();

  props.setProperty(statusKey, "APPLYING");
  props.setProperty(checkpointKey, JSON.stringify({
    batchId,
    status: "APPLYING",
    nextOperation: 0,
    completedOperations: 0,
    totalOperations: operations.length,
    stagingHash: payload.stagingHash,
    startedAt,
    updatedAt: startedAt
  }));

  try {
    for (let i = 0; i < operations.length; i++) {
      // Recheck the source before every operation.
      if (getStagingSnapshot_(stage).hash !== payload.stagingHash) {
        throw new Error("Staging changed during apply.");
      }

      const op = operations[i];
      let targetRow;

      if (op.type === "UPDATE") {
        applyExactUpdate_(applications, op);
        targetRow = op.targetRow;
      } else if (op.type === "INSERT") {
        targetRow = appendWritableInsert_(applications, op);
      } else {
        throw new Error(`Unsupported operation type: ${op.type}`);
      }

      SpreadsheetApp.flush();

      const auditRow = [[
        new Date(),
        batchId,
        op.type,
        targetRow,
        String(op.applicationId || op.values[APPLICATION_ID_COL] || ""),
        JSON.stringify(op.changes || op.values),
        payload.stagingHash
      ]];

      audit.getRange(
        audit.getLastRow() + 1, 1, 1, auditRow[0].length
      ).setValues(auditRow);
      SpreadsheetApp.flush();

      // Persist progress only after both the destination and audit writes succeed.
      props.setProperty(checkpointKey, JSON.stringify({
        batchId,
        status: "APPLYING",
        nextOperation: i + 1,
        completedOperations: i + 1,
        totalOperations: operations.length,
        stagingHash: payload.stagingHash,
        startedAt,
        updatedAt: new Date().toISOString()
      }));
    }

    // Clear only after every operation and audit entry succeeded.
    clearStagingAfterSuccessfulApply_(stage);
    SpreadsheetApp.flush();

    props.setProperty(statusKey, "APPLIED");
    props.setProperty(checkpointKey, JSON.stringify({
      batchId,
      status: "APPLIED",
      nextOperation: operations.length,
      completedOperations: operations.length,
      totalOperations: operations.length,
      stagingHash: payload.stagingHash,
      startedAt,
      completedAt: new Date().toISOString()
    }));
  } catch (err) {
    // Do not clear Staging and do not mark the batch APPLIED.
    props.setProperty(statusKey, "FAILED");
    props.setProperty(checkpointKey, JSON.stringify({
      batchId,
      status: "FAILED",
      error: err.message,
      stagingHash: payload.stagingHash,
      updatedAt: new Date().toISOString()
    }));
    throw new Error(
      `Apply stopped safely: ${err.message}. ` +
      "Staging was not cleared; reconcile the checkpoint before retrying."
    );
  }
}

function preflightOperations_(sheet, operations) {
  const seenTargetRows = new Set();
  const seenInsertIds = new Set();
  const lastRow = sheet.getLastRow();

  operations.forEach((op, index) => {
    if (op.type === "UPDATE") {
      if (!Number.isInteger(op.targetRow) || op.targetRow < 2 ||
          op.targetRow > lastRow) {
        throw new Error(`Operation ${index + 1} has an invalid target row.`);
      }

      if (seenTargetRows.has(op.targetRow)) {
        throw new Error(`Row ${op.targetRow} appears in multiple operations.`);
      }
      seenTargetRows.add(op.targetRow);

      const actualId = String(sheet.getRange(
        op.targetRow, APPLICATION_ID_COL
      ).getDisplayValue()).trim();

      if (actualId !== String(op.applicationId).trim()) {
        throw new Error(`Operation ${index + 1} application ID mismatch.`);
      }

      if (!Array.isArray(op.changes) || op.changes.length === 0) {
        throw new Error(`Operation ${index + 1} has no changes.`);
      }

      op.changes.forEach(change => {
        const col = Number(change.col);
        if (!WRITABLE_COLUMNS.includes(col) || FORMULA_COLUMNS.has(col)) {
          throw new Error(
            `Operation ${index + 1} targets protected column ${col}.`
          );
        }

        const actual = sheet.getRange(op.targetRow, col).getDisplayValue();
        if (String(actual) !== String(change.oldValue)) {
          throw new Error(
            `Operation ${index + 1} old value mismatch at row ` +
            `${op.targetRow}, column ${col}.`
          );
        }
      });
    } else if (op.type === "INSERT") {
      const id = String(op.values?.[APPLICATION_ID_COL] || "").trim();
      if (!id) throw new Error(`Operation ${index + 1} has no application ID.`);
      if (seenInsertIds.has(id)) {
        throw new Error(`Duplicate inserted application ID: ${id}`);
      }
      seenInsertIds.add(id);

      Object.keys(op.values || {}).forEach(key => {
        const col = Number(key);
        if (!WRITABLE_COLUMNS.includes(col) || FORMULA_COLUMNS.has(col)) {
          throw new Error(
            `Operation ${index + 1} targets protected column ${col}.`
          );
        }
      });
    } else {
      throw new Error(`Operation ${index + 1} has an invalid type.`);
    }
  });

  const existingIds = lastRow < 2 ? [] : sheet
    .getRange(2, APPLICATION_ID_COL, lastRow - 1, 1)
    .getDisplayValues()
    .flat()
    .map(String)
    .map(s => s.trim());

  operations
    .filter(op => op.type === "INSERT")
    .forEach(op => {
      const id = String(op.values[APPLICATION_ID_COL]).trim();
      if (existingIds.includes(id)) {
        throw new Error(`Inserted application ID already exists: ${id}`);
      }
    });
}
```

Have `applyApprovedBatch()` reject any status other than an initial approved state, and require manual reconciliation when the checkpoint is `FAILED`; never automatically restart at `nextOperation` unless you also make each operation and audit entry idempotent.

Add a reconciliation command that requires the operator to identify completed operation numbers from the checkpoint and audit log; it must never resume the old payload automatically.

```javascript
function reconcileFailedBatch() {
  const lock = LockService.getDocumentLock();
  lock.waitLock(30000);

  try {
    const ss = SpreadsheetApp.getActive();
    const ui = SpreadsheetApp.getUi();
    const props = PropertiesService.getDocumentProperties();
    const actor = getAuthorizedUser_();
    const audit = ss.getSheetByName("Application audit");

    const r = ui.prompt(
      "Reconcile failed batch",
      "Enter the exact batch ID:",
      ui.ButtonSet.OK_CANCEL
    );
    if (r.getSelectedButton() !== ui.Button.OK) return;

    const batchId = r.getResponseText().trim();
    const statusKey = APPLY_STATUS_PREFIX + batchId;
    if (props.getProperty(statusKey) !== "FAILED") {
      throw new Error("Only FAILED batches can be reconciled.");
    }

    const checkpoint = JSON.parse(
      props.getProperty(APPLY_CHECKPOINT_PREFIX + batchId) || "{}"
    );
    const payload = getVerifiedPreviewPayload_(batchId);
    const total = payload.operations.length;

    const completedResponse = ui.prompt(
      "Completed operations",
      `Enter completed operation numbers, comma-separated, from 1 to ${total}. ` +
      "Verify these against Applications and Application audit:",
      ui.ButtonSet.OK_CANCEL
    );
    if (completedResponse.getSelectedButton() !== ui.Button.OK) return;

    const completed = completedResponse.getResponseText()
      .split(",")
      .map(s => s.trim())
      .filter(Boolean)
      .map(n => Number(n));

    if (completed.some(n =>
      !Number.isInteger(n) || n < 1 || n > total
    )) {
      throw new Error("Completed operation numbers are invalid.");
    }

    const completedSet = new Set(completed);
    if (completedSet.size !== completed.length) {
      throw new Error("An operation number was listed more than once.");
    }

    const decisionResponse = ui.prompt(
      "Reconciliation decision",
      'Enter ABANDON or REBUILD_RETRY:',
      ui.ButtonSet.OK_CANCEL
    );
    if (decisionResponse.getSelectedButton() !== ui.Button.OK) return;

    const decision = decisionResponse.getResponseText().trim().toUpperCase();
    if (!["ABANDON", "REBUILD_RETRY"].includes(decision)) {
      throw new Error("Decision must be ABANDON or REBUILD_RETRY.");
    }

    const notesResponse = ui.prompt(
      "Reconciliation notes",
      "Document what was verified and what should happen next:",
      ui.ButtonSet.OK_CANCEL
    );
    if (notesResponse.getSelectedButton() !== ui.Button.OK) return;

    const remaining = [];
    for (let i = 1; i <= total; i++) {
      if (!completedSet.has(i)) remaining.push(i);
    }

    // Record the decision before changing the batch status.
    audit.appendRow([
      new Date(),
      batchId,
      "RECONCILE",
      actor.email,
      decision,
      `Completed operations: ${completed.sort((a, b) => a - b).join(", ") || "none"}`,
      `Remaining operations: ${remaining.join(", ") || "none"}`,
      notesResponse.getResponseText().trim(),
      JSON.stringify(checkpoint)
    ]);
    SpreadsheetApp.flush();

    // The old approval is no longer usable, regardless of the decision.
    props.deleteProperty(APPROVAL_PREFIX + batchId);
    props.setProperty(
      statusKey,
      decision === "ABANDON" ? "ABANDONED" : "REBUILD_REQUIRED"
    );
    props.setProperty(
      APPLY_CHECKPOINT_PREFIX + batchId,
      JSON.stringify({
        ...checkpoint,
        status: decision === "ABANDON" ? "ABANDONED" : "REBUILD_REQUIRED",
        reconciledBy: actor.email,
        reconciledAt: new Date().toISOString(),
        completedOperations: completed,
        remainingOperations: remaining,
        decision,
        notes: notesResponse.getResponseText().trim()
      })
    );

    ui.alert(
      decision === "ABANDON"
        ? "Batch abandoned; Staging was not cleared."
        : "Batch marked REBUILD_REQUIRED. Create a new preview and obtain fresh approval."
    );
  } finally {
    lock.releaseLock();
  }
}
```

Also make `applyApprovedBatch()` require an approval property created after reconciliation and reject `FAILED`, `REBUILD_REQUIRED`, `RECONCILED`, and `ABANDONED`; for `REBUILD_RETRY`, create a new preview batch from the still-unapplied rows after verifying the current destination state, rather than reusing the old payload or restarting at `nextOperation`.

Create the replacement preview only after verifying the recorded completed operations against both the audit log and current `Applications`; never trust a manually entered list by itself. Also normalize the authorization result so reconciliation always logs the authenticated email.

```javascript
function authorizedIdentity_(value) {
  const email = String(value?.email || value || "").trim().toLowerCase();
  if (!email || !email.includes("@")) {
    throw new Error("Could not determine the authenticated user email.");
  }
  return {
    email,
    name: String(value?.name || email).trim()
  };
}

function reconcileFailedBatch() {
  const lock = LockService.getDocumentLock();
  lock.waitLock(30000);

  try {
    const ss = SpreadsheetApp.getActive();
    const ui = SpreadsheetApp.getUi();
    const props = PropertiesService.getDocumentProperties();
    const actor = authorizedIdentity_(getAuthorizedUser_());
    const audit = ss.getSheetByName("Application audit");

    const id = ui.prompt(
      "Reconcile failed batch",
      "Enter the exact failed batch ID:",
      ui.ButtonSet.OK_CANCEL
    );
    if (id.getSelectedButton() !== ui.Button.OK) return;

    const batchId = id.getResponseText().trim();
    if (props.getProperty(APPLY_STATUS_PREFIX + batchId) !== "FAILED") {
      throw new Error("Only FAILED batches can be reconciled.");
    }

    const payload = getVerifiedPreviewPayload_(batchId);
    const checkpoint = JSON.parse(
      props.getProperty(APPLY_CHECKPOINT_PREFIX + batchId) || "{}"
    );
    const completed = promptOperationNumbers_(ui, payload.operations.length);

    // Confirm that every claimed completion has a matching audit record and
    // that the destination still contains the recorded result.
    verifyCompletedOperations_(ss, batchId, payload.operations, completed);

    const decision = ui.prompt(
      "Reconciliation decision",
      "Enter ABANDON or REBUILD_RETRY:",
      ui.ButtonSet.OK_CANCEL
    );
    if (decision.getSelectedButton() !== ui.Button.OK) return;

    const choice = decision.getResponseText().trim().toUpperCase();
    if (!["ABANDON", "REBUILD_RETRY"].includes(choice)) {
      throw new Error("Decision must be ABANDON or REBUILD_RETRY.");
    }

    const notes = ui.prompt(
      "Reconciliation notes",
      "Document the verification and decision:",
      ui.ButtonSet.OK_CANCEL
    );
    if (notes.getSelectedButton() !== ui.Button.OK) return;

    const remaining = payload.operations
      .map((op, i) => ({ op, number: i + 1 }))
      .filter(x => !completed.includes(x.number));

    audit.appendRow([
      new Date(), batchId, "RECONCILE", "", actor.email, choice,
      `Completed: ${completed.join(", ") || "none"}`,
      `Remaining: ${remaining.map(x => x.number).join(", ") || "none"}`,
      notes.getResponseText().trim()
    ]);
    SpreadsheetApp.flush();

    props.deleteProperty(APPROVAL_PREFIX + batchId);

    if (choice === "ABANDON") {
      props.setProperty(APPLY_STATUS_PREFIX + batchId, "ABANDONED");
      ui.alert("Batch abandoned. Staging was not cleared.");
      return;
    }

    const newBatchId = createRetryPreview_(
      ss, batchId, payload, remaining.map(x => x.op), actor.email
    );

    props.setProperty(APPLY_STATUS_PREFIX + batchId, "REBUILD_REQUIRED");
    props.setProperty(APPLY_CHECKPOINT_PREFIX + batchId, JSON.stringify({
      ...checkpoint,
      status: "REBUILD_REQUIRED",
      reconciledBy: actor.email,
      reconciledAt: new Date().toISOString(),
      completedOperations: completed,
      remainingOperations: remaining.map(x => x.number),
      replacementBatchId: newBatchId,
      decision: choice,
      notes: notes.getResponseText().trim()
    }));

    ui.alert(
      `Created fresh preview ${newBatchId}. ` +
      "A different authorized reviewer must approve it before apply."
    );
  } finally {
    lock.releaseLock();
  }
}

function createRetryPreview_(ss, oldBatchId, oldPayload, operations, actorEmail) {
  const stage = ss.getSheetByName("Staging");
  const snapshot = getStagingSnapshot_(stage);

  // Remaining operations must still match the current destination before
  // they are allowed into the replacement preview.
  preflightOperations_(ss.getSheetByName("Applications"), operations);

  const newBatchId = Utilities.getUuid();
  const payload = {
    version: 2,
    sourceFailedBatchId: oldBatchId,
    createdBy: actorEmail,
    createdAt: new Date().toISOString(),
    stagingHash: snapshot.hash,
    operations
  };

  storePreviewPayload_(newBatchId, payload);

  // Use your normal preview-history writer here; its rows must describe only
  // these remaining operations and must receive their own trusted digest.
  appendRetryPreviewHistory_(ss, newBatchId, payload);
  return newBatchId;
}
```

For inserts, `verifyCompletedOperations_()` must match the audit’s recorded target row and application ID; for updates, it should recheck every `newValue` in the destination, while `preflightOperations_()` rejects any remaining operation whose `oldValue` no longer matches. In `approvePreviewBatch()`, normalize both `getAuthorizedUser_()` and the selected reviewer with `authorizedIdentity_()`, then require `reviewer.email !== actor.email` and store both normalized addresses in the approval record.

```javascript
const AUDIT_COL = Object.freeze({
  timestamp: 1,
  batchId: 2,
  type: 3,
  targetRow: 4,
  applicationId: 5,
  details: 6,
  stagingHash: 7
});

function verifyCompletedOperations_(ss, batchId, operations, completedNumbers) {
  const applications = ss.getSheetByName("Applications");
  const audit = ss.getSheetByName("Application audit");

  if (!applications || !audit) {
    throw new Error("Applications or Application audit sheet is missing.");
  }

  const completed = [...new Set(completedNumbers)].sort((a, b) => a - b);
  const auditRows = audit.getLastRow() < 2
    ? []
    : audit.getRange(2, 1, audit.getLastRow() - 1, audit.getLastColumn())
        .getValues();

  completed.forEach(number => {
    const op = operations[number - 1];
    if (!op) {
      throw new Error(`Completed operation ${number} does not exist.`);
    }

    const matchingAudit = auditRows.find(row =>
      String(row[AUDIT_COL.batchId - 1]).trim() === batchId &&
      String(row[AUDIT_COL.type - 1]).trim() === op.type &&
      Number(row[AUDIT_COL.targetRow - 1]) ===
        (op.type === "UPDATE" ? op.targetRow : Number(row[AUDIT_COL.targetRow - 1])) &&
      String(row[AUDIT_COL.applicationId - 1]).trim() ===
        operationApplicationId_(op)
    );

    if (!matchingAudit) {
      throw new Error(
        `No matching audit entry exists for completed operation ${number}.`
      );
    }

    const targetRow = Number(matchingAudit[AUDIT_COL.targetRow - 1]);
    if (!Number.isInteger(targetRow) || targetRow < 2) {
      throw new Error(`Audit entry for operation ${number} has no valid row.`);
    }

    const actualId = String(
      applications.getRange(targetRow, APPLICATION_ID_COL).getDisplayValue()
    ).trim();

    if (actualId !== operationApplicationId_(op)) {
      throw new Error(
        `Application ID mismatch while verifying operation ${number}.`
      );
    }

    if (op.type === "UPDATE") {
      op.changes.forEach(change => {
        const actual = applications
          .getRange(targetRow, Number(change.col))
          .getDisplayValue();

        if (String(actual) !== String(change.newValue ?? "")) {
          throw new Error(
            `Update ${number} is not fully present at row ${targetRow}, ` +
            `column ${change.col}.`
          );
        }
      });
    } else if (op.type === "INSERT") {
      Object.keys(op.values || {}).forEach(key => {
        const col = Number(key);
        const actual = applications
          .getRange(targetRow, col)
          .getDisplayValue();

        if (String(actual) !== String(op.values[key] ?? "")) {
          throw new Error(
            `Insert ${number} does not match its recorded result at ` +
            `row ${targetRow}, column ${col}.`
          );
        }
      });
    }
  });

  return completed;
}

function operationApplicationId_(op) {
  return String(
    op.applicationId ??
    op.values?.[APPLICATION_ID_COL] ??
    ""
  ).trim();
}

function appendRetryPreviewHistory_(ss, batchId, payload) {
  const history = ss.getSheetByName("Preview history");
  if (!history) {
    throw new Error("Preview history sheet is missing.");
  }

  const json = JSON.stringify(payload);
  const digest = sha256Hex_(json);

  // StorePreviewPayload_ writes the same JSON and digest to document
  // properties, so the history row is independently useful for review.
  storePreviewPayload_(batchId, payload);

  const operationSummary = payload.operations.map((op, index) => ({
    number: index + 1,
    type: op.type,
    applicationId: operationApplicationId_(op),
    targetRow: op.type === "UPDATE" ? op.targetRow : null,
    changedColumns: op.type === "UPDATE"
      ? op.changes.map(change => Number(change.col))
      : Object.keys(op.values || {}).map(Number)
  }));

  history.appendRow([
    new Date(),
    batchId,
    "PREVIEW_CREATED",
    payload.createdBy || "",
    payload.sourceFailedBatchId || "",
    payload.stagingHash,
    digest,
    payload.operations.length,
    JSON.stringify(operationSummary)
  ]);

  SpreadsheetApp.flush();
  return digest;
}
```

Use the same `appendRetryPreviewHistory_()` writer for ordinary previews, and require `sha256Hex_(JSON.stringify(payload))` to match both the document-property digest and the history digest during approval. The audit lookup assumes columns A:G are timestamp, batch ID, operation type, target row, application ID, details, and staging hash; adjust `AUDIT_COL` if your sheet differs.

