function sendMonthlyReminder() {
  const ss = SpreadsheetApp.getActiveSpreadsheet();
  const sheet = ss.getSheetByName(CONFIG.currentFilesSheetName);
  if (!sheet) throw new Error('Current Files sheet was not found.');

  const data = sheet.getDataRange().getValues();
  const headers = data[0];
  const fileCol = headers.indexOf('File Name');
  const reviewedCol = headers.indexOf('Last Reviewed');

  if ([fileCol, reviewedCol].includes(-1)) {
    throw new Error('Current Files must have File Name and Last Reviewed headers.');
  }

  const cutoff = new Date();
  cutoff.setDate(cutoff.getDate() - CONFIG.overdueDays);

  const overdue = [];
  for (let r = 1; r < data.length; r++) {
    const fileName = String(data[r][fileCol]).trim();
    const lastReviewed = data[r][reviewedCol];

    if (!fileName || !lastReviewed ||
        !(lastReviewed instanceof Date) ||
        lastReviewed < cutoff) {
      overdue.push(fileName || '(unnamed file)');
    }
  }

  const subject = overdue.length
    ? 'Current files needing review'
    : 'Monthly current-file review: all up to date';

  const body = overdue.length
    ? 'These files have not been reviewed within the last ' +
      CONFIG.overdueDays + ' days:\n\n- ' + overdue.join('\n- ')
    : 'All files in Current Files were reviewed within the last ' +
      CONFIG.overdueDays + ' days.';

  MailApp.sendEmail(CONFIG.notifyEmail, subject, body);
}

function installTriggers() {
  const ss = SpreadsheetApp.getActiveSpreadsheet();

  ScriptApp.getProjectTriggers().forEach(trigger => {
    if (['onFormSubmit', 'sendMonthlyReminder'].includes(trigger.getHandlerFunction())) {
      ScriptApp.deleteTrigger(trigger);
    }
  });

  ScriptApp.newTrigger('onFormSubmit')
    .forSpreadsheet(ss)
    .onFormSubmit()
    .create();

  ScriptApp.newTrigger('sendMonthlyReminder')
    .timeBased()
    .onMonthDay(1)
    .atHour(8)
    .create();
}
