  const nameColumn = testFindColumn_(
    headers, ['file name', 'filename', 'name']
  );
  const idColumn = testFindColumn_(
    headers, ['file id', 'id']
  );
  const urlColumn = testFindColumn_(
    headers, ['url', 'file url', 'link']
  );

  if (nameColumn < 0 && idColumn < 0 && urlColumn < 0) {
    throw new Error(
      'The sheet needs a File Name, File ID, or URL column.'
    );
  }

  const folderFiles = [];
  const files = folder.getFiles();

  while (files.hasNext()) {
    const file = files.next();
    folderFiles.push({
      id: file.getId(),
      name: file.getName(),
      nameKey: testNormalizeName_(file.getName()),
      isCurrent: /\bCURRENT\b/i.test(file.getName())
    });
  }

  const sheetEntries = [];

  for (let row = 1; row < values.length; row++) {
    const record = values[row];
    const status = statusColumn >= 0
      ? String(record[statusColumn]).trim().toUpperCase()
      : 'CURRENT';

    const name = nameColumn >= 0
      ? String(record[nameColumn]).trim()
      : '';
    const id = idColumn >= 0
      ? String(record[idColumn]).trim()
      : '';
    const url = urlColumn >= 0
      ? String(record[urlColumn]).trim()
      : '';

    sheetEntries.push({
      row: row + 1,
      status: status,
      name: name || '(unnamed)',
      nameKey: testNormalizeName_(name),
      id: id || testExtractDriveId_(url),
      isCurrent: status === 'CURRENT'
    });
  }

  const currentFolderFiles = folderFiles.filter(file => file.isCurrent);
  const currentSheetEntries = sheetEntries.filter(entry => entry.isCurrent);

  // A file matches by ID when an ID is available; otherwise by normalized name.
  const matchesEntry = (file, entry) => {
    if (file.id && entry.id) {
      return file.id === entry.id;
    }
    return file.nameKey && file.nameKey === entry.nameKey;
  };

  const missingFromSheet = currentFolderFiles.filter(file =>
    !currentSheetEntries.some(entry => matchesEntry(file, entry))
  );

  const extraCurrentSheetEntries = currentSheetEntries.filter(entry =>
    !currentFolderFiles.some(file => matchesEntry(file, entry))
  );

  // Report every direct child file that has no corresponding sheet entry.
  const unlistedDirectFiles = folderFiles.filter(file =>
    !sheetEntries.some(entry => matchesEntry(file, entry))
  );

  const duplicateCurrentFolderNames = testDuplicateNames_(
    currentFolderFiles
  );
  const duplicateCurrentSheetNames = testDuplicateNames_(
    currentSheetEntries
  );

  const hasProblems =
    missingFromSheet.length > 0 ||
    extraCurrentSheetEntries.length > 0 ||
    unlistedDirectFiles.length > 0 ||
    duplicateCurrentFolderNames.length > 0 ||
    duplicateCurrentSheetNames.length > 0;

  console.log(JSON.stringify({
    test: 'shared-folder CURRENT file integrity',
    reminderFunctionCalled: false,
    emailSent: false,
    folderModified: false,
    sheetModified: false,

    missing: {
      description: 'CURRENT files in the folder missing from the sheet',
      files: missingFromSheet.map(file => ({
        name: file.name,
        fileId: file.id
      }))
    },

    extra: {
      description: 'CURRENT sheet entries missing from the folder',
      sheetEntries: extraCurrentSheetEntries.map(entry => ({
        row: entry.row,
        name: entry.name,
        fileId: entry.id || 'None'
      })),
      unlistedDirectFolderFiles: unlistedDirectFiles.map(file => ({
        name: file.name,
        fileId: file.id,
        markedCurrent: file.isCurrent
      }))
    },

    duplicates: {
      currentFolderFilenames: duplicateCurrentFolderNames,
      currentSheetFilenames: duplicateCurrentSheetNames
    },

    status: hasProblems
      ? 'MISMATCH: missing, extra, or duplicate entries found.'
      : 'MATCH: no missing, extra, or duplicate entries found.'
  }, null, 2));
}

function testDuplicateNames_(items) {
  const groups = {};

  items.forEach(item => {
    const key = item.nameKey || '(unnamed)';
    if (!groups[key]) groups[key] = [];
    groups[key].push(item);
  });

  return Object.keys(groups)
    .filter(key => groups[key].length > 1)
    .map(key => ({
      filename: key,
      occurrences: groups[key].map(item => ({
        row: item.row || null,
        fileId: item.id || null,
        name: item.name
      }))
    }));
}

function testNormalizeHeader_(value) {
  return String(value).trim().toLowerCase().replace(/\s+/g, ' ');
}

function testNormalizeName_(value) {
  return String(value).trim().toLowerCase();
}

function testFindColumn_(headers, names) {
  return headers.findIndex(header => names.includes(header));
}

function testExtractDriveId_(value) {
  const match = String(value).match(/[A-Za-z0-9_-]{20,}/);
  return match ? match[0] : '';
}
