function auditCollectFiles_(folder, depth, output) {
  const files = folder.getFiles();

  while (files.hasNext()) {
    const file = files.next();
    output.push({
      name: file.getName(),
      nameKey: auditNormalizeName_(file.getName()),
      fileId: file.getId(),
      path: depth === 0
        ? '(shared folder root)'
        : `subfolder depth ${depth}`,
      depth: depth
    });
  }

  const subfolders = folder.getFolders();

  while (subfolders.hasNext()) {
    auditCollectFiles_(subfolders.next(), depth + 1, output);
  }
}


