function updateAuditStatusFromChecklist_(ss, auditId) {
  const checklist = ss.getSheetByName('Caregiver Checklist');
  const log = ss.getSheetByName('Audit Log');

  const rows = checklist.getDataRange().getValues();
  const headers = rows[0].map(String);
  const col = name => headers.indexOf(name);

  const auditRows = rows.slice(1).filter(row =>
    String(row[col('Audit ID')]) === auditId
  );

  if (!auditRows.length) return;

  const complete = auditRows.every(row =>
    String(row[col('Opened Successfully')]).toLowerCase() === 'yes' &&
    String(row[col('Editing Blocked')]).toLowerCase() === 'yes' &&
    String(row[col('Checked Date')]).trim() !== ''
  );

  if (!complete) return;

  const logValues = log.getDataRange().getValues();
  const logHeaders = logValues[0].map(String);
  const auditIdCol = logHeaders.indexOf('Audit ID');
  const statusCol = logHeaders.indexOf('Status');

  for (let i = 1; i < logValues.length; i++) {
    if (String(logValues[i][auditIdCol]) !== auditId) continue;

    // Never convert an audit with confirmed automated findings to PASS.
    const currentStatus = String(logValues[i][statusCol]);
    if (currentStatus === 'REVIEW') return;

    log.getRange(i + 1, statusCol + 1).setValue('PASS');
    return;
  }
}
