Use a clear marker that does not depend on the filename—for example, set the Drive file description to exactly `CURRENT`. This recursively scans the selected shared folder and returns only matching files:

```javascript
function getCurrentFilesFromSharedFolder_() {
  const folderId = PropertiesService.getScriptProperties()
    .getProperty('SHARED_FOLDER_ID');
  if (!folderId) throw new Error('SHARED_FOLDER_ID is not configured.');

  const root = DriveApp.getFolderById(folderId);
  const results = [];
  const seen = new Set();

  function scanFolder_(folder) {
    const files = folder.getFiles();
    while (files.hasNext()) {
      const file = files.next();
      const id = file.getId();

      // The file must be explicitly marked CURRENT in its description.
      if (String(file.getDescription()).trim().toUpperCase() !== 'CURRENT') continue;
      if (seen.has(id)) continue;

      seen.add(id);
      results.push({
        name: file.getName(),
        fileId: id
      });
    }

    const subfolders = folder.getFolders();
    while (subfolders.hasNext()) scanFolder_(subfolders.next());
  }

  scanFolder_(root);
  return results;
}
```

