```javascript
function validateRerunPreview_(ss, auditId, currentFiles) {
  const errors = [];

  const currentByName = new Map();
  currentFiles.forEach(file => {
    const name = String(file.name || '').trim();
    if (!name) {
      errors.push(`Current file ${file.fileId || '(unknown ID)'} has no filename.`);
      return;
    }
    if (!currentByName.has(name)) currentByName.set(name, []);
    currentByName.get(name).push(file.fileId);
  });

  currentByName.forEach((ids, name) => {
    if (ids.length > 1) {
      errors.push(`Duplicate CURRENT filename: "${name}" (${ids.length} files).`);
    }
  });

  const sheet = ss.getSheetByName('Caregiver Checklist');
  if (!sheet) return errors.concat('Caregiver Checklist sheet was not found.');

  const values = sheet.getDataRange().getValues();
  const headers = values[0].map(String);
  const auditCol = headers.indexOf('Audit ID');
  const fileCol = headers.indexOf('File');

  if (auditCol < 0 || fileCol < 0) {
    return errors.concat('Checklist must contain Audit ID and File columns.');
  }

  const priorByName = new Map();
  values.slice(1).forEach(row => {
    if (String(row[auditCol]) !== String(auditId)) return;
    const name = String(row[fileCol] || '').trim();
    if (!name) {
      errors.push('An existing checklist row has no filename.');
      return;
    }
    if (!priorByName.has(name)) priorByName.set(name, []);
    priorByName.get(name).push(name);
  });

  priorByName.forEach((rows, name) => {
    if (rows.length > 1) {
      errors.push(`Duplicate existing checklist filename: "${name}".`);
    }
  });

  return errors;
}
```

