```javascript
function validateRerunPreview_(ss, auditId, currentFiles) {
  const errors = [];
  const groupBy_ = (items, keyFn) => {
    const groups = new Map();
    items.forEach(item => {
      const key = String(keyFn(item) || '').trim();
      if (!groups.has(key)) groups.set(key, []);
      groups.get(key).push(item);
    });
    return groups;
  };
  const show_ = value => JSON.stringify(value, (_, v) =>
    v instanceof Date ? v.toISOString() : v
  );

  const currentById = groupBy_(currentFiles, f => f.fileId);
  currentById.forEach((files, id) => {
    if (!id) errors.push(`CURRENT file has no Drive ID:\n${show_(files)}`);
    else if (files.length > 1) {
      errors.push(`Duplicate CURRENT Drive ID "${id}":\n${show_(files)}`);
    }
  });

  const currentByName = groupBy_(currentFiles, f => f.name);
  currentByName.forEach((files, name) => {
    if (!name) errors.push(`CURRENT file has no filename:\n${show_(files)}`);
    else if (files.length > 1) {
      errors.push(`Duplicate CURRENT filename "${name}":\n${show_(files)}`);
    }
  });

  const sheet = ss.getSheetByName('Caregiver Checklist');
  if (!sheet) return errors.concat('Caregiver Checklist sheet was not found.');

  const values = sheet.getDataRange().getValues();
  if (!values.length) return errors.concat('Caregiver Checklist has no header row.');

  const headers = values[0].map(String);
  const auditCol = headers.indexOf('Audit ID');
  const fileCol = headers.indexOf('File');
  const idCol = headers.indexOf('File ID');

  if (auditCol < 0 || fileCol < 0 || idCol < 0) {
    return errors.concat('Checklist must contain Audit ID, File, and File ID columns.');
  }

  const prior = values.slice(1)
    .map((row, i) => ({
      sheetRow: i + 2,
      row: Object.fromEntries(headers.map((h, c) => [h, row[c]])),
      auditId: String(row[auditCol]),
      file: String(row[fileCol] || '').trim(),
      fileId: String(row[idCol] || '').trim()
    }))
    .filter(x => x.auditId === String(auditId));

  const priorById = groupBy_(prior, x => x.fileId);
  priorById.forEach((rows, id) => {
    if (!id) errors.push(`Checklist row has no File ID:\n${show_(rows)}`);
    else if (rows.length > 1) {
      errors.push(`Duplicate checklist File ID "${id}":\n${show_(rows)}`);
    }
  });

  const priorByName = groupBy_(prior, x => x.file);
  priorByName.forEach((rows, name) => {
    if (!name) errors.push(`Checklist row has no filename:\n${show_(rows)}`);
    else if (rows.length > 1) {
      errors.push(`Duplicate checklist filename "${name}":\n${show_(rows)}`);
    }
  });

  return errors;
}
```

