if (alreadyBackedUp) {
  console.log('SKIP copy: successful backup found within 7 days.');
} else if (DRY_RUN) {
  console.log(`WOULD COPY: ${prefix}${stamp}`);
} else {
  try {
    const copy = DriveApp.getFileById(ss.getId())
      .makeCopy(`${prefix}${stamp}`, folder);
    log.appendRow([now, 'Successful', copy.getName(), copy.getUrl()]);
  } catch (err) {
    errors.push(`Copy failed: ${err.message}`);
  }
}

// In the cleanup loop:
if (file.getName().startsWith(prefix) && file.getDateCreated() < cutoff) {
  if (DRY_RUN) {
    console.log(`WOULD TRASH: ${file.getName()} (${file.getUrl()})`);
  } else {
    try {
      file.setTrashed(true);
    } catch (err) {
      errors.push(`Trash failed for ${file.getName()}: ${err.message}`);
    }
  }
}

const result = errors.length ? `FAILED: ${errors.join(' | ')}` : 'Completed successfully';
TEST_CELL.setValue(`${DRY_RUN ? 'Dry run' : 'Backup run'}: ${result}`);
if (errors.length && !DRY_RUN) {
  MailApp.sendEmail(ALERT_EMAIL, 'Backup script alert', errors.join('\n'));
}
```

