```javascript
function notifyManualReviewSafely_(log, action, attempts, latestError) {
  const h = log.getRange(1, 1, 1, log.getLastColumn()).getValues()[0];
  const col = name => h.indexOf(name);
  const prefix = action.kind === 'primary'
    ? 'Primary manual review'
    : 'Backup manual review';

  const claimCol = col(`${prefix} notification claimed at`);
  const sentCol = col(`${prefix} notified at`);
  const errorCol = col(`${prefix} notification error`);
  const row = action.sheetRow;
  const now = new Date();

  const lock = LockService.getScriptLock();
  lock.waitLock(10000);
  let claimed = false;

  try {
    const sent = log.getRange(row, sentCol + 1).getValue();
    const claim = log.getRange(row, claimCol + 1).getValue();

    if (!sent && !isActiveClaim_(claim, now)) {
      log.getRange(row, claimCol + 1).setValue(now);
      claimed = true;
    }
  } finally {
    lock.releaseLock();
  }

  if (!claimed) return; // Already sent or being handled by another run.

  const alertId = log.getRange(row, col('Alert ID') + 1).getValue();
  let sendError = '';

  try {
    MailApp.sendEmail(
      PRIMARY_COORDINATOR,
      `Manual review required: alert ${alertId}`,
      `Alert ID: ${alertId}\n` +
      `Delivery path: ${action.kind}\n` +
      `Failed attempts: ${attempts}\n` +
      `Latest error: ${latestError}\n\n` +
      `Inspect the audit entry, retry once manually if appropriate, ` +
      `and record the final outcome.`
    );
  } catch (err) {
    sendError = err && err.message ? err.message : String(err);
  }

  const finishLock = LockService.getScriptLock();
  finishLock.waitLock(10000);
  try {
    log.getRange(row, claimCol + 1).clearContent();

    if (sendError) {
      log.getRange(row, errorCol + 1)
        .setValue(`${new Date().toISOString()}: ${sendError}`);
    } else {
      log.getRange(row, sentCol + 1).setValue(new Date());
      log.getRange(row, errorCol + 1).clearContent();
    }
  } finally {
    finishLock.releaseLock();
  }
}
```

