    throw new Error(
      "Duplicate application ID(s) found in Staging: " +
      [...duplicateStaged].join(", ") +
      ". No changes were made."
    );
  }

  const auditRows = [];
  const watched = {
    17: "Filing deadline",          // Q
    21: "Interview deadline",       // U
    22: "Visa-issuance deadline",   // V
    25: "Applicability confirmed"   // Y
  };

  let changedRows = 0;
  let appendedRows = 0;

  // All validation is complete before this point.
  stagedRows.forEach(stagedRow => {
    const id = String(stagedRow[0]).trim();
    let targetRow = idToRow.get(id);
    const isNewRow = !targetRow;

    if (!targetRow) {
      targetRow = ++lastIdRow;
      idToRow.set(id, targetRow);
      appendedRows++;
    }

    const oldInput = app
      .getRange(targetRow, 1, 1, 22)
      .getDisplayValues()[0];

    const oldConfirmation = app
      .getRange(targetRow, 25)
      .getDisplayValue();

    // Write Staging A:V to Applications A:V.
    app
      .getRange(targetRow, 1, 1, 22)
      .setValues([stagedRow.slice(0, 22)]);

    // Write Staging W to Applications Y.
