      const formulaSourceRow = targetRow > 2 ? targetRow - 1 : 2;

      app.getRange(formulaSourceRow, 23, 1, 2)
        .copyTo(
          app.getRange(targetRow, 23, 1, 2),
          SpreadsheetApp.CopyPasteType.PASTE_FORMULA,
          false
        );

      app.getRange(formulaSourceRow, 26)
        .copyTo(
          app.getRange(targetRow, 26),
          SpreadsheetApp.CopyPasteType.PASTE_FORMULA,
          false
        );
    }

    const newInput = app
      .getRange(targetRow, 1, 1, 22)
      .getDisplayValues()[0];

    const newConfirmation = app
      .getRange(targetRow, 25)
      .getDisplayValue();

    let rowChanged = false;

    [17, 21, 22].forEach(column => {
      const index = column - 1;

      if (oldInput[index] !== newInput[index]) {
        rowChanged = true;
        auditRows.push([
          batchId,
          timestamp,
          user,
          sourceRange,
          app.getName(),
          app.getRange(targetRow, column).getA1Notation(),
          watched[column],
          oldInput[index],
          newInput[index]
        ]);
      }
    });

    if (oldConfirmation !== newConfirmation) {
      rowChanged = true;
      auditRows.push([
        batchId,
        timestamp,
        user,
        sourceRange,
        app.getName(),
        app.getRange(targetRow, 25).getA1Notation(),
        watched[25],
        oldConfirmation,
        newConfirmation
      ]);
    }

    if (rowChanged) changedRows++;
  });

  if (auditRows.length) {
    log.getRange(log.getLastRow() + 1, 1, auditRows.length, 9)
      .setValues(auditRows);
  } else {
    appendAuditSummary_(
      log,
      batchId,
      timestamp,
      user,
      sourceRange,
      `No watched fields changed; ${stagedRows.length} staged row(s) processed.`
    );
  }

  // Clear only the staged input area, including the confirmation column.
  stage
    .getRange(2, 1, lastStageRow - 1, 23)
    .clearContent();

  SpreadsheetApp.getUi().alert(
    `Batch ${batchId} complete. ` +
    `${changedRows} row(s) changed; ${appendedRows} row(s) appended.`
  );
}

function appendAuditSummary_(log, batchId, timestamp, user, sourceRange, message) {
