function previewStagedRows() {
  const ss = SpreadsheetApp.getActive();
  const app = ss.getSheetByName("Applications");
  const stage = ss.getSheetByName("Staging");

  if (!app || !stage) throw new Error("Applications or Staging sheet is missing.");

  const lastStageRow = stage.getLastRow();
  if (lastStageRow < 2) {
    SpreadsheetApp.getUi().alert("No staged rows found.");
    return;
  }

  const staged = stage
    .getRange(2, 1, lastStageRow - 1, 23)
    .getDisplayValues()
    .filter(row => row.some(value => value.trim() !== ""));

  if (!staged.length) {
    SpreadsheetApp.getUi().alert("No staged rows found.");
    return;
  }

  const appLastRow = Math.max(app.getLastRow(), 2);
  const appValues = app
    .getRange(2, 1, appLastRow - 1, 25)
    .getDisplayValues();

  const idToRow = new Map();
  const duplicateExisting = new Set();

  appValues.forEach((row, index) => {
    const id = row[0].trim();
    if (!id) return;

    const rowNumber = index + 2;
    if (idToRow.has(id)) duplicateExisting.add(id);
    else idToRow.set(id, rowNumber);
  });

  const stagedIds = new Set();
  const duplicateStaged = new Set();

  staged.forEach(row => {
    const id = row[0].trim();
    if (!id) throw new Error("Every staged row needs an application ID in column A.");
    if (stagedIds.has(id)) duplicateStaged.add(id);
    stagedIds.add(id);
  });

  const duplicateMessages = [];
  if (duplicateExisting.size)
    duplicateMessages.push(
      "Already duplicated in Applications: " +
      [...duplicateExisting].join(", ")
    );
  if (duplicateStaged.size)
    duplicateMessages.push(
      "Duplicated within Staging: " +
      [...duplicateStaged].join(", ")
    );

  if (duplicateMessages.length) {
    SpreadsheetApp.getUi().alert(
      "Preview stopped; no changes were made.\n\n" +
      duplicateMessages.join("\n")
    );
    return;
  }

  const watched = [
    [17, "Filing deadline", 16],
    [21, "Interview deadline", 20],
    [22, "Visa-issuance deadline", 21],
    [25, "Applicability confirmed", 22]
  ];

  const newRows = [];
  const changes = [];

  staged.forEach(row => {
    const id = row[0].trim();
    const targetRow = idToRow.get(id);

    if (!targetRow) {
      newRows.push(id);
      watched.forEach(([column, field, stageIndex]) => {
        if (row[stageIndex] !== "")
          changes.push(`${id} — ${field}: [new] → ${row[stageIndex]}`);
      });
      return;
    }

    const oldRow = appValues[targetRow - 2];

    watched.forEach(([column, field, stageIndex]) => {
      const oldValue = oldRow[column - 1];
      const newValue = row[stageIndex];

      if (oldValue !== newValue) {
        changes.push(
          `${id} — ${field}: ${oldValue || "[blank]"} → ${newValue || "[blank]"}`
        );
      }
    });
  });

  const lines = [
    `Rows reviewed: ${staged.length}`,
    `New rows: ${newRows.length}`,
    `Changed watched fields: ${changes.length}`,
    ""
  ];

  if (newRows.length)
    lines.push("New IDs:\n" + newRows.join("\n") + "");

  if (changes.length)
    lines.push("\nChanges:\n" + changes.join("\n"));

  if (!newRows.length && !changes.length)
    lines.push("No watched fields would change.");

  SpreadsheetApp.getUi().alert(lines.join("\n"));
}
