    : "Staging!A2:W2";

  const historyRows = [];

  if (lastStageRow < 2) {
    historyRows.push([
      batchId, timestamp, "Summary", "", "", "", "",
      `No staged rows found. User: ${user}; Source: ${sourceRange}`
    ]);
    history.getRange(history.getLastRow() + 1, 1, 1, 8)
      .setValues(historyRows);
    SpreadsheetApp.getUi().alert(
      `Preview ${batchId} saved: no staged rows found.`
    );
    return;
  }

  const staged = stage
    .getRange(2, 1, lastStageRow - 1, 23)
    .getDisplayValues()
    .filter(row => row.some(value => value.trim() !== ""));

  const appLastRow = Math.max(app.getLastRow(), 2);
  const appValues = app
    .getRange(2, 1, appLastRow - 1, 25)
    .getDisplayValues();

  const idToRow = new Map();
  const duplicateExisting = new Set();

  appValues.forEach((row, index) => {
    const id = row[0].trim();
    if (!id) return;

    const rowNumber = index + 2;
    if (idToRow.has(id)) {
      duplicateExisting.add(id);
    } else {
      idToRow.set(id, rowNumber);
    }
  });

  const stagedIds = new Set();
  const duplicateStaged = new Set();
  const missingIdRows = [];

  staged.forEach((row, index) => {
    const id = row[0].trim();

    if (!id) {
      missingIdRows.push(index + 2);
      return;
    }

    if (stagedIds.has(id)) duplicateStaged.add(id);
    stagedIds.add(id);
  });

  duplicateExisting.forEach(id => {
    historyRows.push([
      batchId, timestamp, "Duplicate existing ID", id, "", "", "",
      "The ID appears more than once in Applications."
    ]);
  });

  duplicateStaged.forEach(id => {
    historyRows.push([
      batchId, timestamp, "Duplicate staged ID", id, "", "", "",
      "The ID appears more than once in this staging batch."
    ]);
  });

  missingIdRows.forEach(rowNumber => {
    historyRows.push([
      batchId, timestamp, "Validation error", "", "", "", "",
      `Staging row ${rowNumber} has no application ID in column A.`
    ]);
  });

  const hasValidationErrors =
    duplicateExisting.size ||
    duplicateStaged.size ||
    missingIdRows.length;

  const watched = [
    [17, "Filing deadline", 16],           // Applications Q, Staging Q
    [21, "Interview deadline", 20],         // Applications U, Staging U
    [22, "Visa-issuance deadline", 21],     // Applications V, Staging V
    [25, "Applicability confirmed", 22]    // Applications Y, Staging W
  ];

  let newRowCount = 0;
  let changeCount = 0;

  if (!hasValidationErrors) {
    staged.forEach(row => {
      const id = row[0].trim();
      const targetRow = idToRow.get(id);

      if (!targetRow) {
        newRowCount++;

        historyRows.push([
          batchId, timestamp, "New row", id, "", "", "",
          "This application ID would be appended."
        ]);

        watched.forEach(([column, field, stageIndex]) => {
          const newValue = row[stageIndex];
