        const newValue = row[stageIndex];

        if (oldValue !== newValue) {
          changeCount++;
          historyRows.push([
            batchId, timestamp, "Changed field", id, field,
            oldValue, newValue,
            `Applications ${app.getRange(targetRow, column).getA1Notation()}`
          ]);
        }
      });
    });
  }

  if (!hasValidationErrors && newRowCount === 0 && changeCount === 0) {
    historyRows.push([
      batchId, timestamp, "Summary", "", "", "", "",
      "No watched fields would change and no new rows would be appended."
    ]);
  } else {
    historyRows.push([
      batchId, timestamp, "Summary", "", "", "", "",
      `Rows reviewed: ${staged.length}; New rows: ${newRowCount}; ` +
      `Changed watched fields: ${changeCount}; ` +
      `Validation errors: ${hasValidationErrors ? "Yes" : "No"}; ` +
      `User: ${user}; Source: ${sourceRange}`
    ]);
  }

  history.getRange(
    history.getLastRow() + 1,
    1,
    historyRows.length,
    headers.length
  ).setValues(historyRows);

  history.autoResizeColumns(1, headers.length);
  history.setFrozenRows(1);

  ss.setActiveSheet(history);
  SpreadsheetApp.getUi().alert(
    `Preview ${batchId} saved to “Preview history”.\n` +
    `${newRowCount} new row(s), ${changeCount} changed watched field(s).` +
    (hasValidationErrors ? "\nValidation errors were found; apply is not recommended." : "")
  );
}
