Use a non-destructive probe that returns a temporary replacement list, then commit it only after the current fragment has been drawn:

```python
def peek_next_fit(queue, width, available_h, measure_box):
    if not queue or available_h <= 0:
        return False, None

    item = queue[0]
    if measure_box(item, width, available_h) <= available_h:
        return True, [item]

    pieces = list(item.split(width, available_h))  # Paragraph.split is non-mutating
    if not pieces:
        return False, None
    return measure_box(pieces[0], width, available_h) <= available_h, pieces

def commit_probe(queue, pieces):
    if pieces and pieces[0] is not queue[0]:
        queue.popleft()
        queue.extendleft(reversed(pieces))
```

