Use a fresh destination whenever the preferred path already exists, rather than deleting or replacing an artifact that Windows may still have open:

```python
def publish_atomically(work: Path, destination: Path) -> Path:
    destination.parent.mkdir(parents=True, exist_ok=True)
    target = destination
    if target.exists():
        target = destination.with_name(
            f"{destination.name}-rerun-{uuid.uuid4().hex[:8]}"
        )

    staging = target.parent / f".{target.name}.tmp-{uuid.uuid4().hex}"
    try:
        shutil.copytree(work, staging)
        os.replace(staging, target)  # target is deliberately nonexistent
        return target
    finally:
        shutil.rmtree(staging, ignore_errors=True)
```

