};

function onFormSubmit(e) {
  const responseSheet = e.range.getSheet();
  const row = e.range.getRow();
  const lastColumn = responseSheet.getLastColumn();
  const headers = responseSheet.getRange(1, 1, 1, lastColumn).getValues()[0];
  const values = responseSheet.getRange(row, 1, 1, lastColumn).getValues()[0];

  const getValue = header => {
    const index = headers.indexOf(header);
    return index === -1 ? '' : values[index];
  };

  const fileName = String(getValue(CONFIG.fileQuestion)).trim();
  const confirmation = String(getValue(CONFIG.confirmationQuestion)).toLowerCase();
  const reviewerEmail = String(
    getValue('Email Address') || getValue('Email')
  ).trim();
  const timestamp = values[0] || new Date();

  if (!fileName || !(confirmation.includes('confirm') ||
                     confirmation === 'yes' ||
                     confirmation === 'true')) return;

  const ss = SpreadsheetApp.getActiveSpreadsheet();
  const sheet = ss.getSheetByName(CONFIG.currentFilesSheetName);
  if (!sheet) throw new Error('Current Files sheet was not found.');

  const data = sheet.getDataRange().getValues();
  const headers2 = data[0];
  const fileCol = headers2.indexOf('File Name');
  const reviewedCol = headers2.indexOf('Last Reviewed');
  const reviewerCol = headers2.indexOf('Reviewer Email');

  if ([fileCol, reviewedCol, reviewerCol].includes(-1)) {
    throw new Error('Current Files must have the required headers.');
  }

  for (let r = 1; r < data.length; r++) {
    if (String(data[r][fileCol]).trim() === fileName) {
      sheet.getRange(r + 1, reviewedCol + 1).setValue(timestamp);
      sheet.getRange(r + 1, reviewerCol + 1).setValue(reviewerEmail);
      return;
    }
  }

  console.log('Form file did not match Current Files: ' + fileName);
}

function sendMonthlyReminder() {
  const ss = SpreadsheetApp.getActiveSpreadsheet();
  const sheet = ss.getSheetByName(CONFIG.currentFilesSheetName);
  if (!sheet) throw new Error('Current Files sheet was not found.');

  const data = sheet.getDataRange().getValues();
  const headers = data[0];
  const fileCol = headers.indexOf('File Name');
  const reviewedCol = headers.indexOf('Last Reviewed');

  if ([fileCol, reviewedCol].includes(-1)) {
    throw new Error('Current Files must have File Name and Last Reviewed headers.');
  }

  const cutoff = new Date();
  cutoff.setDate(cutoff.getDate() - CONFIG.overdueDays);

  const overdue = [];
  for (let r = 1; r < data.length; r++) {
    const fileName = String(data[r][fileCol]).trim();
    const lastReviewed = data[r][reviewedCol];

    if (!fileName || !lastReviewed ||
        !(lastReviewed instanceof Date) ||
        lastReviewed < cutoff) {
      overdue.push(fileName || '(unnamed file)');
    }
  }

  const subject = overdue.length
    ? 'Current files needing review'
    : 'Monthly current-file review: all up to date';

  const body = overdue.length
    ? 'These files have not been reviewed within the last ' +
      CONFIG.overdueDays + ' days:\n\n- ' + overdue.join('\n- ')
    : 'All files in Current Files were reviewed within the last ' +
