Below is the complete script with the empty-file check included. Replace `you@example.com`, verify the question titles match your Form exactly, and set the Apps Script project time zone before running `installTriggers()`.

```javascript
const CONFIG = {
  responseSheetName: 'Form Responses 1',
  currentFilesSheetName: 'Current Files',

  fileQuestion: 'Which current file did you open?',
  confirmationQuestion: 'I confirm I opened and reviewed this current file',

  notifyEmail: 'you@example.com',
  overdueDays: 30
};


/**
 * Runs automatically when a Form response is submitted.
 * Updates the matching row in Current Files.
 */
function onFormSubmit(e) {
  if (!e || !e.range) {
    throw new Error('This function must be run by a spreadsheet form-submit trigger.');
  }

  const responseSheet = e.range.getSheet();
  const rowNumber = e.range.getRow();
  const lastColumn = responseSheet.getLastColumn();

  const responseHeaders = responseSheet
    .getRange(1, 1, 1, lastColumn)
    .getValues()[0];

  const responseValues = responseSheet
    .getRange(rowNumber, 1, 1, lastColumn)
    .getValues()[0];

  function getResponseValue(headerName) {
    const columnIndex = responseHeaders.indexOf(headerName);
    return columnIndex === -1 ? '' : responseValues[columnIndex];
  }

  const fileName = String(
    getResponseValue(CONFIG.fileQuestion)
  ).trim();

  const confirmation = String(
    getResponseValue(CONFIG.confirmationQuestion)
  ).toLowerCase();

  const reviewerEmail = String(
    getResponseValue('Email Address') ||
    getResponseValue('Email')
  ).trim();

  const timestamp =
    getResponseValue('Timestamp') ||
    responseValues[0] ||
    new Date();

  // Ignore incomplete or unconfirmed submissions.
  if (!fileName) return;

  const isConfirmed =
    confirmation.includes('confirm') ||
    confirmation === 'yes' ||
    confirmation === 'true';

  if (!isConfirmed) return;

  const spreadsheet = SpreadsheetApp.getActiveSpreadsheet();
  const currentFilesSheet = spreadsheet.getSheetByName(
    CONFIG.currentFilesSheetName
  );

  if (!currentFilesSheet) {
    throw new Error(
      'The sheet "' + CONFIG.currentFilesSheetName + '" was not found.'
    );
  }

  const data = currentFilesSheet.getDataRange().getValues();

  if (!data.length) {
    throw new Error('The Current Files sheet has no headers.');
  }

  const currentHeaders = data[0];
  const fileColumn = currentHeaders.indexOf('File Name');
  const reviewedColumn = currentHeaders.indexOf('Last Reviewed');
  const reviewerColumn = currentHeaders.indexOf('Reviewer Email');

  if ([fileColumn, reviewedColumn, reviewerColumn].includes(-1)) {
    throw new Error(
      'Current Files must contain these headers: ' +
      'File Name, Last Reviewed, Reviewer Email'
    );
  }

  for (let row = 1; row < data.length; row++) {
    const listedFileName = String(
      data[row][fileColumn] || ''
    ).trim();

    if (listedFileName === fileName) {
      currentFilesSheet
        .getRange(row + 1, reviewedColumn + 1)
        .setValue(timestamp);

      currentFilesSheet
        .getRange(row + 1, reviewerColumn + 1)
        .setValue(reviewerEmail);

      return;
    }
  }

  // The Form response did not match a file currently listed.
  console.log('No matching file found for: ' + fileName);
}


/**
 * Sends the monthly reminder.
 * Files with a blank, invalid, or older-than-30-days review date are included.
 */
function sendMonthlyReminder() {
  const spreadsheet = SpreadsheetApp.getActiveSpreadsheet();
  const currentFilesSheet = spreadsheet.getSheetByName(
    CONFIG.currentFilesSheetName
  );

  if (!currentFilesSheet) {
    throw new Error(
      'The sheet "' + CONFIG.currentFilesSheetName + '" was not found.'
    );
  }

  const data = currentFilesSheet.getDataRange().getValues();

  // Stop without sending email if the sheet has no header row.
  if (!data.length) return;

  const headers = data[0];
  const fileColumn = headers.indexOf('File Name');
  const reviewedColumn = headers.indexOf('Last Reviewed');

  if ([fileColumn, reviewedColumn].includes(-1)) {
    throw new Error(
      'Current Files must contain these headers: File Name and Last Reviewed'
    );
  }

  // Only count nonblank file rows.
  const listedFiles = data
    .slice(1)
    .map(row => String(row[fileColumn] || '').trim())
    .filter(Boolean);

  // Do not send an email when no files are listed.
  if (!listedFiles.length) return;

  const cutoff = new Date();
  cutoff.setDate(cutoff.getDate() - CONFIG.overdueDays);

  const overdueFiles = [];

  for (let row = 1; row < data.length; row++) {
    const fileName = String(
      data[row][fileColumn] || ''
    ).trim();

    // Ignore completely blank rows.
    if (!fileName) continue;

    const lastReviewed = data[row][reviewedColumn];

    const hasValidReviewDate =
      lastReviewed instanceof Date &&
      !isNaN(lastReviewed.getTime());

    if (!hasValidReviewDate || lastReviewed < cutoff) {
      overdueFiles.push(fileName);
    }
  }

  const subject = overdueFiles.length
    ? 'Current files needing review'
    : 'Monthly current-file review: all up to date';

  const body = overdueFiles.length
    ? 'These files have not been reviewed within the last ' +
      CONFIG.overdueDays +
      ' days:\n\n- ' +
      overdueFiles.join('\n- ')
    : 'All files in Current Files were reviewed within the last ' +
      CONFIG.overdueDays +
      ' days.';

  MailApp.sendEmail({
    to: CONFIG.notifyEmail,
    subject: subject,
    body: body
  });
}


/**
 * Optional manual test function.
 * Run this from Apps Script to test the reminder immediately.
 */
function testMonthlyReminder() {
  sendMonthlyReminder();
}


/**
 * Installs or reinstalls the Form-submit and monthly triggers.
 */
function installTriggers() {
  const spreadsheet = SpreadsheetApp.getActiveSpreadsheet();

  // Remove older copies of these triggers first.
  ScriptApp.getProjectTriggers().forEach(trigger => {
    const handler = trigger.getHandlerFunction();

    if (
      handler === 'onFormSubmit' ||
      handler === 'sendMonthlyReminder'
    ) {
      ScriptApp.deleteTrigger(trigger);
    }
  });

  // Trigger for each submitted Form response.
  ScriptApp.newTrigger('onFormSubmit')
    .forSpreadsheet(spreadsheet)
    .onFormSubmit()
    .create();

  // Runs on the first day of each month, during the 8:00 a.m. hour.
  ScriptApp.newTrigger('sendMonthlyReminder')
    .timeBased()
    .onMonthDay(1)
    .atHour(8)
    .create();
}
```

