```javascript
function testCurrentFilesAgainstSharedFolder() {
  const folder = DriveApp.getFolderById(CONFIG.sharedFolderId);
  const spreadsheet = SpreadsheetApp.openById(CONFIG.currentFilesSpreadsheetId);
  const sheet = spreadsheet.getSheetByName('Current Files');

  if (!sheet) {
    throw new Error('Sheet "Current Files" was not found.');
  }

  const values = sheet.getDataRange().getDisplayValues();
  if (values.length === 0) {
    throw new Error('Current Files sheet is empty.');
  }

  const headers = values[0].map(normalizeHeader);
  const statusColumn = findColumn(headers, ['status', 'state']);
  const nameColumn = findColumn(headers, ['file name', 'filename', 'name']);
  const idColumn = findColumn(headers, ['file id', 'id']);
  const urlColumn = findColumn(headers, ['url', 'file url', 'link']);

  if (nameColumn === -1 && idColumn === -1 && urlColumn === -1) {
    throw new Error('The sheet needs a File Name, File ID, or URL column.');
  }

  // Only files whose names contain the standalone word CURRENT are included.
  const folderCurrentFiles = [];
  const files = folder.getFiles();

  while (files.hasNext()) {
    const file = files.next();
    if (/\bCURRENT\b/i.test(file.getName())) {
      folderCurrentFiles.push({
        id: file.getId(),
        name: file.getName(),
        key: file.getId()
      });
    }
  }

  const sheetCurrentEntries = [];
  for (let row = 1; row < values.length; row++) {
    const record = values[row];
    const status = statusColumn >= 0
      ? String(record[statusColumn]).trim().toUpperCase()
      : 'CURRENT';

    if (status !== 'CURRENT') continue;

    const name = nameColumn >= 0 ? String(record[nameColumn]).trim() : '';
    const id = idColumn >= 0 ? String(record[idColumn]).trim() : '';
    const url = urlColumn >= 0 ? String(record[urlColumn]).trim() : '';
    const extractedId = id || extractDriveId(url);

    sheetCurrentEntries.push({
      row: row + 1,
      name: name || '(unnamed)',
      id: extractedId,
      key: extractedId || normalizeName(name)
    });
  }

  const folderKeys = new Set(
    folderCurrentFiles.map(file => file.key)
  );
  const sheetKeys = new Set(
    sheetCurrentEntries.map(entry => entry.key)
  );

  const missingFromSheet = folderCurrentFiles.filter(file => {
    return !sheetKeys.has(file.key) &&
      !sheetCurrentEntries.some(entry =>
        !entry.id && normalizeName(entry.name) === normalizeName(file.name)
      );
  });

  const extraInSheet = sheetCurrentEntries.filter(entry => {
    return !folderKeys.has(entry.key) &&
      !folderCurrentFiles.some(file =>
        normalizeName(file.name) === normalizeName(entry.name)
      );
  });

  console.log(JSON.stringify({
    test: 'CURRENT shared-folder files versus Current Files sheet',
    reminderFunctionCalled: false,
    emailSent: false,
    sheetModified: false,
    folderModified: false,
    folderCurrentCount: folderCurrentFiles.length,
    sheetCurrentCount: sheetCurrentEntries.length,
    missingFromSheet: missingFromSheet.map(file => ({
