function testDriveFileIdsAndSharedFolderLinks() {
  const folder = DriveApp.getFolderById(CONFIG.sharedFolderId);
  const spreadsheet = SpreadsheetApp.openById(
    CONFIG.currentFilesSpreadsheetId
  );
  const sheet = spreadsheet.getSheetByName('Current Files');

  if (!sheet) {
    throw new Error('Sheet "Current Files" was not found.');
  }

  const values = sheet.getDataRange().getDisplayValues();
  if (!values.length) {
    throw new Error('Current Files sheet is empty.');
  }

  const headers = values[0].map(testIdNormalizeHeader_);
  const statusColumn = testIdFindColumn_(
    headers, ['status', 'state']
  );
  const idColumn = testIdFindColumn_(
    headers, ['file id', 'id']
  );
  const urlColumn = testIdFindColumn_(
    headers, ['url', 'file url', 'link']
  );
  const nameColumn = testIdFindColumn_(
    headers, ['file name', 'filename', 'name']
  );

  if (idColumn < 0 && urlColumn < 0) {
    throw new Error('The sheet needs a File ID or URL column.');
  }

  const currentSheetRows = [];

  for (let row = 1; row < values.length; row++) {
    const record = values[row];
    const status = statusColumn >= 0
      ? String(record[statusColumn]).trim().toUpperCase()
      : 'CURRENT';

    if (status !== 'CURRENT') continue;

    const explicitId = idColumn >= 0
      ? String(record[idColumn]).trim()
      : '';
    const url = urlColumn >= 0
      ? String(record[urlColumn]).trim()
      : '';
    const fileId = explicitId || testIdExtractDriveId_(url);

    currentSheetRows.push({
      row: row + 1,
      name: nameColumn >= 0
        ? String(record[nameColumn]).trim() || '(unnamed)'
        : '(unnamed)',
      url: url,
      fileId: fileId
    });
  }

  const folderFiles = [];
  const folderFileIterator = folder.getFiles();

  while (folderFileIterator.hasNext()) {
    const file = folderFileIterator.next();
    folderFiles.push({
      name: file.getName(),
      fileId: file.getId()
    });
  }

  const sheetIdGroups = testIdGroupById_(currentSheetRows);
  const folderIdGroups = testIdGroupById_(folderFiles);

  const missingSheetIds = currentSheetRows
    .filter(entry => !entry.fileId)
    .map(entry => ({
      row: entry.row,
      name: entry.name,
      message: 'No usable Drive file ID was found in the ID or URL column.'
    }));

  const duplicateSheetIds = Object.keys(sheetIdGroups)
    .filter(id => sheetIdGroups[id].length > 1)
    .map(id => ({
      fileId: id,
      rows: sheetIdGroups[id].map(entry => entry.row),
      names: sheetIdGroups[id].map(entry => entry.name)
    }));

  // Drive IDs are normally unique in a folder; this is included as a
  // defensive check and also makes the output explicit.
  const duplicateFolderIds = Object.keys(folderIdGroups)
    .filter(id => folderIdGroups[id].length > 1)
    .map(id => ({
      fileId: id,
      files: folderIdGroups[id].map(file => file.name)
    }));

  const outsideSharedFolder = [];
  const unresolvedIds = [];

  currentSheetRows.forEach(entry => {
    if (!entry.fileId) return;

    try {
      const file = DriveApp.getFileById(entry.fileId);
      const parents = file.getParents();
      let isDirectlyInSharedFolder = false;

      while (parents.hasNext()) {
        if (parents.next().getId() === folder.getId()) {
          isDirectlyInSharedFolder = true;
          break;
        }
      }

      if (!isDirectlyInSharedFolder) {
        outsideSharedFolder.push({
          row: entry.row,
          name: entry.name,
          fileId: entry.fileId,
          url: entry.url || 'None'
        });
      }
    } catch (error) {
      unresolvedIds.push({
        row: entry.row,
        name: entry.name,
        fileId: entry.fileId,
        message: 'File could not be read: ' + error.message
      });
    }
  });

  const folderIds = new Set(folderFiles.map(file => file.fileId));
  const sheetIds = new Set(
    currentSheetRows
      .filter(entry => entry.fileId)
      .map(entry => entry.fileId)
  );

  const folderFilesMissingFromSheet = folderFiles
    .filter(file => !sheetIds.has(file.fileId));

  const sheetIdsNotFoundAsDirectFolderFiles = currentSheetRows
    .filter(entry =>
      entry.fileId &&
      !folderIds.has(entry.fileId) &&
      !unresolvedIds.some(item => item.row === entry.row)
    );

  const hasProblems =
    missingSheetIds.length > 0 ||
    duplicateSheetIds.length > 0 ||
    duplicateFolderIds.length > 0 ||
    outsideSharedFolder.length > 0 ||
    unresolvedIds.length > 0 ||
    folderFilesMissingFromSheet.length > 0 ||
    sheetIdsNotFoundAsDirectFolderFiles.length > 0;

  console.log(JSON.stringify({
    test: 'Drive file ID and shared-folder link integrity',
    reminderFunctionCalled: false,
    emailSent: false,
    folderModified: false,
    sheetModified: false,

    missingIds: {
      currentSheetRowsWithoutUsableIds: missingSheetIds,
      folderFilesMissingFromSheet: folderFilesMissingFromSheet
    },

    duplicateIds: {
      currentSheetIds: duplicateSheetIds,
      folderFileIds: duplicateFolderIds
    },

    outsideSharedFolder: outsideSharedFolder,

    unresolvedIds: unresolvedIds,

    sheetIdsNotFoundAsDirectFolderFiles:
      sheetIdsNotFoundAsDirectFolderFiles,

    status: hasProblems
      ? 'PROBLEMS: missing, duplicate, unresolved, or out-of-folder IDs found.'
      : 'OK: Drive IDs are present and links resolve to files directly in the shared folder.'
  }, null, 2));
}

