function onCaregiverChecklistSubmit_(event) {
  const response = event.response;
  const answers = {};

  response.getItemResponses().forEach(itemResponse => {
    const title = itemResponse.getItem().getTitle();
    const answer = itemResponse.getResponse();
    answers[title] = Array.isArray(answer) ? answer.join(', ') : answer;
  });

  const auditId = String(answers['Audit ID'] || '').trim();
  const fileId = String(answers['File ID'] || '').trim();
  if (!auditId || !fileId) return;

  const ss = SpreadsheetApp.openById(CONFIG.privateAuditSpreadsheetId);
  const sheet = ss.getSheetByName('Caregiver Checklist');
  if (!sheet) throw new Error('Caregiver Checklist sheet was not found.');

  const values = sheet.getDataRange().getValues();
  const headers = values[0].map(String);
  const col = name => headers.indexOf(name) + 1;

  const auditCol = col('Audit ID');
  const fileIdCol = col('File ID');
  const openedCol = col('Opened Successfully');
  const editingCol = col('Editing Blocked');
  const dateCol = col('Checked Date');
  const notesCol = col('Notes');

  let row = -1;
  for (let i = 1; i < values.length; i++) {
    if (String(values[i][auditCol - 1]) === auditId &&
        String(values[i][fileIdCol - 1]) === fileId) {
      row = i + 1;
      break;
    }
  }

  // Reject arbitrary file/audit IDs that were not generated by the audit.
  if (row === -1) return;

  sheet.getRange(row, openedCol).setValue(answers['Opened Successfully'] || '');
  sheet.getRange(row, editingCol).setValue(answers['Editing Blocked'] || '');
  sheet.getRange(row, dateCol).setValue(answers['Checked Date'] || '');
  sheet.getRange(row, notesCol).setValue(answers['Notes'] || '');

  updateAuditStatusFromChecklist_(ss, auditId);
}
