function updateAuditStatusFromChecklist_(ss, auditId) {
  const checklist = ss.getSheetByName('Caregiver Checklist');
  const log = ss.getSheetByName('Audit Log');
  const rows = checklist.getDataRange().getValues();
  const h = rows[0].map(String), c = name => h.indexOf(name);

  const auditRows = rows.slice(1).filter(row =>
    String(row[c('Audit ID')]) === String(auditId)
  );

  const incomplete = auditRows
    .filter(row =>
      String(row[c('Opened Successfully')]).toLowerCase() !== 'yes' ||
      String(row[c('Editing Blocked')]).toLowerCase() !== 'yes' ||
      !String(row[c('Checked Date')]).trim()
    )
    .map(row => String(row[c('File')]));

  const complete = auditRows.length > 0 && incomplete.length === 0;
  const logValues = log.getDataRange().getValues();
  const lh = logValues[0].map(String);
  const idCol = lh.indexOf('Audit ID');
  const statusCol = lh.indexOf('Status');
  const incompleteCol = lh.indexOf('Incomplete Files');

  for (let i = 1; i < logValues.length; i++) {
    if (String(logValues[i][idCol]) !== String(auditId)) continue;
    const current = String(logValues[i][statusCol]);

    if (current !== 'REVIEW') {
      log.getRange(i + 1, statusCol + 1)
        .setValue(complete ? 'PASS' : 'MANUAL-TEST-NEEDED');
    }
    if (incompleteCol >= 0) {
      log.getRange(i + 1, incompleteCol + 1)
        .setValue(incomplete.join('\n') || 'None');
    }
    break;
  }
}
