```javascript
function syncChecklistForRerun_(ss, auditId, currentFiles) {
  const sheet = ss.getSheetByName('Caregiver Checklist');
  const archive = ss.getSheetByName('Checklist Archive') ||
    ss.insertSheet('Checklist Archive');
  const values = sheet.getDataRange().getValues();
  const headers = values[0].map(String);
  const col = name => headers.indexOf(name);
  const currentIds = new Set(currentFiles.map(f => String(f.fileId)));
  const idCol = col('File ID'), auditCol = col('Audit ID'), fileCol = col('File');

  if (archive.getLastRow() === 0) archive.appendRow(headers.concat('Archived At'));

  // Archive rows for files no longer CURRENT.
  for (let r = values.length - 1; r >= 1; r--) {
    if (String(values[r][auditCol]) !== String(auditId)) continue;
    if (!currentIds.has(String(values[r][idCol]))) {
      archive.appendRow(values[r].concat(new Date()));
      sheet.deleteRow(r + 1);
    }
  }

  const latest = sheet.getDataRange().getValues();
  const existingIds = new Set(latest.slice(1)
    .filter(r => String(r[auditCol]) === String(auditId))
    .map(r => String(r[idCol])));

  currentFiles.forEach(file => {
    const id = String(file.fileId);
    if (existingIds.has(id)) {
      const rows = sheet.getDataRange().getValues();
      for (let r = 1; r < rows.length; r++) {
        if (String(rows[r][auditCol]) === String(auditId) &&
            String(rows[r][idCol]) === id) {
          sheet.getRange(r + 1, fileCol + 1).setValue(file.name);
          break;
        }
      }
    } else {
      sheet.appendRow([auditId, file.name, id, '', '', '', '']);
    }
  });
}
