```javascript
function syncChecklistForRerun_(ss, auditId, currentFiles) {
  const sheet = ss.getSheetByName('Caregiver Checklist');
  const archive = ss.getSheetByName('Checklist Archive') ||
    ss.insertSheet('Checklist Archive');
  const values = sheet.getDataRange().getValues();
  const h = values[0].map(String);
  const c = name => h.indexOf(name);
  const auditCol = c('Audit ID'), fileCol = c('File');
  const idCol = c('File ID'), notesCol = c('Notes');
  const currentByName = new Map(currentFiles.map(f => [String(f.name), f]));

  if (archive.getLastRow() === 0)
    archive.appendRow(h.concat('Archived At', 'Archive Reason'));

  for (let r = values.length - 1; r >= 1; r--) {
    if (String(values[r][auditCol]) !== String(auditId)) continue;

    const oldName = String(values[r][fileCol]);
    const oldId = String(values[r][idCol]);
    const current = currentByName.get(oldName);
    const reason = current && String(current.fileId) !== oldId
      ? 'REPLACED: same filename, new Drive File ID'
      : !current ? 'NO LONGER CURRENT' : null;

    if (reason) {
      archive.appendRow(values[r].concat([new Date(), reason]));
      sheet.deleteRow(r + 1);
    }
  }

  const latest = sheet.getDataRange().getValues();
  const existingIds = new Set(latest.slice(1)
    .filter(r => String(r[auditCol]) === String(auditId))
    .map(r => String(r[idCol])));

  currentFiles.forEach(file => {
    if (!existingIds.has(String(file.fileId))) {
