Use a clear marker that does not depend on the filename—for example, set the Drive file description to exactly `CURRENT`. This recursively scans the selected shared folder and returns only matching files:

```javascript
function getCurrentFilesFromSharedFolder_() {
  const folderId = PropertiesService.getScriptProperties()
    .getProperty('SHARED_FOLDER_ID');
  if (!folderId) throw new Error('SHARED_FOLDER_ID is not configured.');

  const root = DriveApp.getFolderById(folderId);
  const results = [];
  const seen = new Set();

  function scanFolder_(folder) {
    const files = folder.getFiles();
    while (files.hasNext()) {
      const file = files.next();
      const id = file.getId();

      // The file must be explicitly marked CURRENT in its description.
      if (String(file.getDescription()).trim().toUpperCase() !== 'CURRENT') continue;
      if (seen.has(id)) continue;

      seen.add(id);
      results.push({
        name: file.getName(),
        fileId: id
      });
    }

    const subfolders = folder.getFolders();
    while (subfolders.hasNext()) scanFolder_(subfolders.next());
  }

  scanFolder_(root);
  return results;
}
```

Add this read-only validation before calling `dryRunChecklistRerun_`; it prevents an approval dialog when filenames are missing or ambiguous:

```javascript
function validateRerunPreview_(ss, auditId, currentFiles) {
  const errors = [];

  const currentByName = new Map();
  currentFiles.forEach(file => {
    const name = String(file.name || '').trim();
    if (!name) {
      errors.push(`Current file ${file.fileId || '(unknown ID)'} has no filename.`);
      return;
    }
    if (!currentByName.has(name)) currentByName.set(name, []);
    currentByName.get(name).push(file.fileId);
  });

  currentByName.forEach((ids, name) => {
    if (ids.length > 1) {
      errors.push(`Duplicate CURRENT filename: "${name}" (${ids.length} files).`);
    }
  });

  const sheet = ss.getSheetByName('Caregiver Checklist');
  if (!sheet) return errors.concat('Caregiver Checklist sheet was not found.');

  const values = sheet.getDataRange().getValues();
  const headers = values[0].map(String);
  const auditCol = headers.indexOf('Audit ID');
  const fileCol = headers.indexOf('File');

  if (auditCol < 0 || fileCol < 0) {
    return errors.concat('Checklist must contain Audit ID and File columns.');
  }

  const priorByName = new Map();
  values.slice(1).forEach(row => {
    if (String(row[auditCol]) !== String(auditId)) return;
    const name = String(row[fileCol] || '').trim();
    if (!name) {
      errors.push('An existing checklist row has no filename.');
      return;
    }
    if (!priorByName.has(name)) priorByName.set(name, []);
    priorByName.get(name).push(name);
  });

  priorByName.forEach((rows, name) => {
    if (rows.length > 1) {
      errors.push(`Duplicate existing checklist filename: "${name}".`);
    }
  });

  return errors;
}
