function addReportLinkToAuditRows_(ss, auditId, reportUrl) {
  const sheet = ss.getSheetByName('Audit Log');
  if (!sheet) return;

  const data = sheet.getDataRange().getValues();
  if (!data.length) return;

  const headers = data[0].map(String);
  const auditCol = headers.indexOf('Audit ID');
  if (auditCol < 0) throw new Error('Audit Log must contain an Audit ID column.');

