Use both a script lock (for simultaneous runs) and a recent-success check (for sequential duplicate triggers); set `RETENTION_MONTHS` to your desired retention period:

```javascript
function createWeeklyBackup() {
  const lock = LockService.getScriptLock();
  if (!lock.tryLock(30000)) return;

  const RETENTION_MONTHS = 3;
  const ss = SpreadsheetApp.getActive();
  const log = ss.getSheetByName('Backup Log');
  const folder = DriveApp.getFolderById('FOLDER_ID');
  const now = new Date();

  try {
    const rows = log.getLastRow() > 1
      ? log.getRange(2, 1, log.getLastRow() - 1, 2).getValues()
      : [];
    const weekAgo = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000);
    const alreadyBackedUp = rows.some(r =>
      r[1] === 'Successful' && r[0] instanceof Date && r[0] >= weekAgo && r[0] <= now
    );
    if (alreadyBackedUp) return;

    const source = DriveApp.getFileById(ss.getId());
    const stamp = Utilities.formatDate(now, Session.getScriptTimeZone(), 'yyyy-MM-dd HH:mm');
    const copy = source.makeCopy(`${ss.getName()} backup ${stamp}`, folder);
    log.appendRow([now, 'Successful', copy.getName(), copy.getUrl()]);

    const cutoff = new Date(now);
    cutoff.setMonth(cutoff.getMonth() - RETENTION_MONTHS);
    const files = folder.getFiles();
    const prefix = `${ss.getName()} backup `;
    while (files.hasNext()) {
      const file = files.next();
      if (file.getName().startsWith(prefix) && file.getDateCreated() < cutoff) {
        file.setTrashed(true); // moves it to Drive trash, rather than permanently deleting it
      }
    }
  } catch (err) {
    log.appendRow([now, 'Failed', '', String(err)]);
    throw err;
  } finally {
    lock.releaseLock();
  }
}
```

