```javascript
function testLatestBackupWithLog() {
  const live = SpreadsheetApp.getActive();
  const sourceLog = live.getSheetByName('Backup Log');
  const resultLog = live.getSheetByName('Restore Test Log'); // Create this separately
  const keyCells = ['Dashboard!B5', 'Dashboard!B6']; // Use stable/invariant cells

  if (!sourceLog || !resultLog) {
    throw new Error('Backup Log and Restore Test Log sheets are required.');
  }

  let status = 'PASSED';
  let details = '';
  let backupUrl = '';

  try {
    const rows = sourceLog.getLastRow() < 2 ? [] :
      sourceLog.getRange(2, 1, sourceLog.getLastRow() - 1, 4)
        .getValues()
        .filter(r => r[1] === 'Successful' && r[3])
        .sort((a, b) => new Date(b[0]) - new Date(a[0]));

    if (!rows.length) throw new Error('No successful backup found.');

    backupUrl = String(rows[0][3]);
    const id = backupUrl.match(/[-\w]{25,}/)?.[0];
    if (!id || id === live.getId()) throw new Error('Invalid or live-file backup ID.');

    const backup = SpreadsheetApp.openById(id);
    const problems = [];

    // Compare displayed values for selected stable cells.
    keyCells.forEach(address => {
      const [sheetName, cell] = address.split('!');
      const liveSheet = live.getSheetByName(sheetName);
      const backupSheet = backup.getSheetByName(sheetName);

      if (!liveSheet || !backupSheet) {
        problems.push(`${address}: sheet missing`);
        return;
      }

      const liveValue = liveSheet.getRange(cell).getDisplayValue();
      const backupValue = backupSheet.getRange(cell).getDisplayValue();

      if (liveValue !== backupValue) {
        problems.push(`${address}: live="${liveValue}", backup="${backupValue}"`);
      }
    });

    // Compare chart source ranges, without modifying either file.
    const chartSources = spreadsheet =>
      spreadsheet.getSheets().flatMap(sheet =>
        sheet.getCharts().flatMap(chart =>
          chart.getRanges().map(range =>
            `${range.getSheet().getName()}!${range.getA1Notation()}`
          )
        )
      ).sort();

    const liveCharts = JSON.stringify(chartSources(live));
    const backupCharts = JSON.stringify(chartSources(backup));

    if (liveCharts !== backupCharts) {
      problems.push(`Chart source ranges differ: live=${liveCharts}, backup=${backupCharts}`);
    }

    if (problems.length) {
      status = 'FAILED';
      details = problems.join(' | ');
    } else {
      details = `Opened ${backup.getName()}; displayed values and chart sources match.`;
    }
  } catch (err) {
    status = 'FAILED';
    details = err.message;
  }

  // The only write is to the separate live-file test log.
  resultLog.appendRow([new Date(), status, backupUrl, details]);
  console.log(`${status}: ${details}`);
  return `${status}: ${details}`;
}
```

