This prevents duplicate log rows for the same copied file; two separate confirmed clicks will still create two distinct backups and therefore produce two legitimate log entries.

Use this fixed **Backup Log** layout: `Completion Time | Status | File Name | File URL | File ID`. Lock the manual workflow to prevent overlapping clicks, and lock the check-plus-append operation so a file ID can never be logged twice:

```javascript
function runBackupWorkflow_(mode) {
  const runLock = mode === 'manual' ? LockService.getDocumentLock() : null;

  if (runLock && !runLock.tryLock(1000)) {
    throw new Error('Another manual backup is already running.');
  }

  try {
    const backup = createBackup(); // { id, name, url }
    cleanupBackups();

    if (mode === 'manual') {
      writeManualBackupLog_(backup, new Date());
    }

    return backup;
  } catch (err) {
    sendBackupFailureAlert_(err, mode);
    throw err;
  } finally {
    if (runLock) runLock.releaseLock();
  }
}

function writeManualBackupLog_(backup, completedAt) {
  const sheet = SpreadsheetApp.getActive()
    .getSheetByName('Backup Log');

  if (!sheet) throw new Error('Backup Log sheet is required.');

  const logLock = LockService.getScriptLock();
  if (!logLock.tryLock(5000)) {
    throw new Error('Could not lock the Backup Log.');
  }

  try {
    const rows = sheet.getDataRange().getValues();
    const alreadyLogged = rows.some(row =>
      String(row[4]).trim() === String(backup.id).trim()
    );

    if (alreadyLogged) return;

    sheet.appendRow([
      completedAt,
      'MANUAL SUCCESS',
      backup.name,
      backup.url,
      backup.id
    ]);
  } finally {
    logLock.releaseLock();
  }
}
```

Ensure `createBackup()` returns `{ id: copiedFile.getId(), name: copiedFile.getName(), url: copiedFile.getUrl() }`; a second click is rejected while the first run is active rather than creating another copy.

Use a status-oriented layout: **Created Time | Last Updated | Status | File Name | File URL | File ID | Details**. Write `COPY CREATED` immediately, then update that same row after cleanup; if cleanup throws or times out, update it to `CLEANUP FAILED` with the error.

```javascript
function runBackupWorkflow_(mode) {
  const lock = mode === 'manual' ? LockService.getDocumentLock() : null;
  if (lock && !lock.tryLock(1000)) {
    throw new Error('Another manual backup is already running.');
  }

  let backup = null;

  try {
    backup = createBackup(); // { id, name, url }

    const rowNumber = upsertBackupLog_(
      backup,
      'COPY CREATED',
      '',
      new Date()
    );

    try {
      cleanupBackups();

      updateBackupLog_(
        rowNumber,
        'MANUAL SUCCESS',
        '',
        new Date()
      );
    } catch (cleanupError) {
      updateBackupLog_(
        rowNumber,
        'CLEANUP FAILED',
        cleanupError.message || String(cleanupError),
        new Date()
      );
      throw cleanupError;
    }

    return backup;
  } catch (err) {
    sendBackupFailureAlert_(err, mode);
    throw err;
  } finally {
    if (lock) lock.releaseLock();
  }
}

function upsertBackupLog_(backup, status, details, timestamp) {
  const sheet = SpreadsheetApp.getActive().getSheetByName('Backup Log');
  if (!sheet) throw new Error('Backup Log sheet is required.');

  const lock = LockService.getScriptLock();
  lock.waitLock(5000);

  try {
    const values = sheet.getDataRange().getValues();

    for (let i = 1; i < values.length; i++) {
      if (String(values[i][5]).trim() === String(backup.id).trim()) {
        return i + 1; // Existing file ID: do not create a duplicate row.
      }
    }

    sheet.appendRow([
      timestamp,
      timestamp,
      status,
      backup.name,
      backup.url,
      backup.id,
      details
    ]);

    return sheet.getLastRow();
  } finally {
    lock.releaseLock();
  }
}

function updateBackupLog_(rowNumber, status, details, timestamp) {
  const sheet = SpreadsheetApp.getActive().getSheetByName('Backup Log');
  const lock = LockService.getScriptLock();
  lock.waitLock(5000);

  try {
    sheet.getRange(rowNumber, 2, 1, 2).setValues([
      [timestamp, status]
    ]);
    sheet.getRange(rowNumber, 7).setValue(details);
  } finally {
    lock.releaseLock();
  }
}
```

The manual lock should still cover copy and cleanup, preventing concurrent backup files; a slow cleanup delays the toast, while a timeout produces a visible `CLEANUP FAILED` row even though the copied file remains recorded.

Use a distinct cleanup `catch` that logs and emails once, then returns a successful-copy result instead of throwing; the menu handler can show the appropriate toast:

```javascript
function onManualBackupMenu() {
  try {
    const result = runBackupWorkflow_('manual');

    SpreadsheetApp.getActive().toast(
      result.status === 'CLEANUP FAILED'
        ? 'Backup created, cleanup needs attention.'
        : 'Backup created successfully.'
    );
  } catch (err) {
    SpreadsheetApp.getActive().toast('Backup failed.');
    throw err;
  }
}

function runBackupWorkflow_(mode) {
  const lock = mode === 'manual' ? LockService.getDocumentLock() : null;

  if (lock && !lock.tryLock(1000)) {
    throw new Error('Another manual backup is already running.');
  }

  try {
    const backup = createBackup();

    const rowNumber = upsertBackupLog_(
      backup,
      'COPY CREATED',
      '',
      new Date()
    );

    try {
      cleanupBackups();

      updateBackupLog_(rowNumber, 'MANUAL SUCCESS', '', new Date());

      return {
        backup: backup,
        status: 'MANUAL SUCCESS'
      };
    } catch (cleanupError) {
      const details = cleanupError.message || String(cleanupError);

      updateBackupLog_(
        rowNumber,
        'CLEANUP FAILED',
        details,
        new Date()
      );

      // This is the only alert sent for a cleanup failure.
      sendCleanupFailureAlert_(backup, cleanupError);

      return {
        backup: backup,
        status: 'CLEANUP FAILED',
        details: details
      };
    }
  } catch (err) {
    // Only copy/logging failures reach this path.
    sendBackupFailureAlert_(err, mode);
    throw err;
  } finally {
    if (lock) lock.releaseLock();
  }
}
```

`sendCleanupFailureAlert_()` should identify the backup as created and include its file name, URL, and cleanup error, while `sendBackupFailureAlert_()` remains reserved for failures before the copy is safely recorded. This treats the backup as usable but clearly flags cleanup for follow-up.

Use a CSV exported or prepared from your Gmail verification list with columns `message_id,attachment_count` (one row per expected message), then run this script:

```python
#!/usr/bin/env python3
import csv, glob, mailbox, os, sys
from email import policy
from email.parser import BytesParser

def norm(x):
    return (x or "").strip().strip("<>").lower()

def read_msg(path):
    with open(path, "rb") as f:
        return BytesParser(policy=policy.default).parse(f)

def msg_id(msg):
    return norm(msg.get("Message-ID"))

def has_attachments(msg):
    return any(
        part.get_filename() or part.get_content_disposition() == "attachment"
        for part in msg.walk()
        if part.get_content_maintype() != "multipart"
    )

if len(sys.argv) != 4:
    print(f"Usage: {sys.argv[0]} export.mbox eml_directory gmail_manifest.csv")
    sys.exit(2)

mbox_path, eml_dir, manifest_path = sys.argv[1:]
expected = {}
with open(manifest_path, newline="", encoding="utf-8-sig") as f:
    for row in csv.DictReader(f):
        mid = norm(row["message_id"])
        if mid:
            expected[mid] = int(row.get("attachment_count", "0") or 0)

mb_ids, mb_dupes, mb_noattach = [], [], []
for msg in mailbox.mbox(mbox_path, factory=None):
    parsed = BytesParser(policy=policy.default).parsebytes(msg.as_bytes())
    mid = msg_id(parsed)
    if not mid:
        print("MBOX message with no Message-ID:", parsed.get("Subject", ""))
        continue
    if mid in mb_ids:
        mb_dupes.append(mid)
    mb_ids.append(mid)
    if expected.get(mid, 0) > 0 and not has_attachments(parsed):
        mb_noattach.append(mid)

eml_ids, eml_dupes = [], []
for path in sorted(glob.glob(os.path.join(eml_dir, "*.eml"))):
    msg = read_msg(path)
    mid = msg_id(msg)
    if not mid:
        print("EML with no Message-ID:", path)
        continue
    if mid in eml_ids:
        eml_dupes.append(mid)
    eml_ids.append(mid)

mb_set, eml_set, expected_set = set(mb_ids), set(eml_ids), set(expected)

print("\nMBOX messages:", len(mb_ids), " unique:", len(mb_set))
print("EML files:    ", len(eml_ids), " unique:", len(eml_set))
print("\nExpected but missing from MBOX:", *sorted(expected_set - mb_set), sep="\n  ")
print("\nExpected but missing EML:", *sorted(expected_set - eml_set), sep="\n  ")
print("\nIn MBOX but not expected:", *sorted(mb_set - expected_set), sep="\n  ")
print("\nIn EML folder but not expected:", *sorted(eml_set - expected_set), sep="\n  ")
print("\nDuplicate IDs in MBOX:", *sorted(set(mb_dupes)), sep="\n  ")
print("\nDuplicate IDs in EML files:", *sorted(set(eml_dupes)), sep="\n  ")
print("\nExpected attachments but none found in MBOX:", *sorted(set(mb_noattach)), sep="\n  ")
```

Run it with `python3 compare_mail.py export.mbox ./eml-files gmail_manifest.csv`; the script treats `Message-ID` case-insensitively and ignores surrounding angle brackets. Ensure the manifest’s attachment counts reflect Gmail’s record, since the `.mbox` itself cannot prove that an attachment was visible in Gmail if the MIME part is malformed or inline.

Use this version; it compares the manifest’s expected count with both the `.mbox` and matching `.eml`, and reports the `.eml` filename plus normalized `Message-ID` for every mismatch:

```python
#!/usr/bin/env python3
import csv
import glob
import mailbox
import os
import sys
from collections import defaultdict
from email import policy
from email.parser import BytesParser

def norm(value):
    return (value or "").strip().strip("<>").lower()

def parse_file(path):
    with open(path, "rb") as f:
        return BytesParser(policy=policy.default).parse(f)

def attachment_count(msg):
    return sum(
        1 for part in msg.walk()
        if part.get_content_maintype() != "multipart"
        and (
            part.get_filename() is not None
            or part.get_content_disposition() == "attachment"
        )
    )

if len(sys.argv) != 4:
    print(f"Usage: {sys.argv[0]} export.mbox eml_directory gmail_manifest.csv")
    sys.exit(2)

mbox_path, eml_dir, manifest_path = sys.argv[1:]

# Expected records from your Gmail verification list.
expected = {}
manifest_dupes = []

with open(manifest_path, newline="", encoding="utf-8-sig") as f:
    for row in csv.DictReader(f):
        mid = norm(row.get("message_id"))
        if not mid:
            continue

        count = int(row.get("attachment_count", "0") or 0)

        if mid in expected:
            manifest_dupes.append(mid)

        expected[mid] = count

# Store every MBOX occurrence, allowing duplicate IDs to be reported.
mbox_records = defaultdict(list)

for index, raw_msg in enumerate(mailbox.mbox(mbox_path, factory=None)):
    msg = BytesParser(policy=policy.default).parsebytes(raw_msg.as_bytes())
    mid = norm(msg.get("Message-ID"))

    if not mid:
        print(f"MBOX message {index} has no Message-ID")
        continue

    mbox_records[mid].append({
        "location": f"MBOX message {index}",
        "count": attachment_count(msg),
    })

# Store every EML occurrence, including its filename.
eml_records = defaultdict(list)

for path in sorted(glob.glob(os.path.join(eml_dir, "*.eml"))):
    msg = parse_file(path)
    mid = norm(msg.get("Message-ID"))

    if not mid:
        print(f"EML has no Message-ID: {path}")
        continue

    eml_records[mid].append({
        "location": path,
        "count": attachment_count(msg),
    })

mbox_ids = set(mbox_records)
eml_ids = set(eml_records)
expected_ids = set(expected)

print("MBOX messages:", sum(len(v) for v in mbox_records.values()))
print("MBOX unique IDs:", len(mbox_ids))
print("EML files:", sum(len(v) for v in eml_records.values()))
print("EML unique IDs:", len(eml_ids))

print("\nExpected but missing from MBOX:")
for mid in sorted(expected_ids - mbox_ids):
    print(f"  {mid}")

print("\nExpected but missing EML:")
for mid in sorted(expected_ids - eml_ids):
    print(f"  {mid}")

print("\nIn MBOX but not expected:")
for mid in sorted(mbox_ids - expected_ids):
    print(f"  {mid}")

print("\nIn EML folder but not expected:")
for mid in sorted(eml_ids - expected_ids):
    for record in eml_records[mid]:
        print(f"  {record['location']} | {mid}")

print("\nDuplicate IDs in MBOX:")
for mid, records in sorted(mbox_records.items()):
    if len(records) > 1:
        print(f"  {mid} ({len(records)} occurrences)")

print("\nDuplicate IDs in EML files:")
for mid, records in sorted(eml_records.items()):
    if len(records) > 1:
        print(f"  {mid}")
        for record in records:
            print(f"    {record['location']}")

print("\nAttachment-count mismatches:")
all_ids = expected_ids | mbox_ids | eml_ids

for mid in sorted(all_ids):
    expected_count = expected.get(mid)
    mbox_count = (
        mbox_records[mid][0]["count"]
        if mid in mbox_records else None
    )
    eml_entries = eml_records.get(mid, [])

    for eml in eml_entries or [{"location": "(no EML file)", "count": None}]:
        eml_count = eml["count"]

        counts = [x for x in (expected_count, mbox_count, eml_count)
                  if x is not None]

        if len(set(counts)) > 1:
            print(f"  Message-ID: {mid}")
            print(f"    EML file:        {eml['location']}")
            print(f"    Expected count:  {expected_count}")
            print(f"    MBOX count:      {mbox_count}")
            print(f"    EML count:       {eml_count}")
```

Run it as `python3 compare_mail.py export.mbox ./eml-files gmail_manifest.csv`; the count treats a MIME part as an attachment when it has a filename or `Content-Disposition: attachment`, so inline named files are counted too.

