Row | Status | Error | Workflow status | Primary reminded at | Backup escalated at
```

```javascript
const PRIMARY_COORDINATOR = 'primary@example.org';
const BACKUP_COORDINATOR = 'backup@example.org';
const PRIMARY_REMINDER_MINUTES = 15;
const BACKUP_ESCALATION_MINUTES = 30;

function setupAuditLog_() {
  const ss = SpreadsheetApp.getActiveSpreadsheet();
  let log = ss.getSheetByName('Alert audit log');

  const headers = [
    'Alert ID', 'Timestamp', 'Message type', 'Mode', 'Recipient',
    'Response sheet', 'Row', 'Status', 'Error', 'Workflow status',
    'Primary reminded at', 'Backup escalated at'
  ];

  if (!log) log = ss.insertSheet('Alert audit log');

  const existing = log.getLastColumn()
    ? log.getRange(1, 1, 1, log.getLastColumn()).getValues()[0]
    : [];

  headers.forEach(header => {
    if (!existing.includes(header)) {
      log.getRange(1, log.getLastColumn() + 1).setValue(header);
    }
  });

  const statusCol = headers.indexOf('Workflow status') + 1;
  const rule = SpreadsheetApp.newDataValidation()
    .requireValueInList(['Open', 'In progress', 'Resolved'], true)
    .setAllowInvalid(false)
    .build();

  if (log.getMaxRows() > 1) {
    log.getRange(2, statusCol, log.getMaxRows() - 1).setDataValidation(rule);
  }

  return log;
}

function processAlertEscalations() {
  const lock = LockService.getScriptLock();
  lock.waitLock(10000);

  try {
    const log = setupAuditLog_();
    const values = log.getDataRange().getValues();
    if (values.length < 2) return;

    const headers = values[0];
    const col = name => headers.indexOf(name);

    const now = new Date();

    for (let i = 1; i < values.length; i++) {
      const rowNumber = i + 1;
      const row = values[i];

      // Only process failed sends.
      if (String(row[col('Status')]).toLowerCase() !== 'error') continue;

      const workflowStatus =
        String(row[col('Workflow status')] || 'Open').trim();

      if (workflowStatus === 'Resolved') continue;

      const occurredAt = new Date(row[col('Timestamp')]);
      if (isNaN(occurredAt.getTime())) continue;

      const ageMinutes = (now - occurredAt) / 60000;
      const alertId = row[col('Alert ID')];
      const error = row[col('Error')] || '(no error recorded)';
      const timestamp = occurredAt.toISOString();

      // One-time primary reminder at 15 minutes.
      if (
        ageMinutes >= PRIMARY_REMINDER_MINUTES &&
        !row[col('Primary reminded at')]
      ) {
        // Claim before sending so overlapping triggers cannot duplicate it.
        log.getRange(rowNumber, col('Primary reminded at') + 1)
          .setValue(now);

        const body =
          `Alert ID: ${alertId}\n` +
          `Timestamp: ${timestamp}\n` +
          `Error: ${error}`;

        MailApp.sendEmail(
          PRIMARY_COORDINATOR,
          `Reminder: unresolved alert ${alertId}`,
          body
        );

        // Refresh the row after sending in case another process changed it.
        row[col('Primary reminded at')] = now;
      }

      // One-time backup escalation at 30 minutes.
      if (
        ageMinutes >= BACKUP_ESCALATION_MINUTES &&
        !row[col('Backup escalated at')]
      ) {
        // Recheck status immediately before escalation.
        const currentStatus = String(
          log.getRange(rowNumber, col('Workflow status') + 1).getValue() || 'Open'
        ).trim();

        if (currentStatus === 'Resolved') continue;

        log.getRange(rowNumber, col('Backup escalated at') + 1)
          .setValue(now);

        // Deliberately contains no volunteer contact details or report contents.
        const body =
          `Alert ID: ${alertId}\n` +
          `Timestamp: ${timestamp}\n` +
          `Error: ${error}`;

        MailApp.sendEmail(
          BACKUP_COORDINATOR,
          `Escalation: unresolved alert ${alertId}`,
          body
        );
      }
    }
  } finally {
    lock.releaseLock();
  }
}
```

Run `setupAuditLog_()` once, then create a time-driven trigger for `processAlertEscalations` every five minutes; because reminder/escalation timestamps are claimed before sending, a retry cannot normally send duplicates, though a crash after claiming may require clearing that timestamp manually.

Use separate **claim**, **success**, and **error** columns. Claims are short leases made under the script lock; `MailApp.sendEmail()` runs afterward, and failures clear the claim so the next five-minute run can retry.

```javascript
const PRIMARY_COORDINATOR = 'primary@example.org';
const BACKUP_COORDINATOR = 'backup@example.org';
const PRIMARY_REMINDER_MINUTES = 15;
const BACKUP_ESCALATION_MINUTES = 30;
const CLAIM_LEASE_MINUTES = 10;

function setupAuditLog_() {
  const ss = SpreadsheetApp.getActiveSpreadsheet();
  let log = ss.getSheetByName('Alert audit log');
  if (!log) log = ss.insertSheet('Alert audit log');

  const headers = [
    'Alert ID', 'Timestamp', 'Message type', 'Mode', 'Recipient',
    'Response sheet', 'Row', 'Status', 'Error', 'Workflow status',
    'Primary reminder claimed at', 'Primary reminded at',
    'Primary reminder error', 'Backup escalation claimed at',
    'Backup escalated at', 'Backup escalation error'
  ];

  const existing = log.getLastColumn()
    ? log.getRange(1, 1, 1, log.getLastColumn()).getValues()[0]
    : [];

  headers.forEach(header => {
    if (!existing.includes(header)) {
      log.getRange(1, log.getLastColumn() + 1).setValue(header);
    }
  });

  const statusCol = headers.indexOf('Workflow status') + 1;
  const rule = SpreadsheetApp.newDataValidation()
    .requireValueInList(['Open', 'In progress', 'Resolved'], true)
    .setAllowInvalid(false)
    .build();

  if (log.getMaxRows() > 1) {
    log.getRange(2, statusCol, log.getMaxRows() - 1)
      .setDataValidation(rule);
  }

  return log;
}

function processAlertEscalations() {
  const log = setupAuditLog_();
  const actions = claimWorkflowActions_(log);

  // No script lock is held during email delivery.
  actions.forEach(action => {
    let error = '';

    try {
      MailApp.sendEmail(action.recipient, action.subject, action.body);
    } catch (err) {
      error = err && err.message ? err.message : String(err);
    }

    finishWorkflowAction_(log, action, error);
  });
}

function claimWorkflowActions_(log) {
  const lock = LockService.getScriptLock();
  lock.waitLock(10000);

  try {
    const values = log.getDataRange().getValues();
    if (values.length < 2) return [];

    const headers = values[0];
    const col = name => headers.indexOf(name);
    const now = new Date();
    const actions = [];

    for (let i = 1; i < values.length; i++) {
      const sheetRow = i + 1;
      const row = values[i];

      if (String(row[col('Status')]).toLowerCase() !== 'error') continue;

      const workflowStatus =
        String(row[col('Workflow status')] || 'Open').trim();
      if (workflowStatus === 'Resolved') continue;

      const occurredAt = new Date(row[col('Timestamp')]);
      if (isNaN(occurredAt.getTime())) continue;

      const ageMinutes = (now - occurredAt) / 60000;
      const alertId = row[col('Alert ID')];
      const timestamp = occurredAt.toISOString();
      const error = row[col('Error')] || '(no error recorded)';
      const body =
        `Alert ID: ${alertId}\n` +
        `Timestamp: ${timestamp}\n` +
        `Error: ${error}`;

      // Claim only if there is no active lease.
      if (
        ageMinutes >= PRIMARY_REMINDER_MINUTES &&
        !row[col('Primary reminded at')] &&
        !isActiveClaim_(row[col('Primary reminder claimed at')], now)
      ) {
        log.getRange(
          sheetRow, col('Primary reminder claimed at') + 1
        ).setValue(now);

        actions.push({
          sheetRow,
          kind: 'primary',
          recipient: PRIMARY_COORDINATOR,
          subject: `Reminder: unresolved alert ${alertId}`,
          body
        });
      }

      if (
        ageMinutes >= BACKUP_ESCALATION_MINUTES &&
        !row[col('Backup escalated at')] &&
        !isActiveClaim_(row[col('Backup escalation claimed at')], now)
      ) {
        // Recheck status while holding the lock immediately before claiming.
        const currentStatus = String(
          log.getRange(sheetRow, col('Workflow status') + 1)
            .getValue() || 'Open'
        ).trim();

        if (currentStatus !== 'Resolved') {
          log.getRange(
            sheetRow, col('Backup escalation claimed at') + 1
          ).setValue(now);

          actions.push({
            sheetRow,
            kind: 'backup',
            recipient: BACKUP_COORDINATOR,
            subject: `Escalation: unresolved alert ${alertId}`,
            body
          });
        }
      }
    }

    return actions;
  } finally {
    lock.releaseLock();
  }
}

function finishWorkflowAction_(log, action, error) {
  const lock = LockService.getScriptLock();
  lock.waitLock(10000);

  try {
    const headers = log.getRange(1, 1, 1, log.getLastColumn())
      .getValues()[0];
    const col = name => headers.indexOf(name);
    const now = new Date();

    const successCol = action.kind === 'primary'
      ? 'Primary reminded at'
      : 'Backup escalated at';

    const errorCol = action.kind === 'primary'
      ? 'Primary reminder error'
      : 'Backup escalation error';

    // Clear the claim in either case. Errors remain retryable.
    const claimCol = action.kind === 'primary'
      ? 'Primary reminder claimed at'
      : 'Backup escalation claimed at';

    log.getRange(action.sheetRow, col(claimCol) + 1).clearContent();

    if (error) {
      log.getRange(action.sheetRow, col(errorCol) + 1)
        .setValue(`${now.toISOString()}: ${error}`);
    } else {
      log.getRange(action.sheetRow, col(successCol) + 1)
        .setValue(now);
      log.getRange(action.sheetRow, col(errorCol) + 1).clearContent();
    }
  } finally {
    lock.releaseLock();
  }
}

function isActiveClaim_(value, now) {
  if (!value) return false;

  const claimedAt = new Date(value);
  if (isNaN(claimedAt.getTime())) return false;

  return ((now - claimedAt) / 60000) < CLAIM_LEASE_MINUTES;
}
```

A crash after claiming will therefore become retryable automatically after the ten-minute lease expires; successful sends receive a permanent timestamp, while failed sends retain the error and are retried on a later run.

