When an attempt reaches three failures, set its review flag to `TRUE` and notify the primary coordinator once, using the existing claim/lock pattern:

```javascript
function notifyManualReview_(log, action, attempts, error) {
  const headers = log.getRange(1, 1, 1, log.getLastColumn()).getValues()[0];
  const col = name => headers.indexOf(name);

  const notifiedCol = action.kind === 'primary'
    ? 'Primary manual review notified at'
    : 'Backup manual review notified at';

  const reviewCol = action.kind === 'primary'
    ? 'Primary reminder needs manual review'
    : 'Backup escalation needs manual review';

  const notifiedCell = log.getRange(action.sheetRow, col(notifiedCol) + 1);
  if (notifiedCell.getValue()) return;

  log.getRange(action.sheetRow, col(reviewCol) + 1).setValue(true);
  notifiedCell.setValue(new Date());

  MailApp.sendEmail(
    PRIMARY_COORDINATOR,
    `Manual review required: alert ${action.alertId}`,
    `Alert ID: ${action.alertId}\n` +
    `Delivery path: ${action.kind}\n` +
    `Failed attempts: ${attempts}\n` +
    `Latest error: ${error}\n\n` +
    `Please inspect the audit entry, retry once by hand if appropriate, ` +
    `and record the final outcome and notes in the audit log.`
  );
}
```

