Claim the notification under the lock, send outside it, then record success or clear the claim for retry:

```javascript
function notifyManualReviewSafely_(log, action, attempts, latestError) {
  const h = log.getRange(1, 1, 1, log.getLastColumn()).getValues()[0];
  const col = name => h.indexOf(name);
  const prefix = action.kind === 'primary'
    ? 'Primary manual review'
    : 'Backup manual review';

  const claimCol = col(`${prefix} notification claimed at`);
  const sentCol = col(`${prefix} notified at`);
  const errorCol = col(`${prefix} notification error`);
  const row = action.sheetRow;
  const now = new Date();

  const lock = LockService.getScriptLock();
  lock.waitLock(10000);
  let claimed = false;

  try {
    const sent = log.getRange(row, sentCol + 1).getValue();
    const claim = log.getRange(row, claimCol + 1).getValue();

    if (!sent && !isActiveClaim_(claim, now)) {
      log.getRange(row, claimCol + 1).setValue(now);
      claimed = true;
    }
  } finally {
    lock.releaseLock();
  }

  if (!claimed) return; // Already sent or being handled by another run.

  const alertId = log.getRange(row, col('Alert ID') + 1).getValue();
  let sendError = '';

  try {
    MailApp.sendEmail(
      PRIMARY_COORDINATOR,
      `Manual review required: alert ${alertId}`,
      `Alert ID: ${alertId}\n` +
      `Delivery path: ${action.kind}\n` +
      `Failed attempts: ${attempts}\n` +
      `Latest error: ${latestError}\n\n` +
      `Inspect the audit entry, retry once manually if appropriate, ` +
      `and record the final outcome.`
    );
  } catch (err) {
    sendError = err && err.message ? err.message : String(err);
  }

  const finishLock = LockService.getScriptLock();
  finishLock.waitLock(10000);
  try {
    log.getRange(row, claimCol + 1).clearContent();

    if (sendError) {
      log.getRange(row, errorCol + 1)
        .setValue(`${new Date().toISOString()}: ${sendError}`);
    } else {
      log.getRange(row, sentCol + 1).setValue(new Date());
      log.getRange(row, errorCol + 1).clearContent();
    }
  } finally {
    finishLock.releaseLock();
  }
}
```

Call this only when the attempt count first reaches three, after setting the relevant manual-review flag; the claim prevents concurrent duplicate sends, while the lease makes a crashed run retryable. Create a separate **Manual review** sheet with `Alert ID | Delivery path | Outcome | Notes | Coordinator initials | Closed at`; use outcome values such as `Retried successfully`, `Retried unsuccessfully`, `No retry needed`, and `Closed`.

Create the sheet and apply an “open items” filter that hides only rows marked **Closed**:

```javascript
const MANUAL_REVIEW_OUTCOMES = [
  'Pending',
  'Retried successfully',
  'Retried unsuccessfully',
  'No retry needed',
  'Closed'
];

function setupManualReviewSheet_() {
  const ss = SpreadsheetApp.getActiveSpreadsheet();
  let sheet = ss.getSheetByName('Manual review');
  if (!sheet) sheet = ss.insertSheet('Manual review');

  const headers = [
    'Alert ID', 'Delivery path', 'Audit entry', 'Outcome',
    'Notes', 'Coordinator initials', 'Closed at'
  ];

  sheet.getRange(1, 1, 1, headers.length).setValues([headers]);

  const outcomeCol = headers.indexOf('Outcome') + 1;
  const rule = SpreadsheetApp.newDataValidation()
    .requireValueInList(MANUAL_REVIEW_OUTCOMES, true)
    .setAllowInvalid(false)
    .build();

  sheet.getRange(2, outcomeCol, sheet.getMaxRows() - 1)
    .setDataValidation(rule);

  if (sheet.getFilter()) sheet.getFilter().remove();

  const filter = sheet.getRange(
    1, 1, Math.max(sheet.getLastRow(), 1), headers.length
  ).createFilter();

  // Shows blank and all non-Closed outcomes.
  filter.setColumnFilterCriteria(
    outcomeCol,
    SpreadsheetApp.newFilterCriteria()
      .setHiddenValues(['Closed'])
      .build()
  );

  sheet.setFrozenRows(1);
  sheet.autoResizeColumns(1, headers.length);
  return sheet;
}

function addManualReviewRow_(alertId, deliveryPath, auditRow) {
  const sheet = setupManualReviewSheet_();
  const ss = SpreadsheetApp.getActiveSpreadsheet();
  const audit = ss.getSheetByName('Alert audit log');
  const row = sheet.getLastRow() + 1;
  const auditUrl =
    `${ss.getUrl()}#gid=${audit.getSheetId()}&range=A${auditRow}`;

  sheet.getRange(row, 1, 1, 7).setValues([[
    alertId,
    deliveryPath,
    `=HYPERLINK("${auditUrl}","Open audit entry")`,
    'Pending',
    '',
    '',
    ''
  ]]);
}
```

Call `addManualReviewRow_(alertId, action.kind, action.sheetRow)` when the relevant path first reaches three failed attempts; the link exposes only the controlled audit entry, so keep both sheets permission-restricted and avoid copying volunteer contact fields into the Manual review sheet.

